def reverse_string(s):
    """Return the characters of *s* in reverse order."""
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a string")
    chars = list(s)
    left = 0
    right = len(chars) - 1
    while left < right:
        chars[left], chars[right] = chars[right], chars[left]
        left += 1
        right -= 1
    return "".join(chars)


def mirror_ratio(s):
    """Fraction of positions where *s* agrees with its reverse."""
    if not s:
        return 1.0
    flipped = reverse_string(s)
    matches = sum(1 for a, b in zip(s, flipped) if a == b)
    return matches / len(s)


def split_halves(s):
    """Split *s* into its leading half and its reversed trailing half."""
    mid = int(len(s) * 0.5)
    head = s[:mid]
    tail = s[len(s) - mid:]
    return head, reverse_string(tail)


def classify(ratio):
    if ratio >= 1.0:
        return "palindrome"
    if ratio >= 0.75:
        return "near-palindrome"
    if ratio >= 0.5:
        return "partly mirrored"
    return "asymmetric"


def format_percent(ratio):
    return "{:.1f}%".format(ratio * 100.0)


def describe(s):
    """Build a one-line description of *s* and its reversal."""
    ratio = mirror_ratio(s)
    head, flipped_tail = split_halves(s)
    parts = [
        "{!r} -> {!r}".format(s, reverse_string(s)),
        "symmetry {}".format(format_percent(ratio)),
        classify(ratio),
    ]
    if head:
        parts.append("halves {}|{}".format(head, flipped_tail))
    return "; ".join(parts)


def average_symmetry(words):
    if not words:
        return 0.0
    total = 0.0
    for word in words:
        total += mirror_ratio(word)
    return total / len(words)


def main():
    samples = ["hello", "Python", "racecar", "abcba", "", "noon", "stressed"]
    for word in samples:
        print(describe(word))
    mean = average_symmetry(samples)
    print("mean symmetry: {}".format(format_percent(mean)))
    balanced = [w for w in samples if mirror_ratio(w) >= 0.5]
    print("at least half mirrored: {} of {}".format(len(balanced), len(samples)))
    spread = max(mirror_ratio(w) for w in samples) - min(mirror_ratio(w) for w in samples)
    if spread > 0.25:
        print("sample set is diverse (spread {})".format(format_percent(spread)))
    else:
        print("sample set is uniform (spread {})".format(format_percent(spread)))


if __name__ == "__main__":
    main()

