VOWELS = frozenset("aeiou")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, case-insensitively."""
    return sum(1 for char in text.lower() if char in VOWELS)


def count_letters(text):
    return sum(1 for char in text if char.isalpha())


def vowel_ratio(text):
    """Fraction of the letters in text that are vowels (0.0 when there are none)."""
    letters = count_letters(text)
    if letters == 0:
        return 0.0
    return count_vowels(text) / letters


def classify_ratio(ratio):
    """Describe how vowel-heavy a piece of text is."""
    if ratio >= 0.75:
        return "extremely vowel-heavy"
    if ratio >= 0.5:
        return "vowel-heavy"
    if ratio >= 0.25:
        return "balanced"
    return "consonant-heavy"


def average_vowels_per_word(text):
    words = text.split()
    if not words:
        return 0.0
    return count_vowels(text) / len(words)


def longest_vowel_run(text):
    best = 0
    current = 0
    for char in text.lower():
        if char in VOWELS:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def syllables_per_word(text):
    """Rough syllable-per-word estimate based on vowel groups."""
    words = text.split()
    if not words:
        return 0.0
    groups = 0
    for word in words:
        previous_was_vowel = False
        for char in word.lower():
            is_vowel = char in VOWELS
            if is_vowel and not previous_was_vowel:
                groups += 1
            previous_was_vowel = is_vowel
    return groups / len(words)


def describe(text):
    ratio = vowel_ratio(text)
    lines = [
        "text: {!r}".format(text),
        "vowels: {}".format(count_vowels(text)),
        "letters: {}".format(count_letters(text)),
        "vowel share: {:.1f}% ({})".format(ratio * 100.0, classify_ratio(ratio)),
        "vowels per word: {:.2f}".format(average_vowels_per_word(text)),
        "longest vowel run: {}".format(longest_vowel_run(text)),
        "syllables per word (est.): {:.2f}".format(syllables_per_word(text)),
    ]
    return "\n".join(lines)


def main():
    samples = [
        "Hello World",
        "Python",
        "Queueing aeiou",
        "rhythm myths",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)
    overall = sum(vowel_ratio(sample) for sample in samples) / len(samples)
    verdict = "above" if overall > 0.4 else "at or below"
    print("mean vowel share: {:.2f} ({} the 0.4 mark)".format(overall, verdict))


if __name__ == "__main__":
    main()

