import math


def calculate_factorial(n):
    """Return n! for a non-negative integer n (0! is 1)."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def stirling_approximation(n):
    """Approximate n! with Stirling's formula, as a float."""
    if n == 0:
        return 1.0
    tau = 2.0 * math.pi
    exponent = n + 0.5
    log_value = 0.5 * math.log(tau) + exponent * math.log(n) - n
    if log_value > 700.0:
        return math.inf
    return math.exp(log_value)


def relative_error_percent(exact, approx):
    """Percentage by which approx misses the exact value."""
    if math.isinf(approx):
        return math.inf
    return abs(approx - float(exact)) / float(exact) * 100.0


def digit_count(value):
    """Number of decimal digits of a positive integer."""
    return len(str(value))


def combinations(n, k):
    """Binomial coefficient n choose k, built from factorials."""
    if k < 0 or k > n:
        return 0
    numerator = calculate_factorial(n)
    denominator = calculate_factorial(k) * calculate_factorial(n - k)
    return numerator // denominator


def poisson_probability(k, mean):
    """Probability of exactly k events for a Poisson process."""
    if mean <= 0.0:
        raise ValueError("mean must be positive")
    return math.exp(-mean) * mean ** k / calculate_factorial(k)


def format_report_row(n):
    exact = calculate_factorial(n)
    approx = stirling_approximation(n)
    error = relative_error_percent(exact, approx)
    shown = str(exact) if digit_count(exact) <= 12 else "{:.6e}".format(approx)
    return "{:>3} {:>20} {:>14.6e} {:>9.4f}%".format(n, shown, approx, error)


def main():
    print("  n                  n!     Stirling(n)    error")
    for n in (0, 1, 2, 5, 10, 20, 50):
        print(format_report_row(n))

    print()
    print("choose(10, 3) =", combinations(10, 3))
    print("choose(52, 5) =", combinations(52, 5))

    print()
    mean = 2.5
    total = 0.0
    for k in range(6):
        probability = poisson_probability(k, mean)
        total += probability
        print("P(X = {}) = {:.5f}".format(k, probability))
    print("cumulative through k=5: {:.5f}".format(total))
    print("remaining tail: {:.5f}".format(1.0 - total))


if __name__ == "__main__":
    main()

