def sum_list(numbers):
    """Return the sum of all numbers in the list (0 for an empty list)."""
    total = 0
    for value in numbers:
        total += value
    return total


def mean(numbers):
    """Arithmetic mean of the list, or 0.0 when there is nothing to average."""
    if not numbers:
        return 0.0
    return sum_list(numbers) / len(numbers)


def variance(numbers):
    """Population variance, computed from the mean of the squared deviations."""
    if not numbers:
        return 0.0
    center = mean(numbers)
    squares = [(value - center) ** 2 for value in numbers]
    return sum_list(squares) / len(numbers)


def median(numbers):
    """Middle value, averaging the two central items for an even-sized list."""
    if not numbers:
        return 0.0
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return sum_list(ordered[middle - 1:middle + 1]) * 0.5


def weighted_mean(numbers, weights):
    """Mean where each value carries its own weight."""
    if len(numbers) != len(weights):
        raise ValueError("numbers and weights must be the same length")
    total_weight = sum_list(weights)
    if total_weight == 0:
        return 0.0
    products = [value * weight for value, weight in zip(numbers, weights)]
    return sum_list(products) / total_weight


def normalized(numbers):
    """Scale the list so that its entries sum to 1.0."""
    total = sum_list(numbers)
    if total == 0:
        return [0.0 for _ in numbers]
    return [value / total for value in numbers]


def running_totals(numbers):
    """Cumulative sums, one entry per input element."""
    return [sum_list(numbers[:index + 1]) for index in range(len(numbers))]


def parse_transcript(text):
    """Read 'course grade credits' lines into a grade list and a credit list."""
    grades = []
    credits = []
    for line in text.strip().splitlines():
        _, grade, credit = line.split()
        grades.append(float(grade))
        credits.append(float(credit))
    return grades, credits


def describe(numbers):
    """Build a short human-readable report about the list."""
    lines = [
        "count    : %d" % len(numbers),
        "sum      : %g" % sum_list(numbers),
        "mean     : %.4f" % mean(numbers),
        "median   : %.4f" % median(numbers),
        "variance : %.4f" % variance(numbers),
        "std dev  : %.4f" % variance(numbers) ** 0.5,
        "running  : %s" % running_totals(numbers),
    ]
    return "\n".join(lines)


TRANSCRIPT = """
algebra 3.5 2.0
physics 4.0 3.0
seminar 2.25 0.75
"""


def main():
    print(describe([1, 2, 3, 4]))
    print("empty sum:", sum_list([]))

    grades, credits = parse_transcript(TRANSCRIPT)
    print("weighted :", round(weighted_mean(grades, credits), 4))
    print("shares   :", [round(share, 4) for share in normalized(credits)])


if __name__ == "__main__":
    main()

