def find_max(numbers):
    """Return the largest number in a non-empty list of integers."""
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


def find_min(numbers):
    """Return the smallest number in a non-empty list of integers."""
    smallest = numbers[0]
    for value in numbers[1:]:
        if value < smallest:
            smallest = value
    return smallest


def mean(numbers):
    """Arithmetic mean of the sample."""
    return sum(numbers) / len(numbers)


def median(numbers):
    """Median, averaging the two middle values for even-sized samples."""
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) * 0.5


def midrange(numbers):
    """Point halfway between the extremes."""
    return (find_min(numbers) + find_max(numbers)) * 0.5


def quantile(numbers, fraction):
    """Linearly interpolated quantile for a fraction in [0, 1]."""
    if fraction < 0.0:
        raise ValueError("fraction must not be negative")
    if fraction > 1.0:
        raise ValueError("fraction must not exceed one")
    ordered = sorted(numbers)
    position = fraction * (len(ordered) - 1)
    lower = int(position)
    upper = min(lower + 1, len(ordered) - 1)
    weight = position - lower
    return ordered[lower] * (1.0 - weight) + ordered[upper] * weight


