    """Collect the headline figures describing a sample."""
    return {
        "max": find_max(numbers),
        "min": find_min(numbers),
        "mean": mean(numbers),
        "median": median(numbers),
        "midrange": midrange(numbers),
        "lower quartile": quantile(numbers, 0.25),
        "upper quartile": quantile(numbers, 0.75),
    }


