WELL_MIXED_THRESHOLD = 0.75


def _validate(numbers):
    """Return the input as a list, rejecting anything that is not integral."""
    if isinstance(numbers, (str, bytes)):
        raise TypeError("filter_even expects a sequence of integers, not a string")
    values = list(numbers)
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("filter_even expects integers, got %r" % (value,))
    return values


def filter_even(numbers):
    """Return a new list holding only the even entries of numbers."""
    return [value for value in _validate(numbers) if value % 2 == 0]


def filter_odd(numbers):
    """Return a new list holding only the odd entries of numbers."""
    return [value for value in _validate(numbers) if value % 2 != 0]


def even_ratio(numbers):
    """Fraction of the list that is even; an empty list has ratio 0.0."""
    values = _validate(numbers)
    if not values:
        return 0.0
    return len(filter_even(values)) / float(len(values))


def mean(values):
    """Arithmetic mean of a non-empty numeric sequence."""
    items = list(values)
    if not items:
        raise ValueError("mean of an empty sequence is undefined")
    return sum(items) / float(len(items))


def balance_score(numbers):
    """1.0 when evens and odds are equally frequent, 0.0 at either extreme."""
    values = _validate(numbers)
    if not values:
        return 0.0
    half = 0.5
    deviation = abs(even_ratio(values) - half)
    return 1.0 - deviation / half


def format_report(label, numbers):
    """Build a one-line human readable summary for a single data set."""
    evens = filter_even(numbers)
    odds = filter_odd(numbers)
    percent = even_ratio(numbers) * 100.0
    parts = [
        "%-10s" % label,
        "evens=%s" % (evens,),
        "odds=%s" % (odds,),
        "even%%=%.1f" % percent,
        "balance=%.2f" % balance_score(numbers),
    ]
    if evens:
        parts.append("even mean=%.2f" % mean(evens))
    return "  ".join(parts)


def main():
    data_sets = [
        ("mixed", [1, 2, 3, 4, 5]),
        ("odds", [7, 9, 11]),
        ("empty", []),
        ("negatives", [-8, -3, 0, 6, 15]),
        ("wide", list(range(1, 13))),
    ]
    for label, numbers in data_sets:
        print(format_report(label, numbers))

    scores = [balance_score(pair[1]) for pair in data_sets]
    print("average balance: %.3f" % mean(scores))
    well_mixed = [pair[0] for pair, score in zip(data_sets, scores)
                  if score >= WELL_MIXED_THRESHOLD]
    print("well mixed sets: %s" % (well_mixed or "none",))


if __name__ == "__main__":
    main()

