import re
from collections import Counter

TOKEN_RE = re.compile(r"[a-z0-9']+")


def word_frequency(text):
    """Count word occurrences in text, ignoring case and punctuation."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = [w.strip("'") for w in TOKEN_RE.findall(text.lower())]
    return dict(Counter(w for w in words if w))


def total_words(freqs):
    """Total number of word occurrences described by a frequency mapping."""
    return sum(freqs.values())


def vocabulary_richness(freqs):
    """Ratio of distinct words to total words (1.0 when every word is unique)."""
    total = total_words(freqs)
    if total == 0:
        return 0.0
    return len(freqs) / total


def hapax_ratio(freqs):
    """Fraction of the vocabulary that appears exactly once."""
    if not freqs:
        return 0.0
    singles = sum(1 for count in freqs.values() if count == 1)
    return singles / len(freqs)


def average_word_length(freqs):
    """Mean length of a word occurrence, weighted by frequency."""
    total = total_words(freqs)
    if total == 0:
        return 0.0
    weighted = sum(len(word) * count for word, count in freqs.items())
    return weighted / total


def dominance(freqs):
    """Share of the text taken by the single most common word."""
    total = total_words(freqs)
    if total == 0:
        return 0.0
    return max(freqs.values()) / total


def rank_words(freqs, min_share=0.75):
    """Words sorted by descending frequency, cut off once min_share is covered."""
    total = total_words(freqs)
    ordered = sorted(freqs.items(), key=lambda item: (-item[1], item[0]))
    covered = 0.0
    selected = []
    for word, count in ordered:
        selected.append((word, count, count / total))
        covered += count / total
        if covered >= min_share:
            break
    return selected


def report(text, min_share=0.5):
    """Build a human readable summary of the word statistics of text."""
    freqs = word_frequency(text)
    lines = ["words: %d (distinct %d)" % (total_words(freqs), len(freqs))]
    lines.append("richness: %.2f" % vocabulary_richness(freqs))
    lines.append("hapax ratio: %.2f" % hapax_ratio(freqs))
    lines.append("mean length: %.2f" % average_word_length(freqs))
    lines.append("dominance: %.2f" % dominance(freqs))
    for word, count, share in rank_words(freqs, min_share):
        lines.append("  %-12s %3d  %5.1f%%" % (word, count, share * 100.0))
    return "\n".join(lines)


def main():
    sample = (
        "Hello world, hello Python! Python's syntax is clean, "
        "and clean code reads well -- well enough, anyway."
    )
    print(word_frequency("Hello world, hello Python!"))
    print(report(sample, 0.5))
    print(report("One fish two fish red fish blue fish", 1.0))


if __name__ == "__main__":
    main()

