def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of floats."""
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        values.append(float(token))
    return values


def calculate_average(numbers):
    """Arithmetic mean of numbers; 0 for an empty list."""
    if not numbers:
        return 0
    total = 0.0
    for value in numbers:
        total += value
    return total / len(numbers)


def median(numbers):
    """Middle value, averaging the two central items for even lengths."""
    if not numbers:
        return 0
    ordered = sorted(numbers)
    count = len(ordered)
    middle = count // 2
    if count % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) * 0.5


def percentile(numbers, fraction):
    """Linear-interpolation percentile, fraction between 0.0 and 1.0."""
    if not numbers:
        return 0
    ordered = sorted(numbers)
    rank = (len(ordered) - 1) * fraction
    low = int(rank)
    high = min(low + 1, len(ordered) - 1)
    weight = rank - low
    return ordered[low] * (1.0 - weight) + ordered[high] * weight


def variance(numbers):
    """Sample variance; 0.0 when there is not enough data to spread."""
    count = len(numbers)
    if count < 2:
        return 0.0
    mean = calculate_average(numbers)
    squares = 0.0
    for value in numbers:
        squares += (value - mean) ** 2
    return squares / (count - 1)


def standard_deviation(numbers):
    return variance(numbers) ** 0.5


def spread_percent(numbers):
    """Standard deviation expressed as a percentage of the mean."""
    mean = calculate_average(numbers)
    if mean == 0:
        return 0.0
    return 100.0 * standard_deviation(numbers) / abs(mean)


def format_report(label, numbers):
    lines = ["%s (%d values)" % (label, len(numbers))]
    lines.append("  mean      : %.4f" % calculate_average(numbers))
    lines.append("  median    : %.4f" % median(numbers))
    lines.append("  lower qrt : %.4f" % percentile(numbers, 0.25))
    lines.append("  upper qrt : %.4f" % percentile(numbers, 0.75))
    lines.append("  std dev   : %.4f" % standard_deviation(numbers))
    lines.append("  spread    : %.2f%%" % spread_percent(numbers))
    return "\n".join(lines)


def main():
    print(format_report("integers", [10, 20, 30]))
    print(format_report("parsed", parse_numbers("1.5, 2.5, 4, 8, 16")))
    print(format_report("empty", []))
    print("calculate_average([10, 20, 30]) =", calculate_average([10, 20, 30]))
    print("calculate_average([]) =", calculate_average([]))


if __name__ == "__main__":
    main()

