"""Basic arithmetic calculator with expression parsing and a tiny CLI."""
import sys

OPS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}
ALIASES = {'x': '*', 'X': '*', ':': '/'}


def parse_number(token):
    """Turn a textual operand into an int or float ('12%' -> 0.12)."""
    text = token.strip()
    if text.endswith('%'):
        return parse_number(text[:-1]) / 100.0
    try:
        return int(text)
    except ValueError:
        return float(text)


def normalize_operator(token):
    op = ALIASES.get(token.strip(), token.strip())
    if op not in OPS:
        raise ValueError('unsupported operator: %r' % token.strip())
    return op


def simple_calculator(num1, operator, num2):
    op = normalize_operator(operator)
    if op == '/' and num2 == 0.0:
        return 'Error'
    return OPS[op](num1, num2)


def parse_expression(text):
    parts = text.split()
    if len(parts) != 3:
        raise ValueError('expected "number operator number", got %r' % text.strip())
    return parse_number(parts[0]), normalize_operator(parts[1]), parse_number(parts[2])


def format_result(value):
    if value == 'Error':
        return 'Error'
    if isinstance(value, int):
        return str(value)
    nearest = round(value)
    if abs(value - nearest) < 0.000001:
        return str(int(nearest))
    if abs(value) >= 1000.0:
        return format(value, ',.2f')
    if abs(value) < 0.001:
        return format(value, '.3e')
    return format(value, 'g')


def evaluate_line(text):
    try:
        num1, op, num2 = parse_expression(text)
    except ValueError as exc:
        return None, str(exc)
    return simple_calculator(num1, op, num2), None


def summarize(results):
    total = len(results)
    if not total:
        return 'nothing evaluated'
    errors = sum(1 for value in results if value == 'Error')
    numeric = [value for value in results if value != 'Error']
    share = errors / total * 100.0
    mean = sum(numeric) / len(numeric) if numeric else 0.0
    return '%d expression(s), %d error(s) (%.1f%%), mean = %s' % (
        total, errors, share, format_result(mean))


def main(argv):
    args = argv[1:]
    if args:
        lines = [' '.join(args)]
    else:
        lines = [line for line in sys.stdin.read().splitlines() if line.strip()]
    results = []
    for line in lines:
        value, problem = evaluate_line(line)
        if problem is not None:
            print('%s -> %s' % (line.strip(), problem))
            continue
        results.append(value)
        print('%s = %s' % (line.strip(), format_result(value)))
    print(summarize(results))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

