        return None, str(exc)
    return simple_calculator(num1, op, num2), None


def summarize(results):
    total = len(results)
    if not total:
        return 'nothing evaluated'
    errors = sum(1 for value in results if value == 'Error')
    numeric = [value for value in results if value != 'Error']
    share = errors / total * 100.
    mean = sum(numeric) / len(numeric) if numeric else 0.
    return '%d expression(s), %d error(s) (%.1f%%), mean = %s' % (
        total, errors, share, format_result(mean))


def main(argv):
    args = argv[1:]
    if args:
        lines = [' '.join(args)]
    else:
        lines = [line for line in sys.stdin.read().splitlines() if line.strip()]
    results = []
    for line in lines:
        value, problem = evaluate_line(line)
        if problem is not None:
            print('%s -> %s' % (line.strip(), problem))
            continue
        results.append(value)
        print('%s = %s' % (line.strip(), format_result(value)))
    print(summarize(results))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

