import math


def is_prime(n):
    """Return True if the positive integer n is prime."""
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    limit = int(n ** 0.5)
    step = 5
    while step <= limit:
        if n % step == 0 or n % (step + 2) == 0:
            return False
        step += 6
    return True


def primes_upto(limit):
    """All primes <= limit, found with a sieve of Eratosthenes."""
    if limit < 2:
        return []
    flags = bytearray([1]) * (limit + 1)
    flags[0] = flags[1] = 0
    for base in range(2, int(limit ** 0.5) + 1):
        if flags[base]:
            flags[base * base::base] = bytearray(len(flags[base * base::base]))
    return [i for i, ok in enumerate(flags) if ok]


def nth_prime(k):
    """The k-th prime (1-indexed), located by sieving a safe upper bound."""
    if k < 1:
        raise ValueError("k must be at least 1")
    if k < 6:
        bound = 15
    else:
        bound = int(k * (math.log(k) + math.log(math.log(k))) * 1.25)
    return primes_upto(bound)[k - 1]


def gap_stats(primes):
    """Average and largest gap between consecutive primes in the list."""
    if len(primes) < 2:
        return 0.0, 0
    gaps = [b - a for a, b in zip(primes, primes[1:])]
    return sum(gaps) / len(gaps), max(gaps)


def density_report(limit):
    """Compare the real prime count below limit with the n/ln(n) estimate."""
    primes = primes_upto(limit)
    count = len(primes)
    percent = 100.0 * count / limit
    estimate = limit / math.log(limit)
    ratio = count / estimate
    deviation = abs(ratio - 1.0)
    verdict = "close" if deviation <= 0.25 else "off"
    average_gap, widest = gap_stats(primes)
    return ("%d primes below %d (%.2f%% of numbers); estimate %.1f, ratio "
            "%.3f (%s); average gap %.2f, widest gap %d"
            % (count, limit, percent, estimate, ratio, verdict,
               average_gap, widest))


def main():
    for value in (7, 10, 1, 97, 561):
        print("is_prime(%d) -> %s" % (value, is_prime(value)))
    print("1000th prime:", nth_prime(1000))
    print(density_report(10000))
    twins = [(p, p + 2) for p in primes_upto(200) if is_prime(p + 2)]
    print("twin primes below 200:", twins)


if __name__ == "__main__":
    main()

