ABSOLUTE_ZERO_C = -273.15
FAHRENHEIT_OFFSET = 32.0
FAHRENHEIT_RATIO = 1.8
HALF_STEPS_PER_DEGREE = 2.0


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return _as_number(celsius) * FAHRENHEIT_RATIO + FAHRENHEIT_OFFSET


def fahrenheit_to_celsius(fahrenheit):
    """Convert a Fahrenheit temperature back to Celsius."""
    return (_as_number(fahrenheit) - FAHRENHEIT_OFFSET) / FAHRENHEIT_RATIO


def celsius_to_kelvin(celsius):
    """Convert a Celsius temperature to Kelvin."""
    return _as_number(celsius) + 273.15


def _as_number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("temperature must be a real number, got %r" % (value,))
    return float(value)


def parse_temperature(text):
    """Read a string like '21.5 C' or '-40F' and return the Celsius value."""
    cleaned = text.strip().upper().replace("DEGREES", "").replace("°", "")
    if cleaned.endswith("F"):
        return fahrenheit_to_celsius(float(cleaned[:-1]))
    if cleaned.endswith("C"):
        return float(cleaned[:-1])
    return float(cleaned)


def round_to_nearest_half(value):
    """Round a temperature to the closest half degree."""
    steps = round(value * HALF_STEPS_PER_DEGREE)
    return steps / HALF_STEPS_PER_DEGREE


def describe(celsius):
    """Return a short human description of a Celsius temperature."""
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError("temperature below absolute zero")
    if celsius <= 0.0:
        return "freezing"
    if celsius < 15.0:
        return "cold"
    if celsius < 25.5:
        return "mild"
    if celsius < 32.5:
        return "warm"
    return "hot"


def conversion_table(start, stop, step=12.5):
    """Build rows of (celsius, fahrenheit, kelvin) from start to stop."""
    if step <= 0.0:
        raise ValueError("step must be positive")
    rows = []
    current = _as_number(start)
    limit = _as_number(stop)
    while current <= limit + 1e-9:
        rows.append((current, celsius_to_fahrenheit(current), celsius_to_kelvin(current)))
        current += step
    return rows


def format_row(celsius, fahrenheit, kelvin):
    return "%8.2f C = %8.2f F = %8.2f K  (%s)" % (
        celsius, fahrenheit, kelvin, describe(celsius))


def main():
    print("celsius_to_fahrenheit(0)  ->", celsius_to_fahrenheit(0))
    print("celsius_to_fahrenheit(25) ->", celsius_to_fahrenheit(25))
    table_stop = 50.0
    for row in conversion_table(-25.0, table_stop):
        print(format_row(*row))
    for reading in ["21.5 C", "-40F", "98.6 F", "0.75"]:
        celsius = round_to_nearest_half(parse_temperature(reading))
        print("%-8s -> %6.1f C -> %6.1f F" % (
            reading, celsius, celsius_to_fahrenheit(celsius)))


if __name__ == "__main__":
    main()

