import string


def tokenize(sentence):
    """Split a sentence into bare words, dropping surrounding punctuation."""
    words = []
    for raw in sentence.split():
        word = raw.strip(string.punctuation)
        if word:
            words.append(word)
    return words


def find_longest_word(sentence):
    """Return the first longest word of the sentence ('' for no words)."""
    longest = ''
    for word in tokenize(sentence):
        if len(word) > len(longest):
            longest = word
    return longest


def average_word_length(words):
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def rounded_half_up(value):
    """Round a non-negative length to the nearest integer, .5 going up."""
    return int(value + 0.5)


def dominance(longest, words):
    """How many times longer the longest word is than the average word."""
    average = average_word_length(words)
    if average <= 0.0:
        return 0.0
    return len(longest) / average


def describe_dominance(ratio):
    if ratio >= 2.25:
        return 'towering'
    if ratio >= 1.5:
        return 'prominent'
    return 'typical'


def long_word_share(words, limit):
    if not words:
        return 0.0
    long_words = [word for word in words if len(word) >= limit]
    return len(long_words) / len(words)


def complexity_score(longest, words):
    """Blend average and peak word length into a single figure."""
    peak_weight = 0.25
    blended = peak_weight * len(longest)
    blended += (1.0 - peak_weight) * average_word_length(words)
    return blended


def report(sentence):
    words = tokenize(sentence)
    longest = find_longest_word(sentence)
    if not longest:
        return 'no words found in %r' % sentence
    average = average_word_length(words)
    limit = rounded_half_up(average + 1.0)
    share = 100.0 * long_word_share(words, limit)
    ratio = dominance(longest, words)
    return (
        '%r -> longest %r (%d letters), average %.2f, '
        '%s (x%.2f), %.1f%% of words reach %d letters, complexity %.2f'
        % (sentence, longest, len(longest), average,
           describe_dominance(ratio), ratio, share, limit,
           complexity_score(longest, words))
    )


def main():
    samples = [
        'The quick brown fox',
        'Hello world',
        'Extraordinary discoveries need careful, patient verification.',
        'a bb ccc',
        '   ',
    ]
    for sample in samples:
        print(report(sample))


if __name__ == '__main__':
    main()

