def fibonacci_sequence(n):
    """Return the first n Fibonacci numbers, starting with 0 and 1."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    sequence = []
    current, following = 0, 1
    for _ in range(n):
        sequence.append(current)
        current, following = following, current + following
    return sequence


def golden_ratio():
    """The limit of the ratio between consecutive Fibonacci numbers."""
    root_five = 5 ** .5
    return (1 + root_five) / 2.


def consecutive_ratios(sequence):
    """Ratios term[i] / term[i-1] for every predecessor that is not zero."""
    ratios = []
    for index in range(1, len(sequence)):
        previous = sequence[index - 1]
        if previous != 0:
            ratios.append(sequence[index] / float(previous))
    return ratios


def relative_errors(ratios, limit):
    """Distance of each ratio from the limit, expressed in percent."""
    return [100. * abs(ratio - limit) / limit for ratio in ratios]


def convergence_index(errors, tolerance=.75):
    """Position of the first ratio whose error stays under the tolerance."""
    for index, error in enumerate(errors):
        if error < tolerance:
            return index
    return None


def binet_estimate(index):
    """Closed-form value of the Fibonacci number at the given index."""
    phi = golden_ratio()
    root_five = 5 ** .5
    raw = (phi ** index - (-1 / phi) ** index) / root_five
    return int(raw + .5)


def report(n):
    """Build printable lines comparing the sequence with its growth rate."""
    sequence = fibonacci_sequence(n)
    phi = golden_ratio()
    ratios = consecutive_ratios(sequence)
    errors = relative_errors(ratios, phi)
    lines = ["first %d terms: %s" % (n, sequence)]
    lines.append("golden ratio: %.6f" % phi)
    for offset, (ratio, error) in enumerate(zip(ratios, errors)):
        step = offset + 2
        marker = "*" if error < 1. else " "
        lines.append("%s index %2d  ratio %8.5f  error %7.3f%%" % (marker, step, ratio, error))
    settled = convergence_index(errors)
    if settled is None:
        lines.append("ratios never settle within 0.75% for this length")
    else:
        lines.append("ratios settle from index %d onward" % (settled + 2))
    mismatch = [k for k in range(n) if binet_estimate(k) != sequence[k]]
    lines.append("closed form agrees on %d of %d terms" % (n - len(mismatch), n))
    return lines


def main():
    for line in report(12):
        print(line)
    print("fibonacci_sequence(1) -> %s" % fibonacci_sequence(1))
    print("fibonacci_sequence(5) -> %s" % fibonacci_sequence(5))


if __name__ == "__main__":
    main()

