import os
import sys


def count_lines_in_file(filepath):
    """Return the number of lines in the file at filepath."""
    total = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for _line in handle:
            total += 1
    return total


def count_blank_lines(filepath):
    """Return the number of lines that hold nothing but whitespace."""
    blank = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            if not line.strip():
                blank += 1
    return blank


def average_line_length(filepath):
    """Mean number of characters per line, newline excluded."""
    lines = count_lines_in_file(filepath)
    if lines == 0:
        return 0.0
    characters = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            characters += len(line.rstrip("\n"))
    return characters / lines


def file_size_kb(filepath):
    """Size of the file in kilobytes."""
    return os.path.getsize(filepath) / 1024.0


def blank_ratio(filepath):
    lines = count_lines_in_file(filepath)
    if lines == 0:
        return 0.0
    return count_blank_lines(filepath) / lines


def describe_density(ratio):
    if ratio >= 0.5:
        return "mostly empty"
    if ratio >= 0.25:
        return "airy"
    if ratio >= 0.05:
        return "compact"
    return "dense"


def estimate_pages(filepath, lines_per_page=60.0):
    """Number of printed pages the file would fill, as a fraction."""
    return count_lines_in_file(filepath) / lines_per_page


def format_report(filepath):
    lines = count_lines_in_file(filepath)
    ratio = blank_ratio(filepath)
    pages = estimate_pages(filepath)
    rows = [
        "file: %s" % filepath,
        "lines: %d" % lines,
        "blank lines: %d (%.1f%%)" % (count_blank_lines(filepath), ratio * 100.0),
        "average line length: %.2f characters" % average_line_length(filepath),
        "size: %.3f KB" % file_size_kb(filepath),
        "layout: %s" % describe_density(ratio),
        "pages: %.2f" % pages,
    ]
    if pages > 0.75:
        rows.append("note: longer than three quarters of a page")
    return "\n".join(rows)


def main(argv):
    targets = argv[1:] or [__file__]
    for index, target in enumerate(targets):
        if index > 0:
            print("")
        print(format_report(target))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

