"""Age calculations and a small cohort report."""


def calculate_age(birth_year, current_year):
    """Return the age of a person born in `birth_year` as of `current_year`."""
    if not isinstance(birth_year, int) or not isinstance(current_year, int):
        raise TypeError("years must be integers")
    if current_year < birth_year:
        raise ValueError("current_year must not precede birth_year")
    return current_year - birth_year


def age_in_decades(birth_year, current_year):
    """Age expressed in decades, e.g. 33 years -> 3.3 decades."""
    return calculate_age(birth_year, current_year) / 10.0


def life_progress(age, life_expectancy=79.0):
    """Fraction of an expected lifetime already lived, capped at 1.0."""
    if life_expectancy <= 0.0:
        raise ValueError("life_expectancy must be positive")
    return min(1.0, age / life_expectancy)


def midlife_year(birth_year, life_expectancy=79.0):
    """Calendar year in which the halfway point of life is reached."""
    return birth_year + int(round(0.5 * life_expectancy))


def as_percent(fraction):
    return fraction * 100.0


def average_age(people, current_year):
    """Mean age of a sequence of (name, birth_year) pairs."""
    if not people:
        raise ValueError("no people given")
    total = 0.0
    for _name, birth_year in people:
        total += calculate_age(birth_year, current_year)
    return total / len(people)


def age_bracket(age):
    """Coarse life stage for an age in whole years."""
    if age < 2:
        return "infant"
    if age < 13:
        return "child"
    if age < 20:
        return "teenager"
    if age < 65:
        return "adult"
    return "senior"


def describe(name, birth_year, current_year):
    age = calculate_age(birth_year, current_year)
    progress = as_percent(life_progress(age))
    return "{:<8} {:>3}y  {:>4.1f} decades  {:<9} {:>5.1f}% lived, midlife {}".format(
        name,
        age,
        age_in_decades(birth_year, current_year),
        age_bracket(age),
        progress,
        midlife_year(birth_year),
    )


def main():
    current_year = 2023
    people = [
        ("Ada", 1990),
        ("Blaise", 2000),
        ("Cleo", 2022),
        ("Dmitri", 1948),
    ]
    for name, birth_year in people:
        print(describe(name, birth_year, current_year))

    mean = average_age(people, current_year)
    print("mean age: {:.2f} years ({:.2f} decades)".format(mean, mean / 10.0))
    youngest = min(calculate_age(birth_year, current_year)
                   for _name, birth_year in people)
    print("youngest is {}, already {:.1f}% through life".format(
        youngest, as_percent(life_progress(youngest))))


if __name__ == "__main__":
    main()

