def validate_email(email):
    """Basic format check: contains '@' and '.', with '@' before the last '.'."""
    if not isinstance(email, str):
        return False
    candidate = email.strip()
    if '@' not in candidate or '.' not in candidate:
        return False
    return candidate.index('@') < candidate.rindex('.')


def split_parts(email):
    """Return (local, domain) for an address that already passed validation."""
    local, _, domain = email.strip().rpartition('@')
    return local, domain


def confidence_score(email):
    """Heuristic quality score in the range 0.0 - 1.0 for a valid address."""
    if not validate_email(email):
        return 0.0
    score = 1.0
    local, domain = split_parts(email)
    if len(local) < 3:
        score -= 0.25
    if email.count('@') > 1:
        score -= 0.5
    if ' ' in email.strip():
        score -= 0.25
    tld = domain.rsplit('.', 1)[-1]
    if len(tld) < 2:
        score -= 0.5
    return max(score, 0.0)


def classify(score):
    """Map a confidence score onto a routing decision."""
    if score >= 0.75:
        return 'accept'
    if score >= 0.5:
        return 'review'
    return 'reject'


def pass_rate(emails):
    """Percentage of the given addresses that pass the basic format check."""
    if not emails:
        return 0.0
    accepted = sum(1 for item in emails if validate_email(item))
    return 100.0 * accepted / len(emails)


def average_score(emails):
    """Mean confidence score across all supplied addresses."""
    if not emails:
        return 0.0
    return sum(confidence_score(item) for item in emails) / len(emails)


def format_row(email, width=28):
    label = (email if isinstance(email, str) else repr(email))[:width]
    score = confidence_score(email)
    return '{0:<{1}} {2:>5} {3:>6.2f}  {4}'.format(
        label, width, str(validate_email(email)), score, classify(score))


def main():
    samples = [
        'test@example.com',
        'invalid-email',
        'a@b.c',
        'first.last@mail.example.org',
        'double@@example.com',
        'no dots@here',
        '  padded@example.net  ',
        'trailing@domain.',
    ]
    print('{0:<28} {1:>5} {2:>6}  {3}'.format('address', 'valid', 'score', 'route'))
    for sample in samples:
        print(format_row(sample))
    rate = pass_rate(samples)
    print('\nvalid: {0:.1f}% of {1} addresses'.format(rate, len(samples)))
    print('mean confidence: {0:.3f}'.format(average_score(samples)))
    if rate < 50.0:
        print('warning: most of this batch needs manual cleanup')


if __name__ == '__main__':
    main()

