import math


def _validated(numbers):
    """Return the input as a list of floats, rejecting empty or non-positive data."""
    values = [float(value) for value in numbers]
    if not values:
        raise ValueError("geometric mean requires at least one number")
    for value in values:
        if value <= 0.0:
            raise ValueError("all numbers must be positive, got %r" % value)
    return values


def geometric_mean(numbers):
    """Nth root of the product of the N given positive numbers."""
    values = _validated(numbers)
    if len(values) == 2:
        return (values[0] * values[1]) ** 0.5
    log_sum = math.fsum(math.log(value) for value in values)
    return math.exp(log_sum / len(values))


def arithmetic_mean(numbers):
    values = _validated(numbers)
    return math.fsum(values) / len(values)


def harmonic_mean(numbers):
    values = _validated(numbers)
    total = math.fsum(1.0 / value for value in values)
    return len(values) / total


def geometric_interpolate(start, end, fraction):
    """Point a given fraction of the way from start to end on a log scale."""
    low, high = _validated([start, end])
    return low * (high / low) ** fraction


def average_growth_factor(series):
    """Geometric mean of the successive ratios of a series of measurements."""
    values = _validated(series)
    if len(values) < 2:
        raise ValueError("need at least two measurements to measure growth")
    ratios = [values[i + 1] / values[i] for i in range(len(values) - 1)]
    return geometric_mean(ratios)


def format_summary(label, numbers):
    geo = geometric_mean(numbers)
    ari = arithmetic_mean(numbers)
    har = harmonic_mean(numbers)
    return "%-16s geo=%8.4f  arith=%8.4f  harm=%8.4f  geo/arith=%6.4f" % (
        label, geo, ari, har, geo / ari)


def main():
    revenue = [
        100.0,
        112.5,
        126.0,
        141.75,
    ]
    datasets = [
        ("[2, 8]", [2, 8]),
        ("[1, 1, 1]", [1, 1, 1]),
        ("[4, 9, 16, 25]", [4, 9, 16, 25]),
        ("revenue", revenue),
    ]
    for label, numbers in datasets:
        print(format_summary(label, numbers))

    low = 1.0
    high = 16.0
    print("halfway 1 -> 16: %.4f" % geometric_interpolate(low, high, 0.5))
    print("three quarters:  %.4f" % geometric_interpolate(low, high, 0.75))

    factor = average_growth_factor(revenue)
    percent = (factor - 1.0) * 100
    print("average growth factor: %.6f (%.2f%% per period)" % (factor, percent))
    print("projected next value:  %.4f" % (revenue[-1] * factor))


if __name__ == "__main__":
    main()

