def update_inventory(inventory, item_name, quantity):
    """Add quantity to item_name in inventory, creating the entry if needed."""
    if not isinstance(item_name, str) or not item_name.strip():
        raise ValueError("item_name must be a non-empty string")
    key = item_name.strip().lower()
    inventory[key] = inventory.get(key, 0) + quantity
    return inventory


def apply_shipment(inventory, shipment):
    """Apply a sequence of (item_name, quantity) pairs to the inventory."""
    for item_name, quantity in shipment:
        update_inventory(inventory, item_name, quantity)
    return inventory


def parse_price_list(text):
    """Parse 'name=price' lines into a price table keyed like the inventory."""
    prices = {}
    for line in text.strip().splitlines():
        name, _, raw = line.partition("=")
        prices[name.strip().lower()] = float(raw)
    return prices


def stock_value(inventory, prices):
    """Total monetary value of the stock, ignoring items with no known price."""
    total = 0.0
    for item, quantity in inventory.items():
        total += prices.get(item, 0.0) * quantity
    return round(total, 2)


def reorder_list(inventory, thresholds, default_threshold=2.0):
    """Items whose stock has fallen to or below their reorder threshold."""
    low = []
    for item, quantity in sorted(inventory.items()):
        limit = thresholds.get(item, default_threshold)
        if quantity <= limit:
            low.append((item, round(limit - quantity, 2)))
    return low


def format_report(inventory, prices, thresholds):
    lines = ["ITEM         QTY     VALUE"]
    for item, quantity in sorted(inventory.items()):
        value = prices.get(item, 0.0) * quantity
        lines.append("{:<12} {:>5} {:>9.2f}".format(item, quantity, value))
    lines.append("{:<12} {:>5} {:>9.2f}".format("TOTAL", "", stock_value(inventory, prices)))
    shortfalls = reorder_list(inventory, thresholds)
    if shortfalls:
        lines.append("Reorder: " + ", ".join(
            "{} (+{:g})".format(item, gap) for item, gap in shortfalls))
    return "\n".join(lines)


def main():
    prices = parse_price_list("""
    apple = 0.50
    banana = 0.25
    flour = 1.75
    Olive Oil = 8.00
    """)
    thresholds = {"flour": 1.0}
    thresholds["olive oil"] = 0.75

    inventory = update_inventory({"apple": 10}, "apple", 5)
    print(inventory)
    print(update_inventory({"apple": 10}, "banana", 3))

    apply_shipment(inventory, [
        ("Banana", 12),
        ("flour", 2.25),
        ("olive oil", 0.5),
        ("banana", -4),
    ])
    update_inventory(inventory, "flour", -1.5)
    print(inventory)

    print(format_report(inventory, prices, thresholds))


if __name__ == "__main__":
    main()

