RESPONSES = ('Too high', 'Too low', 'Correct!')


def guess_number(secret_number, guess):
    """Compare a guess against the secret number."""
    if guess > secret_number:
        return RESPONSES[0]
    if guess < secret_number:
        return RESPONSES[1]
    return RESPONSES[2]


def warmth(secret_number, guess, low, high):
    """Return 1.0 for an exact hit, falling towards zero at the range edges."""
    span = max(secret_number - low, high - secret_number)
    if span <= 0:
        return 1.0
    distance = abs(secret_number - guess) / float(span)
    heat = 1.0 - distance
    return max(0.0, heat)


def hint(secret_number, guess, low, high):
    """Combine the plain verdict with a temperature word."""
    verdict = guess_number(secret_number, guess)
    if verdict == RESPONSES[2]:
        return verdict
    heat = warmth(secret_number, guess, low, high)
    if heat >= 0.75:
        temperature = 'boiling'
    elif heat >= 0.5:
        temperature = 'warm'
    elif heat >= 0.25:
        temperature = 'cool'
    else:
        temperature = 'freezing'
    return '{0} ({1})'.format(verdict, temperature)


def bisect_guesses(secret_number, low, high):
    """Play the game automatically, returning every (guess, hint) pair."""
    history = []
    while low <= high:
        guess = int((low + high) / 2.0)
        message = hint(secret_number, guess, low, high)
        history.append((guess, message))
        if message == RESPONSES[2]:
            break
        if message.startswith(RESPONSES[0]):
            high = guess - 1
        else:
            low = guess + 1
    return history


def efficiency(history, low, high):
    """Guesses used as a fraction of the worst case for the given range."""
    worst_case = 0
    width = high - low + 1
    while width > 0:
        worst_case += 1
        width = int(width / 2.0)
    return len(history) / float(worst_case)


def main():
    low, high = 1, 100
    for secret in (10, 1, 100, 63):
        history = bisect_guesses(secret, low, high)
        print('Secret {0}:'.format(secret))
        for attempt, (guess, message) in enumerate(history, start=1):
            print('  {0}. guessed {1} -> {2}'.format(attempt, guess, message))
        score = efficiency(history, low, high)
        print('  used {0:.2f} of the worst case'.format(score))
        if score <= 0.5:
            print('  (lucky run)')


if __name__ == '__main__':
    main()

