def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index rounded to two decimal places."""
    weight = _validate_positive(weight_kg, "weight_kg")
    height = _validate_positive(height_m, "height_m")
    return round(weight / (height ** 2), 2)


def _validate_positive(value, name):
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise TypeError("%s must be a number" % name)
    if number <= 0.0:
        raise ValueError("%s must be greater than zero" % name)
    return number


UNDERWEIGHT_LIMIT = 18.5
NORMAL_LIMIT = 25.0
OVERWEIGHT_LIMIT = 30.0


def bmi_category(bmi):
    """Classify a BMI value using the standard WHO cut-off points."""
    if bmi < UNDERWEIGHT_LIMIT:
        return "underweight"
    if bmi < NORMAL_LIMIT:
        return "normal weight"
    if bmi < OVERWEIGHT_LIMIT:
        return "overweight"
    return "obese"


def healthy_weight_range(height_m):
    """Return the weight interval (kg) matching a normal BMI for a height."""
    height = _validate_positive(height_m, "height_m")
    area = height ** 2
    low = UNDERWEIGHT_LIMIT * area
    high = NORMAL_LIMIT * area
    return round(low, 1), round(high, 1)


def weight_to_reach(weight_kg, height_m):
    """Kilograms to lose (negative) or gain (positive) to enter normal range."""
    weight = _validate_positive(weight_kg, "weight_kg")
    low, high = healthy_weight_range(height_m)
    if weight < low:
        return round(low - weight, 1)
    if weight > high:
        return round(high - weight, 1)
    return 0.0


def describe(weight_kg, height_m):
    """Build a one-line human readable report for a single person."""
    bmi = calculate_bmi(weight_kg, height_m)
    low, high = healthy_weight_range(height_m)
    delta = weight_to_reach(weight_kg, height_m)
    text = "%.1f kg at %.2f m -> BMI %.2f (%s)" % (
        weight_kg, height_m, bmi, bmi_category(bmi))
    text += "; healthy range %.1f-%.1f kg" % (low, high)
    if delta > 0.0:
        text += "; gain %.1f kg" % delta
    elif delta < 0.0:
        text += "; lose %.1f kg" % abs(delta)
    return text


def main():
    people = [
        (70, 1.75),
        (100, 2.0),
        (52, 1.68),
        (95, 1.62),
    ]
    for weight, height in people:
        print(describe(weight, height))


if __name__ == "__main__":
    main()

