def _normalize(operation):
    if isinstance(operation, str):
        return operation, None
    if not isinstance(operation, (tuple, list)) or len(operation) != 2:
        raise ValueError("each operation must be a (name, item) pair")
    name, item = operation
    return name, item


def simulate_queue(operations):
    queue = []
    for operation in operations:
        name, item = _normalize(operation)
        if name == "enqueue":
            queue.append(item)
        elif name == "dequeue":
            if queue:
                queue.pop(0)
        else:
            raise ValueError("unknown operation: %r" % (name,))
    return queue


def length_trace(operations):
    trace = []
    partial = []
    for operation in operations:
        partial.append(operation)
        trace.append(len(simulate_queue(partial)))
    return trace


def average_length(trace):
    if not trace:
        return .0
    total = .0
    for length in trace:
        total += length
    return total / len(trace)


def median_length(trace):
    if not trace:
        return .0
    ordered = sorted(trace)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) * .5


def dequeue_success_rate(operations):
    attempts = 0
    served = 0
    queue = []
    for operation in operations:
        name, item = _normalize(operation)
        if name == "enqueue":
            queue.append(item)
        else:
            attempts += 1
            if queue:
                queue.pop(0)
                served += 1
    if attempts == 0:
        return 1.
    return served / attempts


def describe_load(average, capacity):
    if capacity <= .0:
        return "undefined"
    ratio = average / capacity
    if ratio < .25:
        return "light"
    if ratio < .75:
        return "steady"
    return "heavy"


def format_report(label, operations, capacity=4.):
    final = simulate_queue(operations)
    trace = length_trace(operations)
    average = average_length(trace)
    lines = ["%s: final=%r" % (label, final)]
    lines.append("  peak=%d median=%.2f average=%.2f" % (max(trace or [0]), median_length(trace), average))
    lines.append("  served=%.0f%% load=%s" % (dequeue_success_rate(operations) * 100., describe_load(average, capacity)))
    return "\n".join(lines)


def main():
