        ("empty pop", [("dequeue", None)]),
        ("burst", [("enqueue", c) for c in "abcdef"] + [("dequeue", None)] * 2),
        ("alternating", [("enqueue", 9), "dequeue", ("enqueue", 8), "dequeue", ("enqueue", 7)]),
    ]
