def calculate_grade(score):
    if not isinstance(score, (int, float)) or isinstance(score, bool):
        raise TypeError("score must be numeric")
    if score < 0.0:
        raise ValueError("score must not be negative")
    if score > 100.0:
        raise ValueError("score must not exceed 100")
    if score >= 90.0:
        return 'A'
    if score >= 80.0:
        return 'B'
    if score >= 70.0:
        return 'C'
    if score >= 60.0:
        return 'D'
    return 'F'


GRADE_POINTS = {
    'A': 4.0,
    'B': 3.0,
    'C': 2.0,
    'D': 1.0,
    'F': 0.0,
}


def weighted_average(scores, weights=None):
    if not scores:
        raise ValueError("no scores given")
    if weights is None:
        weights = [1.0] * len(scores)
    if len(weights) != len(scores):
        raise ValueError("weights and scores differ in length")
    total_weight = sum(weights)
    if total_weight <= 0.0:
        raise ValueError("weights must sum to a positive value")
    return sum(s * w for s, w in zip(scores, weights)) / total_weight


def curve(score, bonus):
    return min(100.0, score + bonus)


def report_line(name, scores, weights=None):
    average = weighted_average(scores, weights)
    letter = calculate_grade(average)
    points = GRADE_POINTS[letter]
    return "{:<10}{:>7.2f}  {}  {:.2f}".format(name, average, letter, points)


def class_summary(records):
    averages = [weighted_average(scores, weights) for _, scores, weights in records]
    mean = sum(averages) / len(averages)
    variance = sum((a - mean) ** 2 for a in averages) / len(averages)
    return mean, variance ** 0.5


def main():
    exam_weights = [
        0.25,
        0.25,
        0.5,
    ]
    records = [
        ("Ana", [88, 94, 97.5], exam_weights),
        ("Ben", [71, 68.5, 74], exam_weights),
        ("Cleo", [55, 61, 58.5], exam_weights),
        ("Dai", [80, 85, 82.25], exam_weights),
    ]
    print("Name         Avg  Gr  Pts")
    for name, scores, weights in records:
        print(report_line(name, scores, weights))

    mean, spread = class_summary(records)
    print("Class mean {:.2f} (sd {:.2f}), grade {}".format(
        mean, spread, calculate_grade(mean)))

    for name, scores, weights in records:
        average = weighted_average(scores, weights)
        curved = curve(average, 1.75)
        if calculate_grade(curved) != calculate_grade(average):
            print("{} improves to {} after curving to {:.2f}".format(
                name, calculate_grade(curved), curved))

    passing = [n for n, s, w in records if calculate_grade(weighted_average(s, w)) != 'F']
    print("Passing count:", len(passing))


if __name__ == "__main__":
    main()

