        counts[ch] = counts.get(ch, 0) + 1
    return counts


def most_frequent_char(text):
    """Return the most frequent character, earliest one wins on ties."""
    best = None
    best_count = 0
    for ch, n in char_counts(text).items():
        if n > best_count:
            best = ch
            best_count = n
    return best


def relative_frequency(text):
    """Map each counted character to its share of all counted characters."""
    counts = char_counts(text)
    total = sum(counts.values())
    if total == 0:
        return {}
    return {ch: n / total for ch, n in counts.items()}


def classify(ratio):
    """Describe how strongly a character dominates the text."""
    if ratio >= 0.5:
