TROPICAL_YEAR = 365.2422
JULIAN_YEAR = 365.25
GREGORIAN_YEAR = 365.2425
GREGORIAN_LEAP_RATE = 0.2425
SECONDS_PER_DAY = 86400.0
NEGLIGIBLE_DRIFT = 0.5
MINOR_DRIFT = 2.75

MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def is_leap_year(year):
    """Return True when *year* is a leap year in the Gregorian calendar."""
    if isinstance(year, bool) or not isinstance(year, int):
        raise TypeError("year must be an integer")
    if year < 1:
        raise ValueError("year must be a positive integer")
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def days_in_year(year):
    return 366 if is_leap_year(year) else 365


def days_in_month(year, month):
    if month not in range(1, 13):
        raise ValueError("month must be in 1..12")
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def count_leap_years(start, end):
    if start > end:
        raise ValueError("start must not exceed end")
    return sum(1 for year in range(start, end + 1) if is_leap_year(year))


def leap_rate(start, end):
    span = end - start + 1
    return count_leap_years(start, end) / span


def average_year_length(start, end):
    total = sum(days_in_year(year) for year in range(start, end + 1))
    return total / (end - start + 1.0)


def drift_seconds_per_year(average_length):
    return (average_length - TROPICAL_YEAR) * SECONDS_PER_DAY


def drift_per_millennium(average_length):
    return (average_length - TROPICAL_YEAR) * 1000.0


def julian_excess_per_century(average_length):
    return (JULIAN_YEAR - average_length) * 100.0


def describe_drift(drift):
    size = abs(drift)
    if size < NEGLIGIBLE_DRIFT:
        return "negligible"
    if size < MINOR_DRIFT:
        return "minor"
    return "significant"


def format_report(start, end):
    average = average_year_length(start, end)
    drift = drift_per_millennium(average)
    lines = [
        "Gregorian calendar report for {0}-{1}".format(start, end),
        "  leap years      : {0} (rate {1:.4f}, ideal {2:.4f})".format(
            count_leap_years(start, end), leap_rate(start, end),
            GREGORIAN_LEAP_RATE),
        "  average year    : {0:.4f} days (ideal {1:.4f})".format(
            average, GREGORIAN_YEAR),
        "  Julian excess   : {0:+.3f} days / century".format(
            julian_excess_per_century(average)),
        "  drift / year    : {0:+.2f} seconds".format(
            drift_seconds_per_year(average)),
        "  drift / 1000 yr : {0:+.3f} days ({1})".format(
            drift, describe_drift(drift)),
        "  February 2024   : {0} days".format(days_in_month(2024, 2)),
    ]
    return "\n".join(lines)


def main():
    for year in (1900, 2000, 2023, 2024):
        print("{0}: {1}".format(year, is_leap_year(year)))
    print(format_report(1601, 2000))
    print(format_report(1900, 2100))


if __name__ == "__main__":
    main()

