import math


def validate_size(n):
    """Return n as a usable table size, raising ValueError for bad input."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("table size must be an integer")
    if n < 1:
        raise ValueError("table size must be at least 1")
    return n


def round_half_up(value):
    """Round to the nearest integer with ties going away from zero."""
    if value < 0.0:
        return -int(math.floor(-value + 0.5))
    return int(math.floor(value + 0.5))


def as_percent(fraction):
    """Format a fraction of the cells as a whole-number percentage."""
    return "{}%".format(round_half_up(fraction * 100.0))


def quantile(sorted_values, q):
    """Linear-interpolation quantile of an already sorted list."""
    if not sorted_values:
        raise ValueError("no values to summarise")
    position = (len(sorted_values) - 1) * q
    lower = int(math.floor(position))
    upper = min(lower + 1, len(sorted_values) - 1)
    weight = position - lower
    return sorted_values[lower] * (1.0 - weight) + sorted_values[upper] * weight


def multiplication_table(n):
    """Print the n x n multiplication table and return it as a list of lists."""
    n = validate_size(n)
    table = [[row * col for col in range(1, n + 1)] for row in range(1, n + 1)]
    width = len(str(n * n))
    for row in table:
        print(" ".join(str(value).rjust(width) for value in row))
    return table


def summarize(table):
    """Collect descriptive statistics about the products in a table."""
    flat = sorted(value for row in table for value in row)
    size = len(table)
    hot_cutoff = flat[-1] * 0.75
    return {
        "mean": sum(flat) / len(flat),
        "median": quantile(flat, 0.5),
        "lower_quartile": quantile(flat, 0.25),
        "upper_quartile": quantile(flat, 0.75),
        "hot_share": sum(1 for value in flat if value >= hot_cutoff) / len(flat),
        "diagonal_mean": sum(table[i][i] for i in range(size)) / size,
    }


def format_summary(stats):
    return (
        "mean={:.2f} median={:.2f} IQR=[{:.2f}, {:.2f}] "
        "diagonal mean={:.2f} top-quarter cells={}"
    ).format(
        stats["mean"],
        stats["median"],
        stats["lower_quartile"],
        stats["upper_quartile"],
        stats["diagonal_mean"],
        as_percent(stats["hot_share"]),
    )


def main():
    for size in (2, 5, 9):
        print("Multiplication table for n = {}".format(size))
        print(format_summary(summarize(multiplication_table(size))))
        print()


if __name__ == "__main__":
    main()

