BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}

WIN_POINTS = 1.0
TIE_POINTS = 0.5
LOSS_POINTS = 0.0

PLAYER1_MESSAGE = "Player 1 wins!"
PLAYER2_MESSAGE = "Player 2 wins!"
TIE_MESSAGE = "It's a tie!"


def normalize_choice(choice):
    if not isinstance(choice, str):
        raise TypeError("choice must be a string, got %r" % (choice,))
    cleaned = choice.strip().lower()
    if cleaned not in BEATS:
        raise ValueError("unknown choice: %r" % (choice,))
    return cleaned


def rock_paper_scissors(player1_choice, player2_choice):
    first = normalize_choice(player1_choice)
    second = normalize_choice(player2_choice)
    if first == second:
        return TIE_MESSAGE
    if BEATS[first] == second:
        return PLAYER1_MESSAGE
    return PLAYER2_MESSAGE


def score_round(player1_choice, player2_choice):
    result = rock_paper_scissors(player1_choice, player2_choice)
    if result == PLAYER1_MESSAGE:
        return WIN_POINTS, LOSS_POINTS
    if result == PLAYER2_MESSAGE:
        return LOSS_POINTS, WIN_POINTS
    return TIE_POINTS, TIE_POINTS


def play_match(rounds):
    p1_total = 0.0
    p2_total = 0.0
    results = []
    for player1_choice, player2_choice in rounds:
        results.append(rock_paper_scissors(player1_choice, player2_choice))
        p1_points, p2_points = score_round(player1_choice, player2_choice)
        p1_total += p1_points
        p2_total += p2_points
    return p1_total, p2_total, results


def point_share(score, played):
    if played == 0:
        return 0.0
    return score / played * 100.0


def match_summary(rounds):
    p1_score, p2_score, results = play_match(rounds)
    played = len(results)
    share = point_share(p1_score, played)
    if p1_score > p2_score:
        verdict = "Player 1 takes the match"
    elif p2_score > p1_score:
        verdict = "Player 2 takes the match"
    else:
        verdict = "The match is drawn"
    lines = ["Round %d: %s" % (i + 1, text) for i, text in enumerate(results)]
    lines.append("Score: %.2f - %.2f" % (p1_score, p2_score))
    lines.append("Player 1 earned %.1f%% of the available points" % share)
    lines.append(verdict)
    if p1_score > played / 2.0:
        lines.append("Player 1 clinched more than half the points.")
    return "\n".join(lines)


def main():
    rounds = [
        ("rock", "scissors"),
        ("paper", "rock"),
        ("Scissors", "scissors"),
        ("rock", "paper"),
        ("paper", "scissors"),
    ]
    print(match_summary(rounds))


if __name__ == "__main__":
    main()

