import math


def _to_whole_seconds(seconds):
    """Validate a duration and round it to the nearest whole second."""
    if isinstance(seconds, bool) or not isinstance(seconds, (int, float)):
        raise TypeError("duration must be an int or a float")
    value = float(seconds)
    if not math.isfinite(value):
        raise ValueError("duration must be a finite number")
    if value < 0.0:
        raise ValueError("duration must not be negative")
    return int(value + 0.5)


def seconds_to_hms(seconds):
    """Convert a duration in seconds to a zero-padded 'HH:MM:SS' string."""
    total = _to_whole_seconds(seconds)
    hours, remainder = divmod(total, 3600)
    minutes, secs = divmod(remainder, 60)
    return "{:02d}:{:02d}:{:02d}".format(hours, minutes, secs)


def hms_to_seconds(text):
    """Parse an 'HH:MM:SS' string back into a whole number of seconds."""
    parts = text.strip().split(":")
    if len(parts) != 3:
        raise ValueError("expected a duration in 'HH:MM:SS' form")
    hours, minutes, secs = (int(part) for part in parts)
    if not 0 <= minutes < 60 or not 0 <= secs < 60:
        raise ValueError("minutes and seconds must be in the range 0-59")
    return hours * 3600 + minutes * 60 + secs


def milestones(total_seconds, step=0.25):
    """List (percent, 'HH:MM:SS') checkpoints through a duration."""
    if step <= 0.0:
        raise ValueError("step must be positive")
    if step > 1.0:
        raise ValueError("step must not exceed one whole duration")
    total = _to_whole_seconds(total_seconds)
    marks = []
    fraction = 0.0
    limit = 1.0 + step / 2
    while fraction < limit:
        marks.append((fraction * 100.0, seconds_to_hms(total * fraction)))
        fraction += step
    return marks


def average_split(total_seconds, parts):
    """Average duration of one equal part of a longer effort."""
    if parts < 1:
        raise ValueError("need at least one part")
    total = _to_whole_seconds(total_seconds)
    return seconds_to_hms(total / parts)


def pace_per_km(total_seconds, distance_km):
    """Time needed to cover a single kilometre at the average pace."""
    distance = float(distance_km)
    if distance <= 0.0:
        raise ValueError("distance must be positive")
    total = _to_whole_seconds(total_seconds)
    return seconds_to_hms(total / distance)


def main():
    for sample in (3661, 90, 0, 86399, 59.75):
        print("{!r:>8} -> {}".format(sample, seconds_to_hms(sample)))

