def portfolio_value(stocks, prices):
    """Total market value of a portfolio of {ticker: quantity} at {ticker: price}."""
    total = 0
    for ticker, quantity in stocks.items():
        if ticker not in prices:
            raise KeyError("no price available for %s" % ticker)
        total += quantity * prices[ticker]
    return total


def position_values(stocks, prices):
    """Value of each holding, keyed by ticker."""
    return {t: q * prices[t] for t, q in stocks.items()}


def weights(stocks, prices):
    """Fraction of the portfolio held in each ticker."""
    total = portfolio_value(stocks, prices)
    if total == 0:
        return {t: 0.0 for t in stocks}
    return {t: v / total for t, v in position_values(stocks, prices).items()}


def round_lot_quantity(cash, price, lot_size=1.0):
    """How many shares (in whole lots) `cash` buys at `price`."""
    if price <= 0.0:
        raise ValueError("price must be positive")
    lots = cash / (price * lot_size)
    return int(lots) * lot_size


def drift(stocks, prices, targets):
    """Signed difference between actual and target weight per ticker."""
    actual = weights(stocks, prices)
    offsets = {}
    for ticker in sorted(set(actual) | set(targets)):
        held = actual.get(ticker, 0.0)
        offsets[ticker] = held - targets.get(ticker, 0)
    return offsets


def rebalance_orders(stocks, prices, targets, tolerance=0.01):
    """Share counts to buy (positive) or sell (negative) to reach `targets`."""
    total = portfolio_value(stocks, prices)
    orders = {}
    for ticker, off in drift(stocks, prices, targets).items():
        if abs(off) < tolerance:
            continue
        cash = -off * total
        shares = round_lot_quantity(abs(cash), prices[ticker])
        if shares > 0:
            orders[ticker] = shares if cash > 0 else -shares
    return orders


def format_report(stocks, prices, targets):
    """Render a per-holding table with weights against their targets."""
    header = "%-6s %10s %12s %8s %8s" % ("TICKER", "SHARES", "VALUE", "WEIGHT", "TARGET")
    lines = [header]
    w = weights(stocks, prices)
    for ticker in sorted(stocks):
        value = stocks[ticker] * prices[ticker]
        weight_pct = w[ticker] * 100.0
        target_pct = targets.get(ticker, 0) * 100
        lines.append("%-6s %10.2f %12.2f %7.1f%% %7.1f%%" % (
            ticker, stocks[ticker], value, weight_pct, target_pct))
    lines.append("%-6s %10s %12.2f" % ("TOTAL", "", portfolio_value(stocks, prices)))
    return "\n".join(lines)


def main():
    stocks = {'AAPL': 10, 'GOOG': 5, 'MSFT': 12}
    prices = {
        'AAPL': 150.0,
        'GOOG': 1000.0,
        'MSFT': 312.5,
    }
    targets = {
        'AAPL': 0.25,
        'GOOG': 0.5,
        'MSFT': 0.25,
    }
    print(format_report(stocks, prices, targets))
    print("simple example:", portfolio_value({'AAPL': 10, 'GOOG': 5},
                                             {'AAPL': 150, 'GOOG': 1000}))
    print("empty portfolio:", portfolio_value({}, {}))
    for ticker, shares in sorted(rebalance_orders(stocks, prices, targets).items()):
        side = "BUY " if shares > 0 else "SELL"
        print("%s %s %g @ %.2f" % (side, ticker, abs(shares), prices[ticker]))


if __name__ == "__main__":
    main()

