import math


def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    if isinstance(decimal_int, bool) or not isinstance(decimal_int, int):
        raise TypeError("decimal_to_binary expects a non-negative integer")
    if decimal_int < 0:
        raise ValueError("decimal_to_binary expects a non-negative integer")
    if decimal_int == 0:
        return "0"
    digits = []
    remaining = decimal_int
    while remaining:
        digits.append(str(remaining & 1))
        remaining >>= 1
    return "".join(reversed(digits))


def fraction_to_binary(fraction, precision=12):
    """Return the binary digits of a fraction in [0, 1) without a leading dot."""
    if fraction < 0.0:
        raise ValueError("fraction must not be negative")
    if fraction >= 1.0:
        raise ValueError("fraction must be smaller than one")
    digits = []
    value = fraction
    while value > 0.0 and len(digits) < precision:
        value *= 2.0
        if value >= 1.0:
            digits.append("1")
            value -= 1.0
        else:
            digits.append("0")
    return "".join(digits)


def number_to_binary(value, precision=12):
    """Convert an int or a non-negative float to a binary string."""
    if isinstance(value, int) and not isinstance(value, bool):
        return decimal_to_binary(value)
    whole = int(math.floor(value))
    fraction = value - whole
    text = decimal_to_binary(whole)
    if fraction > 0.0:
        digits = fraction_to_binary(fraction, precision)
        if digits:
            text = text + "." + digits
    return text


def binary_to_number(bits):
    """Parse a binary string (possibly with a fractional part) back to a number."""
    whole_part, _, fraction_part = bits.partition(".")
    value = float(int(whole_part, 2))
    weight = 0.5
    for digit in fraction_part:
        if digit == "1":
            value += weight
        weight *= 0.5
    return value


def ones_ratio(bits):
    """Fraction of set bits among the binary digits of a converted number."""
    digits = [digit for digit in bits if digit in "01"]
    if not digits:
        return 0.0
    return digits.count("1") / len(digits)


def density_label(ratio):
    """Describe whether ones or zeros dominate the binary representation."""
    if ratio > 0.5:
        return "one-heavy"
    if ratio < 0.5:
        return "zero-heavy"
    return "balanced"


def main():
    samples = [0, 11, 5, 255, 1024]
    samples.append(0.75)
    samples.append(1.0)
    samples.append(2.25)
    samples.append(6.375)
    for sample in samples:
        bits = number_to_binary(sample)
        ratio = ones_ratio(bits)
        restored = binary_to_number(bits)
        print("{:>8} -> {:<16} ones={:.3f} {:<10} back={}".format(
            sample, bits, ratio, density_label(ratio), restored))


if __name__ == "__main__":
    main()

