VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

NUMERALS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)


def roman_to_int(roman_numeral):
    text = roman_numeral.strip().upper()
    if not text:
        raise ValueError("empty Roman numeral")
    unknown = [ch for ch in text if ch not in VALUES]
    if unknown:
        raise ValueError("bad characters: " + "".join(unknown))
    total = 0
    for index, ch in enumerate(text):
        value = VALUES[ch]
        if index + 1 < len(text) and value < VALUES[text[index + 1]]:
            total -= value
        else:
            total += value
    return total


def int_to_roman(number):
    if number < 1:
        raise ValueError("Roman numerals start at 1")
    parts = []
    remainder = number
    for value, symbol in NUMERALS:
        count, remainder = divmod(remainder, value)
        parts.append(symbol * count)
    return "".join(parts)


def subtractive_ratio(roman_numeral):
    """Fraction of adjacent symbol pairs written in subtractive form."""
    text = roman_numeral.strip().upper()
    pairs = sum(
        1
        for i in range(len(text) - 1)
        if VALUES[text[i]] < VALUES[text[i + 1]]
    )
    return 2.0 * pairs / len(text)


def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 0:
        return (ordered[middle - 1] + ordered[middle]) * 0.5
    return float(ordered[middle])


def describe(roman_numeral):
    value = roman_to_int(roman_numeral)
    ratio = subtractive_ratio(roman_numeral)
    density = len(str(value)) / len(roman_numeral.strip())
    label = "subtractive" if ratio >= 0.5 else "additive"
    if density >= 0.75:
        label += ", compact"
    return "{:<12} {:>5}  {:>6.1f}%  {}".format(
        roman_numeral, value, ratio * 100.0, label
    )


def main():
    samples = ["IV", "IX", "XL", "MCMXCIV", "MMXXV", "DCCCLXXXVIII", "XIII"]
    print("numeral       value  subtr.   notes")
    for numeral in samples:
        print(describe(numeral))
    values = [roman_to_int(numeral) for numeral in samples]
    average = sum(values) / len(values)
    print("average value: {:.2f}".format(average))
    print("median value:  {:.2f}".format(median(values)))
    spread = (max(values) - min(values)) / average
    print("relative spread: {:.3f}".format(spread))
    mismatched = [n for n in samples if int_to_roman(roman_to_int(n)) != n]
    print("round-trip failures: {}".format(len(mismatched)))


if __name__ == "__main__":
    main()

