def validate_sequence(numbers):
    """Check that `numbers` holds unique integers from 1..N with exactly one gap."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if len(numbers) == 0:
        raise ValueError("numbers must contain at least one element")
    n = len(numbers) + 1
    seen = set()
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{value!r} is not an integer")
        if value < 1 or value > n:
            raise ValueError(f"{value} lies outside the range 1..{n}")
        if value in seen:
            raise ValueError(f"{value} appears more than once")
        seen.add(value)
    return n


def find_missing_number(numbers):
    """Return the single missing value of the unsorted sequence 1..N."""
    n = validate_sequence(numbers)
    return n * (n + 1) // 2 - sum(numbers)


def median(values):
    """Median of the supplied values, always returned as a float."""
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 0:
        return (ordered[middle - 1] + ordered[middle]) * 0.5
    return float(ordered[middle])


def sequence_stats(numbers):
    """Describe the sequence and the gap found inside it."""
    missing = find_missing_number(numbers)
    n = len(numbers) + 1
    expected_mean = (n + 1) * 0.5
    actual_mean = sum(numbers) / len(numbers)
    return {
        "n": n,
        "missing": missing,
        "expected_mean": expected_mean,
        "actual_mean": actual_mean,
        "median": median(numbers),
        "coverage": 100.0 * len(numbers) / n,
        "mean_ratio": actual_mean / expected_mean,
        "position": missing / n,
    }


def describe_position(stats):
    """Explain where the gap sits relative to the middle of the range."""
    if stats["position"] <= 0.5:
        half = "lower half"
    else:
        half = "upper half"
    ratio = stats["mean_ratio"]
    if ratio < 1.0:
        pull = "drags the observed mean down"
    elif ratio > 1.0:
        pull = "pushes the observed mean up"
    else:
        pull = "leaves the observed mean untouched"
    return f"{stats['missing']} is in the {half} of 1..{stats['n']} and {pull}"


def format_report(numbers):
    stats = sequence_stats(numbers)
    return "\n".join([
        f"input          : {list(numbers)}",
        f"missing number : {stats['missing']}",
        f"expected mean  : {stats['expected_mean']:.2f}",
        f"observed mean  : {stats['actual_mean']:.2f}",
        f"observed median: {stats['median']:.2f}",
        f"coverage       : {stats['coverage']:.1f}%",
        f"note           : {describe_position(stats)}",
    ])


def main():
    samples = [[1, 2, 4, 5], [5, 1, 3, 2], [2], [9, 4, 7, 1, 2, 8, 5, 6, 10]]
    for sample in samples:
        print(format_report(sample))
        print("-" * 48)


if __name__ == "__main__":
    main()

