from collections import Counter


def normalize(text):
    """Lower-case the text and drop spaces, keeping every other character."""
    return "".join(ch for ch in text.lower() if not ch.isspace())


def char_counts(text):
    return Counter(normalize(text))


def is_anagram(s1, s2):
    """True when s1 and s2 use the same characters with the same frequencies."""
    return char_counts(s1) == char_counts(s2)


def similarity(s1, s2):
    """Symmetric overlap score: 1.0 for anagrams, 0.0 when nothing is shared."""
    c1 = char_counts(s1)
    c2 = char_counts(s2)
    total1 = sum(c1.values())
    total2 = sum(c2.values())
    if total1 == 0 and total2 == 0:
        return 1.0
    if total1 == 0 or total2 == 0:
        return 0.0
    common = sum((c1 & c2).values())
    return 0.5 * (common / total1 + common / total2)


def classify(score):
    if score >= 1.0:
        return "anagram"
    if score >= 0.75:
        return "near-anagram"
    if score >= 0.5:
        return "partial overlap"
    return "unrelated"


def missing_characters(s1, s2):
    """Characters of s1 that s2 cannot supply, as a sorted string."""
    shortfall = char_counts(s1) - char_counts(s2)
    return "".join(sorted(shortfall.elements()))


def describe(s1, s2):
    score = similarity(s1, s2)
    line = "{!r} vs {!r}: {} ({:.1f}% match)".format(
        s1, s2, classify(score), score * 100.0
    )
    if not is_anagram(s1, s2):
        left = missing_characters(s1, s2)
        right = missing_characters(s2, s1)
        line += " | extra in first: '{}', extra in second: '{}'".format(left, right)
    return line


def main():
    pairs = [
        ("listen", "silent"),
        ("hello", "world"),
        ("Dormitory", "Dirty Room"),
        ("conversation", "voices rant on"),
        ("apple", "apples"),
    ]
    for s1, s2 in pairs:
        print(describe(s1, s2))
    matches = sum(1 for s1, s2 in pairs if is_anagram(s1, s2))
    rate = matches / len(pairs)
    mean = sum(similarity(a, b) for a, b in pairs) / len(pairs)
    print("anagram pairs: {}/{} ({:.2f} of the sample)".format(matches, len(pairs), rate))
    print("mean similarity: {:.3f}".format(mean))


if __name__ == "__main__":
    main()

