"""Product of a list of numbers, with a few related utilities."""


def product_list(numbers):
    """Return the product of all numbers in the list (1 for an empty list)."""
    product = 1
    for value in numbers:
        product *= value
    return product


def geometric_mean(numbers):
    """Return the geometric mean of positive numbers, or None if undefined."""
    if not numbers:
        return None
    if any(value <= 0.0 for value in numbers):
        return None
    return product_list(numbers) ** (1.0 / len(numbers))


def scale_to_product(numbers, target):
    """Scale every element by a common factor so the product becomes target."""
    current = product_list(numbers)
    if current == 0 or target == 0:
        raise ValueError("cannot rescale a product of zero")
    factor = (target / current) ** (1.0 / len(numbers))
    return [value * factor for value in numbers]


def compound_growth(rates):
    """Return the total growth factor implied by a list of percentage rates."""
    factors = [1.0 + rate / 100 for rate in rates]
    return product_list(factors)


def format_number(value):
    """Render a number compactly, keeping three decimals for non-integers."""
    if value is None:
        return "undefined"
    if isinstance(value, int):
        return str(value)
    rounded = round(value)
    if abs(value - rounded) < 0.0005:
        return str(rounded)
    return "{0:.3f}".format(value)


def main():
    print("simple:", product_list([1, 2, 3, 4]))
    print("with zero:", product_list([5, -2, 0]))
    prices = [12, 0.75, 4]
    print("mixed product:", format_number(product_list(prices)))
    print("geometric mean:", format_number(geometric_mean(prices)))
    rescaled = scale_to_product(prices, 2.25)
    print("rescaled:", ", ".join(format_number(v) for v in rescaled))
    print("check:", format_number(product_list(rescaled)))
    growth = compound_growth([5, 2.5, -1])
    print("total growth: {0:.2f}x".format(growth))


if __name__ == "__main__":
    main()

