def count_uppercase(text):
    """Return the number of uppercase letters in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    count = 0
    for character in text:
        if character.isupper():
            count += 1
    return count


def count_letters(text):
    """Return the number of alphabetic characters in text."""
    return sum(1 for character in text if character.isalpha())


def uppercase_ratio(text):
    """Return the share of letters in text that are uppercase."""
    letters = count_letters(text)
    if letters == 0:
        return 0.0
    return count_uppercase(text) / letters


def describe_case(text):
    """Classify the capitalisation style of text from its uppercase ratio."""
    ratio = uppercase_ratio(text)
    if ratio == 0.0:
        return "no uppercase"
    if ratio >= 1.0:
        return "all caps"
    if ratio >= 0.75:
        return "mostly caps"
    if ratio >= 0.25:
        return "mixed case"
    return "occasional caps"


def format_percentage(ratio, decimals=1):
    """Render a ratio in the range 0..1 as a percentage string."""
    return "{value:.{places}f}%".format(value=ratio * 100.0, places=decimals)


def shouting_score(text):
    """Score how much a line looks like shouting: caps plus exclamation marks."""
    score = uppercase_ratio(text)
    exclamations = text.count("!")
    if exclamations:
        score += 0.5 * min(exclamations, 2)
    return min(score, 2.0)


def report_line(text):
    """Build a one-line report about the capitalisation of text."""
    parts = [
        "{!r}".format(text),
        "uppercase={}".format(count_uppercase(text)),
        "ratio={}".format(format_percentage(uppercase_ratio(text))),
        describe_case(text),
    ]
    if shouting_score(text) >= 1.0:
        parts.append("SHOUTING")
    return " | ".join(parts)


def main():
    samples = [
        "Hello World",
        "python is fun",
        "STOP RIGHT THERE!",
        "McDonald's Farm",
        "1234 5678",
        "eBay AND Amazon",
    ]
    for sample in samples:
        print(report_line(sample))
    average = sum(uppercase_ratio(sample) for sample in samples) / len(samples)
    print("average uppercase ratio:", format_percentage(average, 2))
    loud = [s for s in samples if shouting_score(s) > 0.75]
    print("loud samples:", len(loud), "of", len(samples))


if __name__ == "__main__":
    main()

