NEAR_TOLERANCE = 0.25


def validate_numbers(numbers):
    """Check that numbers is a non-empty sequence of real numbers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if len(numbers) == 0:
        raise ValueError("numbers must not be empty")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("all elements must be int or float")
    return list(numbers)


def find_smallest(numbers):
    """Return the minimum value of the given list of numbers."""
    values = validate_numbers(numbers)
    smallest_number = values[0]
    for value in values[1:]:
        if value < smallest_number:
            smallest_number = value
    return smallest_number


def find_largest(numbers):
    """Return the maximum value of the given list of numbers."""
    values = validate_numbers(numbers)
    largest = values[0]
    for value in values[1:]:
        if value > largest:
            largest = value
    return largest


def spread(numbers):
    """Distance between the largest and the smallest value."""
    return find_largest(numbers) - find_smallest(numbers)


def midpoint(numbers):
    """Value halfway between the smallest and the largest value."""
    return find_smallest(numbers) + spread(numbers) * 0.5


def normalize(numbers):
    """Rescale values so the minimum maps to zero and the maximum to one."""
    smallest = find_smallest(numbers)
    width = spread(numbers)
    if width == 0.0:
        return [0.5] * len(numbers)
    return [(value - smallest) / width for value in numbers]


def count_near_smallest(numbers, tolerance):
    """How many values sit within tolerance of the minimum."""
    smallest = find_smallest(numbers)
    return sum(1 for value in numbers if value - smallest <= tolerance)


def share_near_smallest(numbers, tolerance):
    """Percentage of values within tolerance of the minimum."""
    values = validate_numbers(numbers)
    return count_near_smallest(values, tolerance) / len(values) * 100.0


def format_value(value):
    if isinstance(value, float):
        return str(round(value, 2))
    return str(value)


def describe(numbers):
    parts = [
        "values=[" + ", ".join(format_value(v) for v in numbers) + "]",
        "smallest=" + format_value(find_smallest(numbers)),
        "largest=" + format_value(find_largest(numbers)),
        "midpoint=" + format_value(midpoint(numbers)),
        "near_min=" + str(count_near_smallest(numbers, NEAR_TOLERANCE)),
        "near_min_pct=" + format_value(share_near_smallest(numbers, NEAR_TOLERANCE)),
        "scaled=[" + ", ".join(format_value(v) for v in normalize(numbers)) + "]",
    ]
    return " | ".join(parts)


def main():
    datasets = [
        [5, 2, 8, 1],
        [-10, 0, 3],
        [0.5, 6, -1],
        [7, 7, 7],
    ]
    for numbers in datasets:
        print(describe(numbers))
    pooled = [find_smallest(dataset) for dataset in datasets]
    print("overall smallest =", format_value(find_smallest(pooled)))


if __name__ == "__main__":
    main()

