def filter_odd(numbers):
    """Return a new list containing only the odd numbers of *numbers*."""
    odd_numbers = []
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("filter_odd expects a list of int, got %r" % (value,))
        if value % 2 != 0:
            odd_numbers.append(value)
    return odd_numbers


def odd_ratio(numbers):
    """Fraction of the input that is odd; an empty input has ratio 0.0."""
    if not numbers:
        return 0.0
    return len(filter_odd(numbers)) / float(len(numbers))


def odd_percentage(numbers):
    return odd_ratio(numbers) * 100.0


def is_mostly_odd(numbers):
    """True when strictly more than half of the values are odd."""
    return odd_ratio(numbers) > 0.5


def mean(values):
    if not values:
        return 0.0
    total = 0.0
    for value in values:
        total += value
    return total / len(values)


def median(values):
    if not values:
        return 0.0
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def spread(values):
    """Half the distance between the extremes, 0.0 for fewer than two values."""
    if len(values) < 2:
        return 0.0
    return (max(values) - min(values)) * 0.5


def describe(numbers):
    odds = filter_odd(numbers)
    lines = [
        "input   : %r" % (numbers,),
        "odd     : %r" % (odds,),
        "share   : %.1f%%" % odd_percentage(numbers),
        "mean    : %.2f" % mean(odds),
        "median  : %.2f" % median(odds),
        "spread  : %.2f" % spread(odds),
    ]
    if is_mostly_odd(numbers):
        lines.append("verdict : mostly odd")
    else:
        lines.append("verdict : mostly even")
    return "\n".join(lines)


