def list_difference(list1, list2):
    """Return the elements of list1 that do not appear in list2."""
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("both arguments must be lists")
    try:
        excluded = set(list2)
    except TypeError:
        return [item for item in list1 if item not in list2]
    return [item for item in list1 if item not in excluded]


def common_elements(list1, list2):
    """Return the elements of list1 that also appear in list2."""
    removed = list_difference(list1, list2)
    kept = list(list1)
    for item in removed:
        kept.remove(item)
    return kept


def retention_ratio(list1, list2):
    """Fraction of list1 that survives the difference operation."""
    if not list1:
        return 0.0
    return len(list_difference(list1, list2)) / len(list1)


def jaccard_index(list1, list2):
    """Similarity of the two lists, treated as sets of distinct values."""
    left, right = set(list1), set(list2)
    union = left | right
    if not union:
        return 1.0
    return len(left & right) / len(union)


def similarity_grade(score):
    """Describe a similarity score between 0.0 and 1.0 in words."""
    if score >= 0.75:
        return "nearly identical"
    if score >= 0.5:
        return "strongly overlapping"
    if score >= 0.25:
        return "partly overlapping"
    return "mostly distinct"


def format_report(list1, list2):
    """Build a multi-line summary of the difference between two lists."""
    difference = list_difference(list1, list2)
    shared = common_elements(list1, list2)
    score = jaccard_index(list1, list2)
    percent_unique = 100.0 * retention_ratio(list1, list2)
    lines = [
        "list1      = {!r}".format(list1),
        "list2      = {!r}".format(list2),
        "difference = {!r}".format(difference),
        "shared     = {!r}".format(shared),
        "unique to list1: {:.1f}%".format(percent_unique),
        "similarity: {:.2f} ({})".format(score, similarity_grade(score)),
    ]
    return "\n".join(lines)


def main():
    prices = [
        1.5,
        2.25,
        0.75,
    ]
    discounted = [
        2.25,
    ]
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        (prices, discounted),
        ([], []),
    ]
    for list1, list2 in cases:
        print(format_report(list1, list2))
        print("-" * 40)


if __name__ == "__main__":
    main()

