import math

SQRT5 = math.sqrt(5.0)
PHI = (1.0 + SQRT5) / 2


def _validate_index(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    return n


def nth_fibonacci(n):
    _validate_index(n)
    previous, current = 0, 1
    for _ in range(n):
        previous, current = current, previous + current
    return previous


def fibonacci_binet(n):
    _validate_index(n)
    value = PHI ** n / SQRT5
    return int(math.floor(value + 0.5))


def successive_ratio(n):
    exact = nth_fibonacci(n)
    if exact == 0:
        return 0.0
    return nth_fibonacci(n + 1) / exact


def relative_error(approximation, exact):
    if exact == 0:
        if approximation == 0:
            return 0.0
        return 1.0
    return abs(approximation - exact) / exact


def error_percent(approximation, exact):
    return relative_error(approximation, exact) * 100.0


def digit_estimate(n):
    if n < 2:
        return 1
    return int(math.floor(n * math.log10(PHI) - math.log10(SQRT5))) + 1


def stable_ratio_index(tolerance=1.0e-6, limit=200):
    for n in range(1, limit):
        if abs(successive_ratio(n) - PHI) < tolerance:
            return n
    return None


def last_exact_binet_index(limit=200):
    best = 0
    for n in range(limit):
        exact = nth_fibonacci(n)
        if abs(PHI ** n / SQRT5 - exact) < 0.5:
            best = n
        else:
            break
    return best


def report_row(n):
    exact = nth_fibonacci(n)
    approx = fibonacci_binet(n)
    ratio = successive_ratio(n)
    return "{:>3} {:>10} {:>10} {:>9.4f} {:>9.5f} {:>4}".format(
        n, exact, approx, error_percent(approx, exact), ratio, digit_estimate(n)
    )


def main():
    print("  n      F(n)     Binet    err(%)     ratio  dig")
    for n in range(0, 16):
        print(report_row(n))
    print("golden ratio: {:.10f}".format(PHI))
    print("ratio settles at n = {}".format(stable_ratio_index()))
    print("Binet stays exact up to n = {}".format(last_exact_binet_index()))
    print("F(0) = {}, F(6) = {}".format(nth_fibonacci(0), nth_fibonacci(6)))


if __name__ == "__main__":
    main()

