from datetime import date
import math


def parse_date(date_str):
    """Turn a 'YYYY-MM-DD' string into a date object, rejecting bad input."""
    parts = date_str.strip().split('-')
    if len(parts) != 3:
        raise ValueError("date must look like YYYY-MM-DD, got %r" % date_str)
    try:
        year, month, day = (int(part) for part in parts)
    except ValueError:
        raise ValueError("date fields must be integers, got %r" % date_str)
    return date(year, month, day)


def days_remaining(start_date_str, end_date_str):
    """Number of days between the start date and the (future) end date."""
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def weeks_remaining(days):
    """The same span expressed in weeks."""
    return days / 7.0


def months_remaining(days):
    """Approximate months, using the mean length of a Gregorian month."""
    return days / 30.44


def years_remaining(days):
    """Approximate years, using the mean length of a Gregorian year."""
    return days / 365.25


def round_half_up(value):
    """Round to the nearest integer, ties going upwards."""
    return int(math.floor(value + 0.5))


def elapsed_fraction(start_date_str, current_date_str, end_date_str):
    """How much of the start..end window has already gone by, as 0..1."""
    total = days_remaining(start_date_str, end_date_str)
    if total <= 0:
        raise ValueError("end date must come after the start date")
    fraction = days_remaining(start_date_str, current_date_str) / float(total)
    if fraction < 0.0:
        return 0.0
    if fraction > 1.0:
        return 1.0
    return fraction


def urgency(fraction):
    """Short label describing how close the deadline is."""
    if fraction >= 0.75:
        return "final stretch"
    if fraction >= 0.5:
        return "past halfway"
    if fraction > 0.0:
        return "under way"
    return "not started"


def format_report(start_date_str, current_date_str, end_date_str):
    """Multi-line countdown summary for the given window."""
    left = days_remaining(current_date_str, end_date_str)
    fraction = elapsed_fraction(start_date_str, current_date_str, end_date_str)
    lines = ["Countdown %s -> %s (today %s)" % (start_date_str, end_date_str, current_date_str),
             "  days remaining : %d" % left,
             "  weeks remaining: %.2f" % weeks_remaining(left),
             "  months (approx): %.2f" % months_remaining(left),
             "  years (approx) : %.3f" % years_remaining(left),
             "  progress       : %d%% (%s)" % (round_half_up(fraction * 100.0), urgency(fraction))]
    return "\n".join(lines)


def main():
    print(days_remaining('2023-01-01', '2023-01-05'))
    print(days_remaining('2023-12-31', '2024-01-01'))
    print(format_report('2023-01-01', '2023-10-01', '2024-01-01'))
    print(format_report('2024-02-01', '2024-02-15', '2024-03-01'))


if __name__ == '__main__':
    main()

