ALLOWED_HOST_CHARS = set("abcdefghijklmnopqrstuvwxyz0123456789-.")
SECURE_WEIGHT = 0.5
TLD_WEIGHT = 0.25
DEPTH_WEIGHT = 0.25
TRUST_THRESHOLD = 0.75


def split_scheme(url):
    """Return (scheme, remainder) for a supported scheme, else ('', url)."""
    lowered = url.lower()
    for scheme in ("https://", "http://"):
        if lowered.startswith(scheme):
            return scheme, url[len(scheme):]
    return "", url


def extract_host(remainder):
    """Cut the authority part away from path, query and fragment."""
    host = remainder
    for separator in ("/", "?", "#"):
        host = host.split(separator)[0]
    return host.split("@")[-1].split(":")[0]


def is_valid_url(url):
    if not isinstance(url, str):
        return False
    scheme, remainder = split_scheme(url.strip())
    if not scheme:
        return False
    host = extract_host(remainder).lower()
    if "." not in host or host.startswith(".") or host.endswith("."):
        return False
    if not set(host) <= ALLOWED_HOST_CHARS:
        return False
    return all(label and not label.startswith("-") for label in host.split("."))


def score_url(url):
    """Heuristic confidence in 0.0 - 1.0 for an already parsed URL."""
    if not is_valid_url(url):
        return 0.0
    scheme, remainder = split_scheme(url.strip())
    secure = 1.0
    if scheme != "https://":
        secure = 0.5
    labels = extract_host(remainder).lower().split(".")
    tld = labels[-1]
    tld_quality = 1.0
    if len(tld) < 2 or not tld.isalpha():
        tld_quality = 0.25
    depth = min(len(labels) / 3.0, tld_quality)
    score = SECURE_WEIGHT * secure
    score += TLD_WEIGHT * tld_quality
    return score + DEPTH_WEIGHT * depth


def format_report(url):
    verdict = "valid" if is_valid_url(url) else "invalid"
    percent = score_url(url) * 100.0
    return "{:<34} {:<8} confidence {:5.1f}%".format(url, verdict, percent)


def summarize(urls):
    valid = [u for u in urls if is_valid_url(u)]
    ratio = 0.0
    if urls:
        ratio = len(valid) / len(urls) * 100.0
    average = sum(score_url(u) for u in valid) / len(valid) if valid else 0.0
    trusted = [u for u in valid if score_url(u) >= TRUST_THRESHOLD]
    return ratio, average, trusted


def main():
    candidates = [
        "https://www.example.com",
        "ftp://invalid-url",
        "http://example.co.uk/path?q=1",
        "https://localhost",
        "http://.broken.com",
        "https://deep.sub.domain.example.org/#top",
    ]
    for candidate in candidates:
        print(format_report(candidate))
    ratio, average, trusted = summarize(candidates)
    print("\nvalid: {:.1f}% of {} candidates".format(ratio, len(candidates)))
    print("mean confidence of valid URLs: {:.2f}".format(average))
    print("above the trust threshold {}: {}".format(TRUST_THRESHOLD, len(trusted)))
    for url in trusted:
        print("  - {} ({:.2f})".format(url, score_url(url)))


if __name__ == "__main__":
    main()

