def validate(numbers):
    """Return the input as a list of floats, rejecting non-positive values."""
    if not numbers:
        raise ValueError("harmonic mean is undefined for an empty list")
    values = []
    for item in numbers:
        value = float(item)
        if value <= 0.0:
            raise ValueError("all numbers must be positive, got %r" % (item,))
        values.append(value)
    return values


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    values = validate(numbers)
    total = 0.0
    for value in values:
        total += 1.0 / value
    return len(values) / total


def arithmetic_mean(numbers):
    values = validate(numbers)
    return sum(values) / len(values)


def geometric_mean(numbers):
    values = validate(numbers)
    product = 1.0
    for value in values:
        product *= value
    return product ** (1.0 / len(values))


def weighted_harmonic_mean(numbers, weights):
    """Harmonic mean where each value contributes according to its weight."""
    values = validate(numbers)
    weights = validate(weights)
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    denominator = 0.0
    for value, weight in zip(values, weights):
        denominator += weight / value
    return sum(weights) / denominator


def spread_ratio(numbers):
    """How far the harmonic mean falls below the arithmetic mean."""
    return harmonic_mean(numbers) / arithmetic_mean(numbers)


def describe(numbers):
    lines = ["data: " + ", ".join("%g" % value for value in validate(numbers))]
    lines.append("  harmonic   = %.6f" % harmonic_mean(numbers))
    lines.append("  geometric  = %.6f" % geometric_mean(numbers))
    lines.append("  arithmetic = %.6f" % arithmetic_mean(numbers))
    ratio = spread_ratio(numbers)
    lines.append("  H/A ratio  = %.4f" % ratio)
    if ratio > 0.99:
        lines.append("  values are nearly identical")
    elif ratio < 0.75:
        lines.append("  values are strongly skewed by small entries")
    return "\n".join(lines)


def main():
    datasets = [
        [1, 2, 4],
        [10, 10, 10],
        [
            0.5,
            1.0,
            2.25,
            8.0,
        ],
    ]
    for data in datasets:
        print(describe(data))
        print()
    speeds = [
        90.0,
        45.0,
        30.0,
    ]
    legs = [
        2.0,
        1.0,
        0.5,
    ]
    print("average speed over weighted legs = %.4f" % weighted_harmonic_mean(speeds, legs))


if __name__ == "__main__":
    main()

