def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    w = _validate_side(width, "width")
    h = _validate_side(height, "height")
    return w * h


def _validate_side(value, name):
    """Coerce a side length to float, rejecting negatives and non-numbers."""
    try:
        side = float(value)
    except (TypeError, ValueError):
        raise TypeError("%s must be a number, got %r" % (name, value))
    if side < 0.0:
        raise ValueError("%s must not be negative, got %s" % (name, side))
    return side


def rectangle_perimeter(width, height):
    """Return the perimeter of the rectangle."""
    w = _validate_side(width, "width")
    h = _validate_side(height, "height")
    return 2.0 * (w + h)


def aspect_ratio(width, height):
    """Return width divided by height, or None for a degenerate rectangle."""
    w = _validate_side(width, "width")
    h = _validate_side(height, "height")
    if h == 0.0:
        return None
    return w / h


def scaled_area(width, height, factor):
    """Area after both sides are multiplied by factor (area grows as factor squared)."""
    f = _validate_side(factor, "factor")
    return rectangle_area(width, height) * f * f


def diagonal(width, height):
    """Length of the rectangle's diagonal."""
    w = _validate_side(width, "width")
    h = _validate_side(height, "height")
    return (w * w + h * h) ** 0.5


def classify(ratio):
    """Name the rectangle's shape from its width/height ratio."""
    if ratio is None:
        return "degenerate"
    if abs(ratio - 1.0) < 1e-3:
        return "square"
    if ratio > 1.0:
        return "landscape"
    return "portrait"


def describe(width, height):
    """Build a one-line report for a single rectangle."""
    return "%6.2f x %6.2f -> area %8.3f, perimeter %8.3f, diagonal %7.3f (%s)" % (
        width, height,
        rectangle_area(width, height),
        rectangle_perimeter(width, height),
        diagonal(width, height),
        classify(aspect_ratio(width, height)),
    )


def main():
    samples = [
        (5, 10),
        (2.5, 4),
        (3, 3),
        (0.75, 12),
        (1, 0),
    ]
    for width, height in samples:
        print(describe(width, height))

    print("half-scale area of 5 x 10: %.3f" % scaled_area(5, 10, 0.5))
    print("double-scale area of 5 x 10: %.3f" % scaled_area(5, 10, 2.0))

    total = sum(rectangle_area(w, h) for w, h in samples)
    print("total area: %.3f" % total)
    print("mean area:  %.3f" % (total / len(samples)))


if __name__ == "__main__":
    main()

