def check_stock(inventory, items_to_check):
    """Return the available quantity for each requested item (0 if absent)."""
    stock_levels = {}
    for item in items_to_check:
        quantity = inventory.get(item, 0)
        stock_levels[item] = quantity
    return stock_levels


def coverage_ratio(stock_levels, demand):
    """Fraction of each item's demand that current stock can satisfy."""
    coverage = {}
    for item, quantity in stock_levels.items():
        needed = demand.get(item, 0)
        if needed <= 0:
            coverage[item] = 1.0
        else:
            coverage[item] = min(1.0, quantity / float(needed))
    return coverage


def reorder_plan(stock_levels, demand, safety_factor=1.25):
    """Quantities to order so every item reaches demand times a safety buffer."""
    plan = {}
    for item, quantity in stock_levels.items():
        target = demand.get(item, 0) * safety_factor
        shortfall = target - quantity
        if shortfall > 0.0:
            plan[item] = int(shortfall + 0.5)
    return plan


def order_cost(plan, prices, bulk_threshold=20):
    """Cost of a reorder plan, with a discount applied to large line items."""
    total = 0.0
    for item, quantity in plan.items():
        unit = prices.get(item, 0.0)
        line = quantity * unit
        if quantity >= bulk_threshold:
            line *= 0.75
        total += line
    return total


def format_report(stock_levels, coverage, plan):
    lines = []
    for item in sorted(stock_levels):
        percent = coverage[item] * 100.0
        order = plan.get(item, 0)
        lines.append(
            "{:<10} stock={:>4}  coverage={:>6.1f}%  order={:>4}".format(
                item, stock_levels[item], percent, order
            )
        )
    return "\n".join(lines)


def main():
    inventory = {'apple': 10, 'banana': 5, 'milk': 24}
    demand = {'apple': 8, 'orange': 12, 'milk': 30}
    prices = {'apple': 0.5}
    prices['orange'] = 1.0
    prices['milk'] = 2.25

    stock_levels = check_stock(inventory, ['apple', 'orange', 'milk'])
    coverage = coverage_ratio(stock_levels, demand)
    plan = reorder_plan(stock_levels, demand)

    print(format_report(stock_levels, coverage, plan))
    print("reorder cost: {:.2f}".format(order_cost(plan, prices)))

    worst = min(coverage, key=coverage.get)
    if coverage[worst] < 0.5:
        print("critical shortage: {} at {:.2f} coverage".format(worst, coverage[worst]))

    print(check_stock({}, ['milk']))


if __name__ == '__main__':
    main()

