def count_words(text):
    """Return the number of space-separated words in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    word_count = len(text.split())
    return word_count


def split_words(text):
    """Return the individual words of text, ignoring repeated spaces."""
    return text.split()


def average_word_length(words):
    """Mean number of characters per word; 0.0 for an empty list."""
    if not words:
        return 0.0
    total = sum(len(word) for word in words)
    return total / len(words)


def short_word_ratio(words, limit=4):
    """Fraction of words no longer than limit characters."""
    if not words:
        return 0.0
    short = sum(1 for word in words if len(word) <= limit)
    return short / len(words)


def count_sentences(text):
    """Count sentence terminators, treating text without one as a single sentence."""
    sentences = 0
    previous_was_end = False
    for char in text:
        if char in ".!?":
            if not previous_was_end:
                sentences += 1
            previous_was_end = True
        else:
            previous_was_end = False
    return max(sentences, 1)


def words_per_sentence(text):
    """Average sentence length in words."""
    return count_words(text) / count_sentences(text)


def complexity_score(text):
    """Weighted blend of word length and sentence length."""
    length_weight = 0.75
    sentence_weight = 1 - length_weight
    words = split_words(text)
    length_part = length_weight * average_word_length(words)
    return length_part + sentence_weight * words_per_sentence(text)


def describe_style(text):
    score = complexity_score(text)
    if score >= 6.0:
        return "dense"
    if score >= 3.5:
        return "balanced"
    return "plain"


def report(text):
    """Build a multi-line summary of the given text."""
    words = split_words(text)
    lines = ["words: %d" % count_words(text),
             "sentences: %d" % count_sentences(text),
             "average word length: %.2f" % average_word_length(words),
             "short words: %.1f%%" % (short_word_ratio(words) * 100.0),
             "words per sentence: %.2f" % words_per_sentence(text),
             "complexity: %.2f (%s)" % (complexity_score(text), describe_style(text))]
    return "\n".join(lines)


def main():
    samples = ["This is a test sentence.",
               "  Hello   world  ",
               "Considerable deliberation preceded the announcement! Nobody objected."]
    for sample in samples:
        print(repr(sample))
        print(report(sample))
        print("-" * 32)


if __name__ == "__main__":
    main()

