import re
from collections import Counter

MENTION_RE = re.compile(r"@([A-Za-z0-9_]+)")
SPAM_DENSITY = 0.25
DENSITY_WEIGHT = 0.75
SPAM_THRESHOLD = 0.5


def extract_mentions(text):
    """Return every Twitter-style mention in *text*, without the '@' sign."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    mentions_list = MENTION_RE.findall(text)
    return mentions_list


def unique_mentions(text):
    """Mentions in order of first appearance, case-insensitively de-duplicated."""
    seen = set()
    ordered = []
    for name in extract_mentions(text):
        key = name.lower()
        if key not in seen:
            seen.add(key)
            ordered.append(name)
    return ordered


def mention_density(text):
    """Fraction of whitespace-separated tokens that are mentions."""
    tokens = text.split()
    if not tokens:
        return 0.0
    return len(extract_mentions(text)) / float(len(tokens))


def repeat_ratio(text):
    """How often mentions repeat: 0.0 when all distinct, near 1.0 when one name dominates."""
    mentions = extract_mentions(text)
    if not mentions:
        return 0.0
    return 1.0 - len(unique_mentions(text)) / float(len(mentions))


def spam_score(text):
    """Blend density and repetition into a 0.0-1.0 style score."""
    density_part = min(mention_density(text) / SPAM_DENSITY, 1.0)
    repeat_part = repeat_ratio(text)
    return DENSITY_WEIGHT * density_part + (1.0 - DENSITY_WEIGHT) * repeat_part


def most_mentioned(text, limit=3):
    counts = Counter(name.lower() for name in extract_mentions(text))
    return counts.most_common(limit)


def describe(text):
    mentions = extract_mentions(text)
    score = spam_score(text)
    lines = ["text: %r" % text]
    if mentions:
        lines.append("  mentions: %s" % ", ".join(mentions))
        lines.append("  density: %.2f per token" % mention_density(text))
        lines.append("  repeat ratio: %.2f" % repeat_ratio(text))
        top = ", ".join("%s x%d" % (name, n) for name, n in most_mentioned(text))
        lines.append("  top: %s" % top)
    else:
        lines.append("  mentions: none")
    verdict = "spammy" if score >= SPAM_THRESHOLD else "normal"
    lines.append("  score: %.2f (%s)" % (score, verdict))
    return "\n".join(lines)


def main():
    samples = [
        "Hello @user1, how are you @user2?",
        "No mentions here.",
        "@ann @bob @ann @ann @ann win now",
        "Thanks @maria_99 for the 2.25 kg cake and the 0.5 litre juice!",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)
    total = sum(len(extract_mentions(s)) for s in samples)
    print("total mentions: %d (avg %.2f per sample)" % (total, total / float(len(samples))))


if __name__ == "__main__":
    main()

