def validate_inputs(values, weights):
    """Check that values and weights form a usable weighted data set."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("cannot average an empty data set")
    for w in weights:
        if w < 0.0:
            raise ValueError("weights must be non-negative")
    if sum(weights) == 0.0:
        raise ValueError("the sum of the weights must be non-zero")


def weighted_average(values, weights):
    """Return the weighted average of values with the given weights."""
    validate_inputs(values, weights)
    total = 0.0
    for value, weight in zip(values, weights):
        total += value * weight
    return total / sum(weights)


def normalize_weights(weights):
    """Rescale weights so that they sum to one."""
    total = sum(weights)
    return [w / total for w in weights]


def uniform_weights(count):
    """Equal normalized weights for a data set of the given size."""
    return normalize_weights([1.0] * count)


def weighted_variance(values, weights):
    """Population variance of values around their weighted average."""
    avg = weighted_average(values, weights)
    squares = [(value - avg) ** 2 for value in values]
    return weighted_average(squares, weights)


def weighted_median(values, weights):
    """Value at which the cumulative normalized weight reaches one half."""
    pairs = sorted(zip(values, weights))
    fractions = normalize_weights([pair[1] for pair in pairs])
    cumulative = 0.0
    for pair, fraction in zip(pairs, fractions):
        cumulative += fraction
        if cumulative >= 0.5:
            return float(pair[0])
    return float(pairs[-1][0])


def format_report(name, values, weights):
    """One-line summary of a weighted data set."""
    avg = weighted_average(values, weights)
    spread = weighted_variance(values, weights) ** 0.5
    median = weighted_median(values, weights)
    return "%-12s mean=%7.3f std=%7.3f median=%7.3f" % (name, avg, spread, median)


def main():
    print(weighted_average([10, 20, 30], [1, 2, 1]))
    print(weighted_average([5, 10], uniform_weights(2)))
    print(format_report("scores", [10, 20, 30], [1, 2, 1]))
    print(format_report("grades", [4, 3, 2], [3, 4, 2]))


if __name__ == "__main__":
    main()

