SEVERITY_WEIGHTS = {
    "DEBUG": 0.25,
    "INFO": 0.5,
    "WARNING": 1.0,
    "ERROR": 2.0,
    "CRITICAL": 4.0,
}

SEPARATOR = " - "
DEGRADED_SEVERITY = 2.0
WATCH_SEVERITY = 1.0
DEGRADED_RATIO = 0.5
WATCH_RATIO = 0.25


def parse_log_line(log_line):
    """Split 'Timestamp - Level - Message' into its three named fields."""
    if not isinstance(log_line, str):
        raise TypeError("log_line must be a string")
    parts = log_line.strip().split(SEPARATOR, 2)
    if len(parts) != 3:
        raise ValueError("log line must contain timestamp, level and message")
    timestamp, level, message = (part.strip() for part in parts)
    if not timestamp or not level:
        raise ValueError("timestamp and level must not be empty")
    parsed_log = {
        "timestamp": timestamp,
        "level": level.upper(),
        "message": message,
    }
    return parsed_log


def parse_log_lines(lines):
    """Parse every non-blank line, skipping the ones that are malformed."""
    entries = []
    for line in lines:
        if not line.strip():
            continue
        try:
            entries.append(parse_log_line(line))
        except (TypeError, ValueError):
            continue
    return entries


def severity_of(entry):
    return SEVERITY_WEIGHTS.get(entry["level"], WATCH_SEVERITY)


def summarize(entries):
    total = len(entries)
    counts = {}
    for entry in entries:
        counts[entry["level"]] = counts.get(entry["level"], 0) + 1
    mean_severity = 0.0
    error_ratio = 0.0
    if total:
        mean_severity = sum(severity_of(e) for e in entries) / total
        bad = counts.get("ERROR", 0) + counts.get("CRITICAL", 0)
        error_ratio = bad / total
    return {
        "total": total,
        "counts": counts,
        "mean_severity": mean_severity,
        "error_ratio": error_ratio,
    }


def health_status(summary):
    if summary["error_ratio"] >= DEGRADED_RATIO:
        return "DEGRADED"
    if summary["mean_severity"] >= DEGRADED_SEVERITY:
        return "DEGRADED"
    if summary["error_ratio"] >= WATCH_RATIO:
        return "WATCH"
    if summary["mean_severity"] >= WATCH_SEVERITY:
        return "WATCH"
    return "HEALTHY"


def format_report(summary):
    lines = ["entries: %d" % summary["total"]]
    total = summary["total"] or 1
    for level, count in sorted(summary["counts"].items()):
        share = 100.0 * count / total
        lines.append("  %-8s %3d  (%5.1f%%)" % (level, count, share))
    lines.append("mean severity: %.2f" % summary["mean_severity"])
    lines.append("error ratio:   %.2f" % summary["error_ratio"])
    lines.append("status: " + health_status(summary))
    return "\n".join(lines)


def main():
    raw = [
        "2023-10-26 10:30:00 - INFO - User logged in.",
        "2023-10-26 10:45:12 - DEBUG - Cache warmed in 0.75 seconds.",
        "2023-10-26 11:00:00 - ERROR - File not found.",
        "2023-10-26 11:05:41 - WARNING - Disk usage above 90%.",
        "malformed line without separators",
    ]
    entries = parse_log_lines(raw)
    for entry in entries:
        print("%s [%s] %s" % (entry["timestamp"], entry["level"], entry["message"]))
    print()
    print(format_report(summarize(entries)))


if __name__ == "__main__":
    main()

