def duplicated_characters(text):
    """Characters appearing more than once, in order of first appearance."""
    counts = Counter(text)
    result = []
    for char in text:
        if counts[char] > 1 and char not in result:
            result.append(char)
    return result


def classify(ratio):
    """Label a uniqueness ratio on a coarse scale."""
    if ratio >= 1.:
        return "all unique"
    if ratio >= .75:
        return "mostly unique"
    if ratio >= .5:
        return "half repeated"
    return "heavily repeated"


def average_repeat_length(text):
    """Mean number of occurrences per distinct character."""
    distinct = len(set(text))
    if distinct == 0:
        return 0.
    return len(text) / distinct


def describe(text):
    ratio = uniqueness_ratio(text)
    lines = ["%-12r unique=%s ratio=%.2f (%s)" % (
        text, has_unique_chars(text), ratio, classify(ratio))]
    repeats = duplicated_characters(text)
    if repeats:
        lines.append("    repeated: %s | avg occurrences %.2f" % (
            ", ".join(repeats), average_repeat_length(text)))
    return "\n".join(lines)


def main():
    samples = ["abcde", "hello", "", "Aa", "abcdea", "mississippi", "Python 3.11"]
    for sample in samples:
        print(describe(sample))
    ratios = [uniqueness_ratio(s) for s in samples]
    overall = sum(ratios) / len(ratios)
    print("mean ratio over %d samples: %.3f" % (len(samples), overall))
    strict = [s for s, r in zip(samples, ratios) if r > .5]
    print("above 0.5 threshold:", strict)


