import math


def digits_of(number):
    """Return the decimal digits of a number's magnitude, most significant first."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    return [int(ch) for ch in str(abs(number))]


def sort_digits(number):
    """Return the integer formed by sorting the digits of `number` ascending."""
    ordered = sorted(digits_of(number))
    sorted_number = int("".join(str(d) for d in ordered))
    return -sorted_number if number < 0 else sorted_number


def digit_mean(number):
    """Average value of the digits."""
    ds = digits_of(number)
    return sum(ds) / len(ds)


def digit_median(number):
    """Median digit; for an even count, the midpoint of the two central digits."""
    ds = sorted(digits_of(number))
    middle = len(ds) // 2
    if len(ds) % 2 == 1:
        return float(ds[middle])
    return (ds[middle - 1] + ds[middle]) / 2.0


def digit_spread(number):
    """Range of the digits normalised onto the interval from zero to one."""
    ds = digits_of(number)
    return (max(ds) - min(ds)) / 9.0


def zero_percentage(number):
    """Share of digits that are zero, in percent."""
    ds = digits_of(number)
    return 100.0 * ds.count(0) / len(ds)


def round_half_up(value):
    """Round to the nearest integer, halves going away from zero."""
    if value < 0:
        return -int(math.floor(-value + 0.5))
    return int(math.floor(value + 0.5))


def classify_balance(number):
    """Compare the mean digit against the midpoint of the digit range."""
    offset = digit_mean(number) - 4.5
    if offset < -0.75:
        return "low-heavy"
    if offset > 0.75:
        return "high-heavy"
    return "balanced"


def describe(number):
    """One-line report about a number and its digit-sorted form."""
    return (
        f"{number:>12} -> {sort_digits(number):>12} | "
        f"mean {digit_mean(number):.2f} (~{round_half_up(digit_mean(number))}) | "
        f"median {digit_median(number):.1f} | "
        f"spread {digit_spread(number):.2f} | "
        f"zeros {zero_percentage(number):.1f}% | "
        f"{classify_balance(number)}"
    )


def main():
    samples = [321, 5049, 720, 9876543210, 1111, -4021, 8]
    for value in samples:
        print(describe(value))
    overall = sum(digit_mean(v) for v in samples) / len(samples)
    print(f"overall mean digit across samples: {overall:.3f}")


if __name__ == "__main__":
    main()

