import math

EXPECTED_RATIO = 1.0 / 15


def is_divisible_by_3_and_5(number):
    """Return True when number is a multiple of both 3 and 5."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    return number % 15 == 0


def divisible_ratio(numbers):
    """Fraction of the given values that are multiples of 15."""
    values = list(numbers)
    if not values:
        return 0.0
    hits = sum(1 for value in values if is_divisible_by_3_and_5(value))
    return hits / float(len(values))


def deviation_from_expected(ratio):
    """Signed distance between an observed ratio and the ideal 1/15 density."""
    return ratio - EXPECTED_RATIO


def classify_ratio(ratio):
    """Describe how dense the multiples of 15 are inside a sample."""
    if ratio >= 0.75:
        return "saturated"
    if ratio >= 0.5:
        return "majority"
    if ratio >= 0.25:
        return "frequent"
    if ratio > 0.0:
        return "sparse"
    return "none"


def as_percent(ratio, digits=2):
    """Convert a ratio to a percentage, rounding halves away from zero."""
    scale = 10.0 ** digits
    scaled = ratio * 100 * scale
    if scaled < 0.0:
        return -math.floor(-scaled + 0.5) / scale
    return math.floor(scaled + 0.5) / scale


def describe(number):
    verdict = "divisible" if is_divisible_by_3_and_5(number) else "not divisible"
    return "{0:>5} is {1} by 3 and 5".format(number, verdict)


def report(numbers):
    """Build a multi-line report for a collection of integers."""
    lines = [describe(number) for number in numbers]
    ratio = divisible_ratio(numbers)
    lines.append("matches: {0}% of the sample ({1})".format(as_percent(ratio), classify_ratio(ratio)))
    drift = deviation_from_expected(ratio)
    lines.append("drift vs 1/15 density: {0:+.4f}".format(drift))
    if abs(drift) > 0.5 * EXPECTED_RATIO:
        lines.append("note: sample density is far from a uniform integer range")
    return "\n".join(lines)


def main():
    print(report([15, 10, 30, 7, 45, 0, -15, 21]))
    print()
    print(report(list(range(1, 61))))


if __name__ == "__main__":
    main()

