def _missing_key_message(index, key):
    return "record {} has no key {!r}".format(index, key)


def validate_records(dict_list, key):
    """Check that every record is a dict carrying `key`; raise otherwise."""
    if not isinstance(dict_list, list):
        raise TypeError("dict_list must be a list")
    for index, record in enumerate(dict_list):
        if not isinstance(record, dict):
            raise TypeError("record {} is not a dict".format(index))
        if key not in record:
            raise KeyError(_missing_key_message(index, key))


def sort_dicts_by_key(dict_list, key):
    """Return a new list of the dicts ordered by the value stored under key."""
    validate_records(dict_list, key)
    return sorted(dict_list, key=lambda record: record[key])


def median_of_key(dict_list, key):
    """Median of the numeric values under key, 0.0 for an empty input."""
    values = [record[key] for record in sort_dicts_by_key(dict_list, key)]
    if not values:
        return 0.0
    middle = len(values) // 2
    if len(values) % 2 == 1:
        return float(values[middle])
    return (values[middle - 1] + values[middle]) * 0.5


def mean_of_key(dict_list, key):
    """Arithmetic mean of the values under key, 0.0 for an empty input."""
    if not dict_list:
        return 0.0
    total = 0.0
    for record in dict_list:
        total += record[key]
    return total / len(dict_list)


def skew_hint(dict_list, key):
    """Describe how far the mean sits from the median, in median units."""
    median = median_of_key(dict_list, key)
    mean = mean_of_key(dict_list, key)
    if median == 0.0:
        return "undefined"
    ratio = mean / median
    if ratio > 1.0:
        return "mean above median (x{:.2f})".format(ratio)
    if ratio < 1.0:
        return "mean below median (x{:.2f})".format(ratio)
    return "symmetric"


def format_table(dict_list, key):
    """Render the records sorted by key as aligned "value | rest" lines."""
    ordered = sort_dicts_by_key(dict_list, key)
    width = max([len(str(r[key])) for r in ordered], default=0)
    lines = []
    for record in ordered:
        rest = ", ".join(
            "{}={}".format(name, record[name]) for name in sorted(record) if name != key
        )
        lines.append("{:>{w}} | {}".format(record[key], rest, w=width))
    return "\n".join(lines)


def main():
    people = [{'name': 'B', 'age': 30}, {'name': 'A', 'age': 20}]
    print(sort_dicts_by_key(people, 'age'))
    print(sort_dicts_by_key([{'id': 2}, {'id': 1}], 'id'))

    scores = [
        {'player': 'ida', 'score': 2.25},
        {'player': 'jon', 'score': 0.75},
        {'player': 'kai', 'score': 1.0},
        {'player': 'lea', 'score': 4.5},
    ]
    print(format_table(scores, 'score'))
    print("median:", median_of_key(scores, 'score'))
    print("mean:", round(mean_of_key(scores, 'score'), 2))
    print("shape:", skew_hint(scores, 'score'))


if __name__ == "__main__":
    main()

