MINUTES_PER_HOUR = 60
MINUTES_PER_DAY = 24 * MINUTES_PER_HOUR


def minutes_to_hh_mm(total_minutes):
    """Format a whole number of minutes as 'HH:MM'."""
    if not isinstance(total_minutes, int) or isinstance(total_minutes, bool):
        raise TypeError("total_minutes must be an int")
    if total_minutes < 0:
        raise ValueError("total_minutes must not be negative")
    hours, minutes = divmod(total_minutes, MINUTES_PER_HOUR)
    return "{:02d}:{:02d}".format(hours, minutes)


def parse_hh_mm(text):
    """Turn an 'HH:MM' string back into a total minute count."""
    hours_text, _, minutes_text = text.partition(":")
    hours = int(hours_text)
    minutes = int(minutes_text)
    if not 0 <= minutes < MINUTES_PER_HOUR:
        raise ValueError("minute field out of range: " + text)
    return hours * MINUTES_PER_HOUR + minutes


def decimal_hours(total_minutes):
    """Express the duration as hours with a fractional part, e.g. 1.5."""
    return total_minutes / MINUTES_PER_HOUR


def fraction_of_day(total_minutes):
    """Share of a full 24 hour day, clamped to the range 0.0 .. 1.0."""
    share = total_minutes / MINUTES_PER_DAY
    if share > 1.0:
        return 1.0
    return share


def round_to_quarter_hour(total_minutes):
    """Snap a duration to the nearest quarter of an hour."""
    quarters = decimal_hours(total_minutes) / 0.25
    nearest = int(quarters + 0.5)
    return int(nearest * 0.25 * MINUTES_PER_HOUR)


def describe(total_minutes):
    """One-line report combining the formats above."""
    formatted = minutes_to_hh_mm(total_minutes)
    snapped = minutes_to_hh_mm(round_to_quarter_hour(total_minutes))
    percent = fraction_of_day(total_minutes) * 100.0
    return "{} = {:.2f} h ({:.1f}% of a day), nearest quarter {}".format(
        formatted, decimal_hours(total_minutes), percent, snapped
    )


def midpoint(start_text, end_text):
    """Halfway point between two 'HH:MM' stamps, as 'HH:MM'."""
    start = parse_hh_mm(start_text)
    end = parse_hh_mm(end_text)
    if end < start:
        end += MINUTES_PER_DAY
    middle = (start + end) * 0.5
    return minutes_to_hh_mm(int(middle + 0.5) % MINUTES_PER_DAY)


def main():
    for value in (0, 70, 135, 599, 1440, 2000):
        print(describe(value))
    print("round trip of '24:00':", minutes_to_hh_mm(parse_hh_mm("24:00")))
    print("midpoint 09:00-17:30:", midpoint("09:00", "17:30"))
    print("midpoint 22:15-05:45:", midpoint("22:15", "05:45"))


if __name__ == "__main__":
    main()

