def validate_matrix(matrix, name):
    if not isinstance(matrix, list) or not matrix:
        raise ValueError(name + " must be a non-empty list of rows")
    width = None
    for row in matrix:
        if not isinstance(row, list):
            raise ValueError(name + " must contain only lists as rows")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(name + " has rows of differing length")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(name + " must contain only numbers")
    return len(matrix), width


def matrix_subtract(matrix1, matrix2):
    shape1 = validate_matrix(matrix1, "matrix1")
    shape2 = validate_matrix(matrix2, "matrix2")
    if shape1 != shape2:
        raise ValueError("matrices must have the same dimensions")
    result_matrix = []
    for row1, row2 in zip(matrix1, matrix2):
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def scale_matrix(matrix, factor):
    validate_matrix(matrix, "matrix")
    return [[value * factor for value in row] for row in matrix]


def midpoint_matrix(matrix1, matrix2):
    difference = matrix_subtract(matrix1, matrix2)
    halved = scale_matrix(difference, 0.5)
    return matrix_subtract(matrix1, halved)


def frobenius_norm(matrix):
    validate_matrix(matrix, "matrix")
    total = 0.0
    for row in matrix:
        for value in row:
            total += float(value) * float(value)
    return total ** 0.5


def max_abs_entry(matrix):
    validate_matrix(matrix, "matrix")
    return max(abs(value) for row in matrix for value in row)


def matrices_close(matrix1, matrix2, tolerance=1.0e-9):
    return max_abs_entry(matrix_subtract(matrix1, matrix2)) <= tolerance


def format_matrix(matrix, precision=2):
    validate_matrix(matrix, "matrix")
    cells = [["{0:.{1}f}".format(float(v), precision) for v in row] for row in matrix]
    width = max(len(text) for row in cells for text in row)
    lines = []
    for row in cells:
        lines.append("[ " + "  ".join(text.rjust(width) for text in row) + " ]")
    return "\n".join(lines)


def main():
    print(matrix_subtract([[1, 2], [3, 4]], [[1, 1], [1, 1]]))
    print(matrix_subtract([[5, 0]], [[1, -1]]))

    readings = [[2.25, 4], [8, 1.75]]
    baseline = [[0.75, 4], [7, 2]]
    drift = matrix_subtract(readings, baseline)
    print(format_matrix(drift))
    print("norm = {0:.4f}".format(frobenius_norm(drift)))

    if max_abs_entry(drift) > 1.0:
        print("drift exceeds the allowed margin of 1.0 units")

    centre = midpoint_matrix(readings, baseline)
    print(format_matrix(centre, precision=3))
    rebuilt = matrix_subtract(centre, scale_matrix(drift, -0.5))
    print("midpoint check:", matrices_close(rebuilt, readings))


if __name__ == "__main__":
    main()

