def flatten_dict(nested_dict, separator='_'):
    """Flatten a dictionary with at most one level of nesting."""
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    if not isinstance(separator, str) or not separator:
        raise ValueError("separator must be a non-empty string")
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                flattened_dict[f"{key}{separator}{inner_key}"] = inner_value
        else:
            flattened_dict[key] = value
    return flattened_dict


def unflatten_dict(flat_dict, separator='_'):
    """Rebuild the two-level dictionary produced by flatten_dict."""
    nested = {}
    for key, value in flat_dict.items():
        if separator in key:
            outer, inner = key.split(separator, 1)
            nested.setdefault(outer, {})[inner] = value
        else:
            nested[key] = value
    return nested


def numeric_values(flat_dict):
    return {k: v for k, v in flat_dict.items()
            if isinstance(v, (int, float)) and not isinstance(v, bool)}


def numeric_summary(flat_dict):
    numbers = numeric_values(flat_dict)
    if not numbers:
        return {"count": 0, "mean": 0.0, "minimum": None, "maximum": None}
    total = 0.0
    for value in numbers.values():
        total += value
    return {"count": len(numbers), "mean": total / len(numbers),
            "minimum": min(numbers.values()), "maximum": max(numbers.values())}


def scale_values(flat_dict, factor):
    scaled = dict(flat_dict)
    for key, value in numeric_values(flat_dict).items():
        scaled[key] = value * factor
    return scaled


def normalize_values(flat_dict):
    """Rescale numeric entries so that the largest one becomes 1.0."""
    numbers = numeric_values(flat_dict)
    peak = max((abs(v) for v in numbers.values()), default=0.0)
    if peak == 0:
        return dict(flat_dict)
    return scale_values(flat_dict, 1.0 / peak)


def format_report(flat_dict, separator='_'):
    mean = numeric_summary(flat_dict)["mean"]
    lines = []
    for key in sorted(flat_dict):
        value = flat_dict[key]
        if isinstance(value, float):
            shown = f"{value:.3f}"
        else:
            shown = str(value)
        marker = " *" if isinstance(value, float) and value >= mean else ""
        lines.append(f"{key.replace(separator, ' > ')}: {shown}{marker}")
    return "\n".join(lines)


def main():
    volume = {"master": 0.75}
    volume["music"] = 0.5
    mixer = {"gain": 2.25, "volume": volume, "preset": "live"}
    flat = flatten_dict(mixer, ".")
    print(flat)
    print(flatten_dict({"a": 1, "b": {"c": 2, "d": 3}}, "_"))
    print(flatten_dict({"x": {"y": 10}}, "."))

    boosted = scale_values(flat, 1.5)
    normalized = normalize_values(boosted)
    print(format_report(normalized, "."))
    print(numeric_summary(normalized))
    print(unflatten_dict(normalized, ".") == unflatten_dict(flat, "."))


if __name__ == "__main__":
    main()

