"""Reverse the characters of each word in a sentence, keeping word order,
plus a small reporting layer over the transformation."""


def reverse_each_word(sentence):
    """Return the sentence with every word's characters reversed."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    return " ".join(word[::-1] for word in sentence.split(" "))


def split_words(sentence):
    """Return the non-empty whitespace-separated words of the sentence."""
    return [word for word in sentence.split() if word]


def average_word_length(words):
    """Mean number of characters per word (0.0 for an empty word list)."""
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def palindrome_ratio(words):
    """Fraction of words that are unchanged by reversal, case-insensitively."""
    if not words:
        return 0.0
    same = sum(1 for word in words if word.lower() == word[::-1].lower())
    return same / len(words)


def round_to_half(value):
    """Round a value to the nearest half step, for compact reporting."""
    steps = round(value / 0.5)
    return steps * 0.5


def format_percent(fraction):
    """Render a fraction between 0 and 1 as a percentage string."""
    return "{0:.1f}%".format(fraction * 100.0)


def classify_symmetry(ratio):
    """Describe how palindromic a sentence is, based on its ratio."""
    if ratio >= 0.75:
        return "highly symmetric"
    if ratio >= 0.5:
        return "half symmetric"
    if ratio > 0.0:
        return "slightly symmetric"
    return "asymmetric"


def describe(sentence):
    """Build a multi-line report about reversing the words of a sentence."""
    words = split_words(sentence)
    ratio = palindrome_ratio(words)
    mean_length = average_word_length(words)
    lines = [
        "input    : {0}".format(sentence),
        "reversed : {0}".format(reverse_each_word(sentence)),
        "words    : {0}".format(len(words)),
        "avg len  : {0:.2f} (~{1})".format(mean_length, round_to_half(mean_length)),
        "unchanged: {0} -> {1}".format(format_percent(ratio), classify_symmetry(ratio)),
    ]
    return "\n".join(lines)


def main():
    samples = [
        "hello world",
        "Python is fun",
        "madam noon level",
        "a racecar and a kayak",
        "",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)
    total = sum(palindrome_ratio(split_words(s)) for s in samples)
    print("mean symmetry across samples: {0}".format(format_percent(total / len(samples))))


if __name__ == "__main__":
    main()

