DEFAULT_COMMISSION_RATE = 0.0025
MIN_COMMISSION = 1.0

TRADE_DATA = """AAPL,10.00,12.00,100
MSFT,15.00,13.00,50
TSLA,240.50,241.25,40
KO,58.75,58.75,200"""


def validate_trade(buy_price, sell_price, quantity):
    """Reject trades that cannot describe a real stock transaction."""
    if buy_price <= 0.0:
        raise ValueError("buy_price must be positive")
    if sell_price <= 0.0:
        raise ValueError("sell_price must be positive")
    if quantity <= 0:
        raise ValueError("quantity must be a positive whole number of shares")


def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the raw profit (positive) or loss (negative) of one trade."""
    validate_trade(buy_price, sell_price, quantity)
    return (sell_price - buy_price) * quantity


def commission(price, quantity, rate=DEFAULT_COMMISSION_RATE):
    """Broker fee for one leg: a percentage of turnover, with a floor."""
    fee = price * quantity * rate
    return fee if fee > MIN_COMMISSION else MIN_COMMISSION


def net_profit(buy_price, sell_price, quantity, rate=DEFAULT_COMMISSION_RATE):
    """Profit after paying commission on both the buy and the sell leg."""
    gross = calculate_stock_profit(buy_price, sell_price, quantity)
    fees = commission(buy_price, quantity, rate) + commission(sell_price, quantity, rate)
    return gross - fees


def return_percentage(buy_price, sell_price, quantity):
    """Profit expressed as a percentage of the capital originally invested."""
    invested = buy_price * quantity
    return calculate_stock_profit(buy_price, sell_price, quantity) / invested * 100.0


def break_even_price(buy_price, quantity, rate=DEFAULT_COMMISSION_RATE):
    """Lowest sell price that still leaves the trade at zero or better."""
    low = buy_price
    high = buy_price * 2.0
    while high - low > 0.0001:
        mid = (low + high) * 0.5
        if net_profit(buy_price, mid, quantity, rate) < 0.0:
            low = mid
        else:
            high = mid
    return high


def verdict_for(gross):
    """One-word summary of how the trade ended."""
    if gross > 0.0:
        return "profit"
    if gross < 0.0:
        return "loss"
    return "flat"


def parse_trade(line):
    """Turn one 'SYMBOL,buy,sell,quantity' record into typed values."""
    symbol, buy, sell, quantity = line.split(",")
    return symbol.strip(), float(buy), float(sell), int(quantity)


def format_trade(symbol, buy_price, sell_price, quantity):
    gross = calculate_stock_profit(buy_price, sell_price, quantity)
    net = net_profit(buy_price, sell_price, quantity)
    pct = return_percentage(buy_price, sell_price, quantity)
    return (
        f"{symbol:<6}{quantity:>6} sh  "
        f"{buy_price:>8.2f} -> {sell_price:>8.2f}  "
        f"gross {gross:>10.2f}  net {net:>10.2f}  "
        f"{pct:>7.2f}%  break-even {break_even_price(buy_price, quantity):>8.2f}  "
        f"{verdict_for(gross)}"
    )


def main():
    trades = [parse_trade(line) for line in TRADE_DATA.splitlines()]
    for symbol, buy, sell, quantity in trades:
        print(format_trade(symbol, buy, sell, quantity))
    total = sum(net_profit(b, s, q) for _, b, s, q in trades)
    print(f"{'TOTAL':<6}{'':>6}      net across portfolio: {total:.2f}")


if __name__ == "__main__":
    main()

