import math

HEX_DIGITS = "0123456789ABCDEF"
BITS_PER_HEX_DIGIT = 4.0
HEX_DIGITS_PER_BYTE = 2.0


def decimal_to_hex(decimal_num):
    """Return the uppercase hexadecimal representation of an integer."""
    if isinstance(decimal_num, bool) or not isinstance(decimal_num, int):
        raise TypeError("decimal_to_hex expects an int")
    if decimal_num == 0:
        return "0"
    remaining = abs(decimal_num)
    digits = []
    while remaining > 0:
        digits.append(HEX_DIGITS[remaining % 16])
        remaining //= 16
    if decimal_num < 0:
        digits.append("-")
    return "".join(reversed(digits))


def hex_digit_count(decimal_num):
    return len(decimal_to_hex(decimal_num).lstrip("-"))


def byte_width(decimal_num):
    """Number of whole bytes needed to hold the value's magnitude."""
    return int(math.ceil(hex_digit_count(decimal_num) / HEX_DIGITS_PER_BYTE))


def padded_hex(decimal_num):
    """Hex string zero-padded to a whole number of bytes."""
    body = decimal_to_hex(decimal_num).lstrip("-")
    padded = body.rjust(byte_width(decimal_num) * 2, "0")
    return "-" + padded if decimal_num < 0 else padded


