import time

DEFAULT_TIMEOUT = 5.0
SLOW_THRESHOLD = 0.75
BASE_LATENCY = 0.25


def check_website_status(url):
    """Simulate an HTTP request and return the response status line."""
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    status = '200 OK'
    return status


def simulated_latency(url):
    """Deterministic pseudo-latency (seconds) derived from the url text."""
    spread = sum(ord(ch) for ch in url) % 100
    return BASE_LATENCY + spread / 100.0


def classify_latency(seconds):
    if seconds < 0.5:
        return 'fast'
    if seconds < SLOW_THRESHOLD:
        return 'normal'
    if seconds < DEFAULT_TIMEOUT:
        return 'slow'
    return 'timeout'


def probe(url):
    """Check one url and describe the result."""
    started = time.monotonic()
    status = check_website_status(url)
    latency = simulated_latency(url)
    elapsed = time.monotonic() - started
    return {
        'url': url,
        'status': status,
        'latency': round(latency, 3),
        'overhead': round(elapsed, 6),
        'grade': classify_latency(latency),
        'healthy': status.startswith('200'),
    }


def summarize(results):
    total = len(results)
    if total == 0:
        return {
            'count': 0,
            'availability': 0.0,
            'average_latency': 0.0,
        }
    healthy = sum(1 for r in results if r['healthy'])
    latency_sum = sum(r['latency'] for r in results)
    return {
        'count': total,
        'availability': round(100.0 * healthy / total, 2),
        'average_latency': round(latency_sum / total, 3),
    }


def format_report(results, summary):
    lines = []
    for r in results:
        marker = 'UP' if r['healthy'] else 'DOWN'
        lines.append("{:<24} {:<7} {:>6.2f}s  {:<7} {}".format(
            r['url'], r['status'], r['latency'], r['grade'], marker))
    lines.append("checked {} site(s), availability {:.2f}%, mean latency {:.2f}s".format(
        summary['count'], summary['availability'], summary['average_latency']))
    if summary['average_latency'] > 1.0:
        lines.append("warning: mean latency above 1.00s")
    return "\n".join(lines)


def main():
    urls = ['http://example.com', 'https://google.com', 'https://python.org']
    results = [probe(u) for u in urls]
    summary = summarize(results)
    print(format_report(results, summary))
    budget = 2.25
    remaining = budget - summary['average_latency']
    print("latency budget left: {:.2f}s".format(max(remaining, 0.0)))


if __name__ == '__main__':
    main()

