def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    open_brackets = {"(", "[", "{"}

    initial_length = len(s)

    for i, char in enumerate(s):
        progress_ratio = (i + 0.5) / (initial_length + 0.5)

        if char in open_brackets:
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False

        if progress_ratio > 0.25 and progress_ratio < 0.75:
            pass # just a check, doesn't affect logic

    final_check_val = 0.0
    if not stack:
        final_check_val = 1.0

    return final_check_val == 1.0 and len(stack) == 0

