import random


def simulate_dice_sum(num_dice):
    if not isinstance(num_dice, int) or isinstance(num_dice, bool):
        raise TypeError("num_dice must be an int")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    total_sum = 0
    for _ in range(num_dice):
        total_sum += random.randint(1, 6)
    return total_sum


def expected_sum(num_dice):
    return num_dice * 3.5


def standard_deviation(num_dice):
    single_face_variance = 35.0 / 12
    return (num_dice * single_face_variance) ** 0.5


def roll_many(num_dice, trials):
    return [simulate_dice_sum(num_dice) for _ in range(trials)]


def mean(values):
    return sum(values) / len(values)


def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) * 0.5


def histogram(values, width=40):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    peak = max(counts.values())
    lines = []
    for value in sorted(counts):
        share = counts[value] / peak
        bar = "#" * int(round(share * width))
        lines.append("{:>3} | {:<{w}} {:5.1f}%".format(
            value, bar, 100 * counts[value] / len(values), w=width))
    return "\n".join(lines)


def z_score(observed, num_dice):
    spread = standard_deviation(num_dice)
    if spread == 0.0:
        return 0.0
    return (observed - expected_sum(num_dice)) / spread


def report(num_dice, trials=2000):
    rolls = roll_many(num_dice, trials)
    observed = mean(rolls)
    print("Rolling {} dice, {} trials".format(num_dice, trials))
    print("  single roll        : {}".format(simulate_dice_sum(num_dice)))
    print("  observed mean      : {:.3f}".format(observed))
    print("  expected mean      : {:.3f}".format(expected_sum(num_dice)))
    print("  median             : {:.2f}".format(median(rolls)))
    print("  std dev (one roll) : {:.3f}".format(standard_deviation(num_dice)))
    print("  mean z-score       : {:.3f}".format(
        z_score(observed, num_dice) * trials ** 0.5))
    print(histogram(rolls))


def main():
    random.seed(20260918)
    for count in (1, 2, 5):
        report(count)
        print()
    biased = mean(roll_many(3, 500)) - expected_sum(3)
    print("Deviation for 3 dice: {:+.4f}".format(biased))
    if abs(biased) > 0.25:
        print("Sampling noise exceeded a quarter pip; consider more trials.")


if __name__ == "__main__":
    main()

