ROMAN_PAIRS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

SYMBOL_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def int_to_roman(num):
    if isinstance(num, bool) or not isinstance(num, int):
        raise TypeError("num must be an integer")
    if num < 1 or num > 3999:
        raise ValueError("num must be between 1 and 3999")
    remaining = num
    parts = []
    for value, symbol in ROMAN_PAIRS:
        count, remaining = divmod(remaining, value)
        parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(roman):
    total = 0
    previous = 0
    for char in reversed(roman.upper()):
        value = SYMBOL_VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    return total


def density(num):
    """Roman symbols used per decimal digit of num."""
    return len(int_to_roman(num)) / len(str(num))


def classify(ratio):
    if ratio <= 1.0:
        return "compact"
    if ratio <= 2.25:
        return "moderate"
    return "verbose"


def quantile(sorted_values, q):
    position = q * (len(sorted_values) - 1)
    low = int(position)
    high = min(low + 1, len(sorted_values) - 1)
    frac = position - low
    return sorted_values[low] * (1.0 - frac) + sorted_values[high] * frac


def summarize(numbers):
    ratios = sorted(density(n) for n in numbers)
    compact = sum(1 for r in ratios if classify(r) == "compact")
    return {
        "mean": sum(ratios) / len(ratios),
        "median": quantile(ratios, 0.5),
        "lower_quartile": quantile(ratios, 0.25),
        "upper_quartile": quantile(ratios, 0.75),
        "compact_percent": 100.0 * compact / len(ratios),
    }


def main():
    samples = [3, 9, 44, 400, 1994, 2024, 3888]
    print(f"{'number':>7} {'roman':<16} {'ratio':>6} class")
    for number in samples:
        roman = int_to_roman(number)
        if roman_to_int(roman) != number:
            raise AssertionError(f"round-trip failed for {number}")
        ratio = density(number)
        print(f"{number:>7} {roman:<16} {ratio:>6.2f} {classify(ratio)}")
    stats = summarize(samples)
    print(f"mean ratio       : {stats['mean']:.2f}")
    print(f"median ratio     : {stats['median']:.2f}")
    print(f"quartile spread  : {stats['upper_quartile'] - stats['lower_quartile']:.2f}")
    print(f"compact numerals : {stats['compact_percent']:.1f}%")


if __name__ == "__main__":
    main()

