import math


def _validate(numbers):
    """Check that `numbers` holds 1..N once each, with a single value twice."""
    n = len(numbers) - 1
    if n < 1:
        raise ValueError("at least two numbers are required")
    counts = {}
    for value in numbers:
        if not isinstance(value, int):
            raise TypeError("all entries must be integers")
        if value < 1 or value > n:
            raise ValueError("values must lie between 1 and %d" % n)
        counts[value] = counts.get(value, 0) + 1
    repeated = [value for value, hits in counts.items() if hits > 1]
    if len(repeated) != 1 or counts[repeated[0]] != 2 or len(counts) != n:
        raise ValueError("exactly one number must appear twice")
    return n


def find_duplicate(numbers):
    """Return the single number that occurs twice in `numbers`."""
    n = _validate(numbers)
    expected_sum = n * (n + 1) * 0.5
    duplicate_num = int(sum(numbers) - expected_sum)
    return duplicate_num


def duplicate_positions(numbers, duplicate_num):
    """Indices of the two copies of `duplicate_num`, in order."""
    return [index for index, value in enumerate(numbers) if value == duplicate_num]


def centre_offsets(numbers, duplicate_num):
    """Signed distance of each copy from the middle of the list."""
    midpoint = (len(numbers) - 1) * 0.5
    return [position - midpoint for position in duplicate_positions(numbers, duplicate_num)]


def gap_fraction(numbers, duplicate_num):
    """How far apart the copies sit, as a fraction of the whole list span."""
    first, second = duplicate_positions(numbers, duplicate_num)
    span = len(numbers) - 1.0
    return (second - first) / span


