    return int(math.floor(value + 0.5))


def describe_placement(numbers, duplicate_num):
    offsets = centre_offsets(numbers, duplicate_num)
    tolerance = len(numbers) * 0.25
    if all(abs(offset) <= tolerance for offset in offsets):
        return "clustered near the centre"
    if all(offset > tolerance for offset in offsets):
        return "pushed towards the tail"
    if all(offset < -tolerance for offset in offsets):
        return "pushed towards the head"
    return "straddling the centre"


