def validate_meeting(meeting):
    """Check that a meeting is a (start, end) pair of minute offsets."""
    if not isinstance(meeting, (tuple, list)) or len(meeting) != 2:
        raise ValueError("a meeting must be a (start, end) pair")
    start, end = meeting
    if not isinstance(start, int) or not isinstance(end, int):
        raise ValueError("meeting times must be integer minutes")
    if end < start:
        raise ValueError("meeting end must not precede its start")
    return start, end


def has_overlap(meeting1, meeting2):
    """Return True when the two meeting intervals share any time."""
    start1, end1 = validate_meeting(meeting1)
    start2, end2 = validate_meeting(meeting2)
    return start1 < end2 and start2 < end1


def overlap_minutes(meeting1, meeting2):
    """Number of minutes the two meetings have in common."""
    start1, end1 = validate_meeting(meeting1)
    start2, end2 = validate_meeting(meeting2)
    return max(0, min(end1, end2) - max(start1, start2))


def to_hours(minutes):
    """Convert a minute count to fractional hours."""
    return minutes / 60.0


def round_to_quarter(hours):
    """Round an hour value to the nearest quarter of an hour."""
    quarter = 0.25
    return round(hours / quarter) * quarter


def severity(hours):
    """Classify a clash by the number of overlapping hours."""
    if hours >= 1.0:
        return "major"
    if hours >= 0.5:
        return "moderate"
    if hours > 0.0:
        return "minor"
    return "none"


def format_clock(minutes):
    """Render minutes after midnight as HH:MM."""
    hour, minute = divmod(minutes, 60)
    return "{:02d}:{:02d}".format(hour, minute)


def format_span(meeting):
    start, end = validate_meeting(meeting)
    return "{}-{}".format(format_clock(start), format_clock(end))


def clash_report(schedule):
    """Build report lines for every clashing pair in a named schedule."""
    lines = []
    for index, (name1, meeting1) in enumerate(schedule):
        for name2, meeting2 in schedule[index + 1:]:
            if not has_overlap(meeting1, meeting2):
                continue
            hours = round_to_quarter(to_hours(overlap_minutes(meeting1, meeting2)))
            lines.append("{} ({}) vs {} ({}): {:.2f} h clash, {}".format(
                name1, format_span(meeting1), name2, format_span(meeting2),
                hours, severity(hours)))
    return lines


def main():
    schedule = [
        ("standup", (540, 555)),
        ("design review", (545, 645)),
        ("1:1", (660, 690)),
        ("planning", (630, 720)),
        ("retro", (900, 960)),
    ]
    for line in clash_report(schedule):
        print(line)

    booked = sum(end - start for _, (start, end) in schedule)
    workday = 480
    load = to_hours(booked) / to_hours(workday)
    print("booked {:.2f} h of an {:.1f} h day (load {:.2f})".format(
        to_hours(booked), to_hours(workday), load))
    if load > 0.75:
        print("schedule is overloaded; consider dropping a meeting")


if __name__ == "__main__":
    main()

