def validate_image(image_matrix):
    """Check that the input really is a rectangular RGB matrix."""
    if not image_matrix or not image_matrix[0]:
        raise ValueError("image must contain at least one pixel")
    width = len(image_matrix[0])
    for y, row in enumerate(image_matrix):
        if len(row) != width:
            raise ValueError("row %d has a different width" % y)
        for x, pixel in enumerate(row):
            if len(pixel) != 3:
                raise ValueError("pixel (%d,%d) is not an RGB triple" % (x, y))
            for channel in pixel:
                if channel < 0 or channel > 255:
                    raise ValueError("channel out of range at (%d,%d)" % (x, y))


def to_grayscale(image_matrix):
    """Average the R, G and B components of every pixel."""
    validate_image(image_matrix)
    grayscale_image = []
    for row in image_matrix:
        levels = []
        for pixel in row:
            average = sum(pixel) / 3.0
            levels.append(int(round(average)))
        grayscale_image.append(levels)
    return grayscale_image


def clamp_level(value):
    """Round a computed level and keep it inside the displayable range."""
    darkest = 0.0
    brightest = 255.0
    if value < darkest:
        return 0
    if value > brightest:
        return 255
    return int(round(value))


def adjust_brightness(gray_image, factor):
    """Scale every gray level by a constant factor."""
    brightened = []
    for row in gray_image:
        brightened.append([clamp_level(level * factor) for level in row])
    return brightened


def stretch_contrast(gray_image, strength):
    """Push levels away from mid gray, so darks deepen and lights brighten."""
    mid = 127.5
    gain = 1.0 + strength
    stretched = []
    for row in gray_image:
        stretched.append([clamp_level(mid + (level - mid) * gain) for level in row])
    return stretched


def gray_stats(gray_image):
    levels = [level for row in gray_image for level in row]
    count = len(levels)
    mean = sum(levels) / float(count)
    variance = sum((level - mean) ** 2 for level in levels) / float(count)
    std = variance ** 0.5
    bright = sum(1 for level in levels if level > mean)
    bright_share = bright * 100.0 / count
    return {"mean": mean, "std": std, "bright_share": bright_share}


def to_ascii(gray_image, ramp="@%#*+=-:. "):
    top = len(ramp) - 1
    lines = []
    for row in gray_image:
        glyphs = []
        for level in row:
            position = level / 255.0 * top
            glyphs.append(ramp[int(position)])
        lines.append("".join(glyphs))
    return "\n".join(lines)


def report(title, gray_image):
    stats = gray_stats(gray_image)
    print("%s: mean=%.2f std=%.2f bright=%.1f%%"
          % (title, stats["mean"], stats["std"], stats["bright_share"]))
    print(to_ascii(gray_image))


def main():
    print(to_grayscale([[[255, 0, 0], [0, 255, 0]]]))
    print(to_grayscale([[[10, 20, 30]]]))
    picture = [
        [[255, 240, 230], [200, 190, 180], [120, 110, 100], [30, 20, 10]],
        [[210, 200, 195], [160, 150, 140], [90, 80, 70], [15, 10, 5]],
        [[180, 170, 160], [130, 120, 110], [60, 50, 40], [5, 5, 0]],
    ]
    gray = to_grayscale(picture)
    report("gray", gray)
    report("bright", adjust_brightness(gray, 1.4))
    report("dim", adjust_brightness(gray, 0.6))
    report("punchy", stretch_contrast(gray, 0.5))


if __name__ == "__main__":
    main()

