import re


def count_keyword_occurrences(text, keyword):
    """Count case-insensitive occurrences of keyword in text."""
    if not isinstance(text, str) or not isinstance(keyword, str):
        raise TypeError("text and keyword must be strings")
    needle = keyword.strip().lower()
    if not needle:
        return 0
    return text.lower().count(needle)


def word_count(text):
    """Number of word-like tokens in the text."""
    return len(re.findall(r"[\w']+", text))


def keyword_density(text, keyword):
    """Percentage of the text's words taken up by the keyword."""
    total = word_count(text)
    if total == 0:
        return 0.0
    hits = count_keyword_occurrences(text, keyword)
    weight = word_count(keyword) or 1
    return 100.0 * hits * weight / total


def classify_density(density):
    """Label a density value using common SEO rules of thumb."""
    if density < 0.5:
        return "sparse"
    if density <= 2.5:
        return "balanced"
    return "over-used"


def relevance_score(text, keyword):
    """Blend raw frequency and density into a 0..10 score."""
    hits = count_keyword_occurrences(text, keyword)
    if hits == 0:
        return 0.0
    density = keyword_density(text, keyword)
    frequency_part = min(hits, 10) * 0.75
    density_part = min(density, 2.5)
    return round(min(frequency_part + density_part, 10.0), 2)


def first_position_ratio(text, keyword):
    """How far into the text the keyword first appears (0.0 = very start)."""
    needle = keyword.strip().lower()
    if not needle or not text:
        return 1.0
    index = text.lower().find(needle)
    if index < 0:
        return 1.0
    return round(index / len(text), 4)


def analyse(text, keyword):
    """Full report for one keyword against one body of text."""
    density = keyword_density(text, keyword)
    return {
        "keyword": keyword,
        "count": count_keyword_occurrences(text, keyword),
        "words": word_count(text),
        "density": round(density, 2),
        "verdict": classify_density(density),
        "score": relevance_score(text, keyword),
        "position": first_position_ratio(text, keyword),
    }


def format_report(report):
    bar_units = int(round(report["score"] / 0.5))
    return (
        "{keyword:<10} count={count:<3} density={density:>5.2f}% "
        "{verdict:<10} score={score:>5.2f} [{bar}]"
    ).format(bar="#" * bar_units, **report)


def main():
    sample = (
        "Python is fun. Hello world, hello Python! Learning Python "
        "makes automation fun, and Python keeps the work readable."
    )
    for keyword in ("hello", "python", "java", "fun"):
        print(format_report(analyse(sample, keyword)))
    print("total words:", word_count(sample))


if __name__ == "__main__":
    main()

