NUMERIC_THRESHOLD = 0.75
HEAVY_THRESHOLD = 0.5
MIXED_THRESHOLD = 0.25
SPREAD_THRESHOLD = 2.25
PERCENT_SCALE = 100.0


def extract_numbers(text):
    """Return every decimal digit of *text*, concatenated in order."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    return "".join(ch for ch in text if "0" <= ch <= "9")


def digit_ratio(text):
    """Fraction of the characters of *text* that are digits."""
    if not text:
        return 0.0
    return len(extract_numbers(text)) / len(text)


def digit_percentage(text):
    return digit_ratio(text) * PERCENT_SCALE


def density_label(ratio):
    if ratio >= NUMERIC_THRESHOLD:
        return "numeric"
    if ratio >= HEAVY_THRESHOLD:
        return "digit-heavy"
    if ratio >= MIXED_THRESHOLD:
        return "mixed"
    if ratio > 0.0:
        return "sparse"
    return "none"


def digit_mean(digits):
    """Average value of the digits in the string *digits*."""
    if not digits:
        return 0.0
    return sum(int(d) for d in digits) / len(digits)


def digit_spread(digits):
    """Standard deviation of the digit values."""
    if len(digits) < 2:
        return 0.0
    mean = digit_mean(digits)
    variance = sum((int(d) - mean) ** 2 for d in digits) / len(digits)
    return variance ** 0.5


def digit_runs(text):
    """Maximal groups of consecutive digits, in order of appearance."""
    runs, current = [], ""
    for ch in text:
        if "0" <= ch <= "9":
            current += ch
        elif current:
            runs.append(current)
            current = ""
    if current:
        runs.append(current)
    return runs


def mean_run_length(text):
    runs = digit_runs(text)
    if not runs:
        return 0.0
    return sum(len(r) for r in runs) / len(runs)


def describe(text):
    digits = extract_numbers(text)
    ratio = digit_ratio(text)
    parts = [
        "digits=%r" % digits,
        "density=%s (%.1f%%)" % (density_label(ratio), digit_percentage(text)),
        "mean=%.2f" % digit_mean(digits),
        "runs=%d avg_len=%.2f" % (len(digit_runs(text)), mean_run_length(text)),
    ]
    if digit_spread(digits) >= SPREAD_THRESHOLD:
        parts.append("well spread")
    elif ratio >= HEAVY_THRESHOLD:
        parts.append("repetitive")
    return " | ".join(parts)


def main():
    samples = [
        "abc123def45",
        "No numbers here.",
        "order 7 of 1000 shipped on 2024-05-31",
        "9999",
        "pi is about 3.14159 and e is 2.71828",
    ]
    for sample in samples:
        print("%-42s -> %s" % (repr(sample), describe(sample)))


if __name__ == "__main__":
    main()

