def _validate(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of int/float")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("numbers[%d] is not a number: %r" % (index, value))
    return list(numbers)


def is_sorted(numbers):
    """Return True when the values are in ascending (non-decreasing) order."""
    values = _validate(numbers)
    for left, right in zip(values, values[1:]):
        if left > right:
            return False
    return True


def ascending_fraction(numbers):
    """Share of adjacent pairs that are in ascending order."""
    values = _validate(numbers)
    pairs = len(values) - 1
    if pairs <= 0:
        return 1.0
    good = sum(1 for i in range(pairs) if values[i] <= values[i + 1])
    return good / float(pairs)


def largest_drop(numbers):
    """Size of the biggest downward step; zero when the list is ascending."""
    values = _validate(numbers)
    drop = 0.0
    for index in range(1, len(values)):
        step = values[index - 1] - values[index]
        if step > drop:
            drop = float(step)
    return drop


def order_score(numbers):
    """Ordering quality between zero and one: good pairs, minus drop penalty."""
    drop = largest_drop(numbers)
    penalty = drop / (drop + 1.0)
    return ascending_fraction(numbers) * (1.0 - penalty)


def first_descent(numbers):
    """Index of the first element that breaks the ascending order, else None."""
    values = _validate(numbers)
    for index in range(1, len(values)):
        if values[index - 1] > values[index]:
            return index
    return None


def describe(numbers):
    """Human readable one-line verdict about the ordering of *numbers*."""
    if is_sorted(numbers):
        return "%r -> sorted ascending" % (list(numbers),)
    score = order_score(numbers)
    verdict = "mostly ascending" if score >= 0.5 else "poorly ordered"
    return "%r -> not sorted (%s, score %.2f, %.1f%% ordered pairs, first break at index %d, largest drop %.2f)" % (
        list(numbers),
        verdict,
        score,
        ascending_fraction(numbers) * 100.0,
        first_descent(numbers),
        largest_drop(numbers),
    )


def main():
    samples = [
        [1, 2, 3, 4],
        [1, 3, 2],
        [3, 3, 3],
        [7],
        [],
        [1, 2, 10, 4, 5, 6],
    ]
    for sample in samples:
        print(describe(sample))
    ordered = sum(1 for sample in samples if is_sorted(sample))
    average = sum(order_score(sample) for sample in samples) / len(samples)
    print("%d of %d sorted, average score %.2f" % (ordered, len(samples), average))


if __name__ == "__main__":
