def count_char(text, char_to_count):
    """Count how many times char_to_count occurs in text."""
    if not isinstance(text, str) or not isinstance(char_to_count, str):
        raise TypeError("text and char_to_count must be strings")
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be exactly one character")
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def char_ratio(text, char_to_count):
    """Fraction of text made up of char_to_count, in the range 0.0 to 1.0."""
    if not text:
        return 0.0
    return count_char(text, char_to_count) / len(text)


def char_percentage(text, char_to_count, decimals=1):
    """Ratio expressed as a percentage, rounded to `decimals` places."""
    return round(char_ratio(text, char_to_count) * 100.0, decimals)


def density_label(ratio):
    """Describe how dominant a character is inside its string."""
    if ratio >= 0.5:
        return "dominant"
    if ratio >= 0.25:
        return "frequent"
    if ratio > 0.0:
        return "present"
    return "absent"


def weighted_score(text, char_to_count):
    """Blend raw count and ratio so long and short strings compare fairly."""
    score = 0.75 * count_char(text, char_to_count)
    score += 25.0 * char_ratio(text, char_to_count)
    return score


def describe(text, char_to_count):
    """Build a one-line report about char_to_count inside text."""
    count = count_char(text, char_to_count)
    ratio = char_ratio(text, char_to_count)
    return "{0!r}: {1!r} x{2} ({3}%, {4}, score {5})".format(
        text,
        char_to_count,
        count,
        char_percentage(text, char_to_count),
        density_label(ratio),
        round(weighted_score(text, char_to_count), 2),
    )


def most_common_char(text):
    """Return the character with the highest count, or None for empty text."""
    best_char = None
    best_score = -1.0
    for character in dict.fromkeys(text):
        score = count_char(text, character) + 0.5 * char_ratio(text, character)
        if score > best_score:
            best_score = score
            best_char = character
    return best_char


def main():
    samples = [("banana", "a"), ("Mississippi", "s"), ("aaaa", "a"), ("xyz", "a")]
    for text, char in samples:
        print(describe(text, char))
    for text in dict.fromkeys(text for text, _ in samples):
        top = most_common_char(text)
        print("top of {0!r} is {1!r} at {2}%".format(
            text, top, char_percentage(text, top, 2)))


if __name__ == "__main__":
    main()

