def merge_dicts(dict1, dict2):
    """Merge two dictionaries; values from dict2 win on conflicting keys."""
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("merge_dicts expects two dictionaries")
    merged = dict(dict1)
    merged.update(dict2)
    return merged


def merge_all(*dicts):
    """Fold any number of dictionaries left to right using merge_dicts."""
    result = {}
    for candidate in dicts:
        result = merge_dicts(result, candidate)
    return result


DEFAULT_SETTINGS = {
    "learning_rate": .5,
    "momentum": .75,
    "dropout": .25,
    "weight_scale": 2.25,
    "grad_clip": 1.,
    "epochs": 10,
    "optimizer": "sgd",
}

RATIO_FIELDS = ("momentum", "dropout")
RATIO_LOWER = .0
RATIO_UPPER = 1.


def clamp(value, lower, upper):
    """Restrict a number to the inclusive range [lower, upper]."""
    return max(lower, min(upper, value))


def clamp_fields(config, fields, lower=RATIO_LOWER, upper=RATIO_UPPER):
    """Return a copy of config with the given numeric fields clamped."""
    bounded = {}
    for key in fields:
        if key in config:
            bounded[key] = clamp(float(config[key]), lower, upper)
    return merge_dicts(config, bounded)


def scale_numeric(config, factor):
    """Multiply every plain numeric value in config by factor."""
    scaled = {}
    for key, value in config.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            continue
        scaled[key] = value * factor
    return merge_dicts(config, scaled)


def format_config(config):
    """Render a config as sorted 'key = value' lines, floats to 3 decimals."""
    lines = []
    for key in sorted(config):
        value = config[key]
        if isinstance(value, float):
            lines.append("{0} = {1:.3f}".format(key, value))
        else:
            lines.append("{0} = {1}".format(key, value))
    return "\n".join(lines)


def build_config(user_settings, environment=None):
    """Combine defaults, user settings and environment tweaks into one config."""
    merged = merge_all(DEFAULT_SETTINGS, user_settings, environment or {})
    return clamp_fields(merged, RATIO_FIELDS)


def main():
    print(merge_dicts({"a": 1, "b": 2}, {"b": 3, "c": 4}))
    print(merge_dicts({"x": 10}, {"y": 20}))

    user = {"learning_rate": .125, "epochs": 40}
    environment = {"optimizer": "adam", "grad_clip": .5}
    config = build_config(merge_dicts(user, {"dropout": 1.5}), environment)
    print(format_config(config))

    warmup = scale_numeric(config, .25)
    print(format_config(warmup))


if __name__ == "__main__":
    main()

