def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


DAYS_PER_YEAR = 365.25
DAYS_PER_MONTH = DAYS_PER_YEAR / 12.0
MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def days_in_month(year, month):
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def round_half_up(value, digits=0):
    factor = 10.0 ** digits
    scaled = value * factor
    if scaled < 0:
        return -int(-scaled + 0.5) / factor
    return int(scaled + 0.5) / factor


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3 or not all(part.isdigit() for part in parts):
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    year, month, day = (int(part) for part in parts)
    if not 1 <= month <= 12:
        raise ValueError('month out of range in %r' % date_str)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError('day out of range in %r' % date_str)
    return year, month, day


def to_ordinal(year, month, day):
    shifted_year = year - (1 if month <= 2 else 0)
    era = shifted_year // 400
    year_of_era = shifted_year - era * 400
    month_index = (month + 9) % 12
    day_of_year = (153 * month_index + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468


def days_between_dates(start_date_str, end_date_str):
    start = to_ordinal(*parse_date(start_date_str))
    end = to_ordinal(*parse_date(end_date_str))
    return end - start


def describe_span(days):
    magnitude = abs(days)
    direction = 'backwards' if days < 0 else 'forwards'
    weeks = round_half_up(magnitude / 7.0, 2)
    if weeks < 1.0:
        size = '%d day(s)' % magnitude
    elif magnitude < DAYS_PER_YEAR:
        months = round_half_up(magnitude / DAYS_PER_MONTH, 1)
        size = '%s week(s) / about %s month(s)' % (weeks, months)
    else:
        years = round_half_up(magnitude / DAYS_PER_YEAR, 2)
        size = 'about %s year(s)' % years
    if magnitude == 0:
        return 'the same day'
    return '%s, counted %s' % (size, direction)


def main():
    pairs = [
        ('2023-01-01', '2023-01-05'),
        ('2023-01-01', '2022-12-25'),
        ('2020-02-28', '2020-03-01'),
        ('2000-01-01', '2023-07-04'),
    ]
    for start_date_str, end_date_str in pairs:
        delta = days_between_dates(start_date_str, end_date_str)
        print('%s -> %s: %d days (%s)' % (start_date_str, end_date_str,
                                          delta, describe_span(delta)))
    total = sum(abs(days_between_dates(a, b)) for a, b in pairs)
    average = round_half_up(total / float(len(pairs)), 2)
    print('mean gap over %d pairs: %s days' % (len(pairs), average))


if __name__ == '__main__':
    main()

