import math


def normalize_rectangle(x1, y1, x2, y2):
    """Return the rectangle as (low_x, low_y, high_x, high_y)."""
    return min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    """True if (px, py) lies inside (or on the border of) the rectangle."""
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    return lx <= px <= hx and ly <= py <= hy


def rectangle_center(x1, y1, x2, y2):
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    cx = 0.5 * (lx + hx)
    cy = 0.5 * (ly + hy)
    return cx, cy


def rectangle_area(x1, y1, x2, y2):
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    return float((hx - lx) * (hy - ly))


def bounding_radius(x1, y1, x2, y2):
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    return 0.5 * math.hypot(hx - lx, hy - ly)


def relative_position(px, py, x1, y1, x2, y2):
    """Coordinates of the point expressed as fractions of width and height."""
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    width = hx - lx
    height = hy - ly
    u = 0.5 if width == 0 else (px - lx) / float(width)
    v = 0.5 if height == 0 else (py - ly) / float(height)
    return u, v


def edge_distance(px, py, x1, y1, x2, y2):
    """Signed distance to the border: positive inside, negative outside."""
    lx, ly, hx, hy = normalize_rectangle(x1, y1, x2, y2)
    if is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return float(min(px - lx, hx - px, py - ly, hy - py))
    dx = max(lx - px, 0.0, px - hx)
    dy = max(ly - py, 0.0, py - hy)
    return -math.hypot(dx, dy)


def classify_point(px, py, x1, y1, x2, y2):
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "outside"
    u, v = relative_position(px, py, x1, y1, x2, y2)
    du = abs(u - 0.5)
    dv = abs(v - 0.5)
    if max(du, dv) <= 0.25:
        return "central"
    if edge_distance(px, py, x1, y1, x2, y2) <= 0.75:
        return "border"
    return "interior"


def format_report(px, py, rect):
    inside = is_point_in_rectangle(px, py, *rect)
    u, v = relative_position(px, py, *rect)
    margin = edge_distance(px, py, *rect)
    return "({:2d},{:2d}) inside={!s:5} u={:.2f} v={:.2f} margin={:+.2f} {}".format(
        px, py, inside, u, v, margin, classify_point(px, py, *rect))


def main():
    rect = (0, 0, 5, 5)
    cx, cy = rectangle_center(*rect)
    print("rectangle {} area {:.1f}".format(rect, rectangle_area(*rect)))
    print("center ({:.1f}, {:.1f}) bounding radius {:.3f}".format(
        cx, cy, bounding_radius(*rect)))
    points = [(3, 3), (6, 2), (0, 0), (5, 5), (2, 4), (-1, -1)]
    for px, py in points:
        print(format_report(px, py, rect))
    hits = sum(1 for px, py in points if is_point_in_rectangle(px, py, *rect))
    print("{} of {} points inside ({:.1f}%)".format(
        hits, len(points), 100.0 * hits / len(points)))


if __name__ == "__main__":
    main()

