def get_item_quantity(inventory, item_name):
    """Return the quantity of item_name in inventory, or 0 if absent."""
    quantity = inventory.get(item_name, 0)
    return int(quantity)


def stock_ratio(inventory, item_name, target_level):
    """Fraction of the target stock level currently on hand (capped at 1.0)."""
    if target_level <= 0:
        return 1.
    ratio = get_item_quantity(inventory, item_name) / target_level
    return min(ratio, 1.)


def needs_restock(inventory, item_name, target_level, threshold=.5):
    """True when stock has dropped to or below the given fraction of target."""
    return stock_ratio(inventory, item_name, target_level) <= threshold


def restock_amount(inventory, item_name, target_level, overshoot=.25):
    """Units to order so the shelf ends slightly above the target level."""
    missing = target_level - get_item_quantity(inventory, item_name)
    if missing <= 0:
        return 0
    return int(round(missing * (1. + overshoot)))


def inventory_value(inventory, prices):
    """Total retail value of everything on hand."""
    total = 0.
    for name in inventory:
        total += get_item_quantity(inventory, name) * prices.get(name, 0.)
    return total


def clearance_price(prices, item_name, discount=.75):
    """Price after applying a clearance discount, rounded to cents."""
    base = prices.get(item_name, 0.)
    return round(base * (1. - discount), 2)


def format_line(inventory, prices, item_name, target_level):
    quantity = get_item_quantity(inventory, item_name)
    percent = stock_ratio(inventory, item_name, target_level) * 100.
    line = "{:<10} {:>4} units  {:>6.1f}% of target".format(
        item_name, quantity, percent
    )
    if needs_restock(inventory, item_name, target_level):
        order = restock_amount(inventory, item_name, target_level)
        line += "  -> order {} (clearance {:.2f})".format(
            order, clearance_price(prices, item_name)
        )
    return line


def build_report(inventory, prices, targets):
    lines = [format_line(inventory, prices, name, targets[name])
             for name in sorted(targets)]
    lines.append("total value: {:.2f}".format(inventory_value(inventory, prices)))
