import sys

DEFAULT_DATA = """product,units,price
apple,120,0.75
banana,18000,0.25
orange,340,1.50
kiwi,,2.25
mango,9,14.00
"""


def parse_csv_line(csv_line):
    """Split one line of simple CSV (no quoting) into a list of strings."""
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a str")
    line = csv_line.rstrip("\r\n")
    if line == "":
        return []
    return line.split(",")


def to_number(field):
    try:
        return float(field.strip())
    except ValueError:
        return None


def numeric_ratio(fields):
    if not fields:
        return 0.0
    hits = sum(1 for f in fields if to_number(f) is not None)
    return hits / len(fields)


def percentile(sorted_values, fraction):
    position = fraction * (len(sorted_values) - 1)
    low = int(position)
    high = min(low + 1, len(sorted_values) - 1)
    weight = position - low
    return sorted_values[low] * (1.0 - weight) + sorted_values[high] * weight


def format_value(value):
    if abs(value) >= 1000.0:
        return "%.2fk" % (value / 1000.0)
    return "%.2f" % value


def transpose(rows):
    width = max((len(r) for r in rows), default=0)
    return [[row[i] if i < len(row) else "" for row in rows] for i in range(width)]


def describe_column(name, fields):
    if numeric_ratio(fields) < 0.5:
        distinct = len({f.strip() for f in fields if f.strip()})
        return "%-8s text    n=%d distinct=%d" % (name, len(fields), distinct)
    values = sorted(v for v in (to_number(f) for f in fields) if v is not None)
    mean = sum(values) / len(values)
    median = percentile(values, 0.5)
    q1 = percentile(values, 0.25)
    q3 = percentile(values, 0.75)
    spread = q3 - q1
    lower = q1 - 1.5 * spread
    upper = q3 + 1.5 * spread
    outliers = sum(1 for v in values if v < lower or v > upper)
    return "%-8s number  n=%d mean=%s median=%s iqr=%s outliers=%d" % (
        name, len(values), format_value(mean), format_value(median),
        format_value(spread), outliers)


def describe_table(text):
    rows = [parse_csv_line(line) for line in text.splitlines()]
    rows = [r for r in rows if r]
    if not rows:
        return []
    header, body = rows[0], rows[1:]
    if numeric_ratio(header) >= 0.5:
        header = ["col%d" % (i + 1) for i in range(len(header))]
        body = rows
    columns = transpose(body)
    names = header + ["col%d" % (i + 1) for i in range(len(header), len(columns))]
    return [describe_column(names[i], columns[i]) for i in range(len(columns))]


def main():
    text = sys.stdin.read() if not sys.stdin.isatty() else ""
    if not text.strip():
        text = DEFAULT_DATA
    for line in describe_table(text):
        print(line)


if __name__ == "__main__":
    main()

