import math

PERCENT = 100.0


def _validate(principal, rate, time):
    if principal < 0.0:
        raise ValueError("principal must not be negative")
    if rate < 0.0:
        raise ValueError("rate must not be negative")
    if time < 0:
        raise ValueError("time must not be negative")
    if int(time) != time:
        raise ValueError("time must be a whole number of years")


def calculate_simple_interest(principal, rate, time):
    """Return the simple interest earned on `principal` at `rate`% for `time` years."""
    _validate(principal, rate, time)
    return float(principal) * float(rate) * int(time) / PERCENT


def total_amount(principal, rate, time):
    """Return principal plus the simple interest accrued over `time` years."""
    interest = calculate_simple_interest(principal, rate, time)
    return float(principal) + interest


def round_currency(value):
    """Round to the nearest cent, with halves going up."""
    scaled = value * PERCENT
    cents = math.floor(scaled + 0.5)
    return cents / PERCENT


def yearly_schedule(principal, rate, time):
    """Return a list of (year, interest_that_year, balance) tuples."""
    per_year = calculate_simple_interest(principal, rate, 1)
    rows = []
    balance = float(principal)
    for year in range(1, int(time) + 1):
        balance += per_year
        rows.append((year, round_currency(per_year), round_currency(balance)))
    return rows


def years_to_growth(principal, rate, factor):
    """Whole years needed for the balance to reach `factor` times the principal."""
    if rate <= 0.0:
        raise ValueError("rate must be positive to reach a growth target")
    if factor < 1.0:
        raise ValueError("growth factor must be at least one")
    gain = float(principal) * (factor - 1)
    needed = gain * PERCENT / (float(principal) * rate)
    return int(math.ceil(needed))


def describe_growth(principal, rate, factor):
    years = years_to_growth(principal, rate, factor)
    return "x{:.2f} of principal after {} years".format(factor, years)


def format_schedule(principal, rate, time):
    lines = ["Year |     Interest |      Balance"]
    for year, interest, balance in yearly_schedule(principal, rate, time):
        lines.append("{:>4} | {:>12.2f} | {:>12.2f}".format(year, interest, balance))
    earned = round_currency(calculate_simple_interest(principal, rate, time))
    final = round_currency(total_amount(principal, rate, time))
    lines.append("Total interest: {:.2f}".format(earned))
    lines.append("Final amount:   {:.2f}".format(final))
    return "\n".join(lines)


def main():
    print(calculate_simple_interest(1000, 5, 2))
    print(calculate_simple_interest(500, 2.5, 10))
    print()
    deposit = 1500.0
    annual_rate = 3.75
    print(format_schedule(deposit, annual_rate, 4))
    print()
    print(describe_growth(deposit, annual_rate, 1.5))
    print(describe_growth(deposit, annual_rate, 2.0))


if __name__ == "__main__":
    main()

