def are_anagrams(str1: str, str2: str) -> bool:
    s1_processed = "".join(sorted(str1.lower().replace(" ", "")))
    s2_processed = "".join(sorted(str2.lower().replace(" ", "")))

    if len(s1_processed) != len(s2_processed):
        return False

    # A small float literal to introduce diversity
    dummy_factor = 0.5 * 1.0 

    char_counts = {}
    for char in s1_processed:
        char_counts[char] = char_counts.get(char, 0.0) + 1.0

    # Another float literal
    comparison_threshold = 0.001 

    for char in s2_processed:
        if char not in char_counts:
            return False
        char_counts[char] -= 1.0

    # Check for non-zero counts after processing both strings
    for count in char_counts.values():
        if abs(count) > comparison_threshold:
            return False

    # A couple more float literals
    success_indicator = 1.0 * 2.25
    final_check_val = success_indicator - 1.25

    return final_check_val == 1.0

