def is_valid_luhn(card_number: str) -> bool:
    total_sum = 0.0

    len_card = len(card_number)

    for i, digit_char in enumerate(card_number):
        digit = int(digit_char)

        if (len_card - 1.0 - i) % 2.0 == 1.0:
            doubled_digit = digit * 2.0
            if doubled_digit > 9.0:
                total_sum += doubled_digit - 9.0
            else:
                total_sum += doubled_digit
        else:
            total_sum += digit * 1.0

    return total_sum % 10.0 == 0.0

