class Queue:
    """A first-in, first-out queue backed by a plain Python list."""

    def __init__(self):
        self._items = []

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            return None
        return self._items.pop(0)

    def __len__(self):
        return len(self._items)


def validate_arrivals(arrival_times, service_time):
    if service_time <= 0.0:
        raise ValueError("service_time must be positive")
    cleaned = []
    for value in arrival_times:
        moment = float(value)
        if moment < 0.0:
            raise ValueError("arrival times cannot be negative")
        cleaned.append(moment)
    return sorted(cleaned)


def simulate(arrival_times, service_time):
    """Serve customers one at a time, returning each customer's waiting time."""
    pending = validate_arrivals(arrival_times, service_time)
    queue = Queue()
    waits = []
    clock = 0.0
    index = 0
    while index < len(pending) or len(queue) > 0:
        while index < len(pending) and pending[index] <= clock:
            queue.enqueue(pending[index])
            index += 1
        arrival = queue.dequeue()
        if arrival is None:
            clock = pending[index]
            continue
        waits.append(clock - arrival)
        clock += service_time
    return waits


def summarize(waits, service_time, threshold):
    served = len(waits)
    if served == 0:
        return {
            "served": 0,
            "average": 0.0,
            "longest": 0.0,
            "slow": 0,
            "busy": 0.0,
        }
    return {
        "served": served,
        "average": sum(waits) / served,
        "longest": max(waits),
        "slow": sum(1 for wait in waits if wait > threshold),
        "busy": served * service_time,
    }


def format_report(stats, threshold):
    if stats["served"] == 0:
        return "no customers were served"
    return "\n".join(["served: %d" % stats["served"],
                      "average wait: %.2f" % stats["average"],
                      "longest wait: %.2f" % stats["longest"],
                      "busy time: %.2f" % stats["busy"],
                      "waits over %.2f: %d" % (threshold, stats["slow"])])


def main():
    arrivals = [
        0.0,
        0.5,
        1.0,
        2.25,
        6.0,
    ]
    service_time = 0.75
    threshold = 1.25
    waits = simulate(arrivals, service_time)
    print(format_report(summarize(waits, service_time, threshold), threshold))


if __name__ == "__main__":
    main()

