import math


def fibonacci_sequence(n):
    if not isinstance(n, int):
        raise TypeError("n must be an int")
    seq = []
    a, b = 0, 1
    while a < n:
        seq.append(a)
        a, b = b, a + b
    return seq


def golden_ratio():
    root_five = 5 ** 0.5
    return (1 + root_five) / 2.0


def consecutive_ratios(seq):
    ratios = []
    for prev, curr in zip(seq, seq[1:]):
        if prev == 0:
            continue
        ratios.append(curr / prev)
    return ratios


def mean(values):
    if not values:
        return 0.0
    return math.fsum(values) / len(values)


def stddev(values):
    if len(values) < 2:
        return 0.0
    center = mean(values)
    variance = math.fsum((v - center) ** 2 for v in values) / (len(values) - 1)
    return variance ** 0.5


def percent_error(approx, exact):
    return abs(approx - exact) / exact * 100.0


def convergence_index(ratios, target, tolerance=0.75):
    for index, ratio in enumerate(ratios):
        if percent_error(ratio, target) < tolerance:
            return index
    return -1


def even_fraction(seq):
    if not seq:
        return 0.0
    evens = sum(1 for value in seq if value % 2 == 0)
    return evens / len(seq)


def expected_length(n, phi):
    if n <= 1:
        return 1.0
    root_five = 5 ** 0.5
    return math.log(n * root_five) / math.log(phi)


def format_ratio_row(index, ratio, target):
    error = percent_error(ratio, target)
    return f"  ratio[{index:>2}] = {ratio:9.6f}   error = {error:7.4f}%"


def report(n):
    phi = golden_ratio()
    seq = fibonacci_sequence(n)
    ratios = consecutive_ratios(seq)
    print(f"limit {n}: {seq}")
    print(f"  terms: {len(seq)}  (estimated {expected_length(n, phi):.2f})")
    print(f"  even terms: {even_fraction(seq) * 100.0:.1f}%")
    start = max(len(ratios) - 3, 0)
    for index, ratio in enumerate(ratios[start:], start=start):
        print(format_ratio_row(index, ratio, phi))
    if ratios:
        print(f"  mean ratio {mean(ratios):.6f} +/- {stddev(ratios):.6f}")
    hit = convergence_index(ratios, phi)
    if hit >= 0:
        print(f"  within 0.75% of phi from ratio[{hit}] onward")
    else:
        print("  never settles within 0.75% of phi")


def main():
    for limit in (1, 10, 1000, 1000000):
        report(limit)
    print(f"phi = {golden_ratio():.10f}")


if __name__ == "__main__":
    main()

