def tokenize(text):
    """Split text on spaces and drop surrounding punctuation from each chunk."""
    words = []
    for chunk in text.split():
        cleaned = chunk.strip(PUNCTUATION)
        if cleaned:
            words.append(cleaned)
    return words


def count_words(text):
    """Return the number of words in text, ignoring punctuation."""
    return len(tokenize(text))


def average_word_length(words):
    """Mean number of characters per word, 0.0 for an empty word list."""
    if not words:
        return 0.0
    total = sum(len(word) for word in words)
    return total / len(words)


def long_word_ratio(words, factor=1.25):
    """Fraction of words longer than factor times the average word length."""
    if not words:
        return 0.0
    cutoff = average_word_length(words) * factor
    long_words = sum(1 for word in words if len(word) > cutoff)
    return long_words / len(words)


def punctuation_density(text):
    """Fraction of characters in text that are punctuation marks."""
    if not text:
        return 0.0
    marks = sum(1 for char in text if char in PUNCTUATION)
    return marks / len(text)


