def is_palindromic_number(number):
    """Return True when the decimal digits of ``number`` read the same both ways."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    digits = str(abs(number))
    return digits == digits[::-1]


def next_palindromic_number(number):
    """Smallest palindromic number strictly greater than ``number``."""
    candidate = number + 1
    while not is_palindromic_number(candidate):
        candidate += 1
    return candidate


def palindromes_in_range(start, end):
    """All palindromic numbers in the inclusive range ``start``..``end``."""
    if start > end:
        raise ValueError("start must not exceed end")
    return [n for n in range(start, end + 1) if is_palindromic_number(n)]


def density_percent(start, end):
    """Percentage of the integers in the inclusive range that are palindromic."""
    span = end - start + 1
    return 100.0 * len(palindromes_in_range(start, end)) / span


def midpoint(start, end):
    """Centre of the inclusive range, as a float."""
    return (start + end) * 0.5


def estimated_density_percent(digit_count):
    """Rough theoretical density of palindromes among ``digit_count``-digit numbers."""
    if digit_count < 1:
        raise ValueError("digit_count must be positive")
    free_digits = digit_count * 0.5
    fraction = 10.0 ** -free_digits
    return 100 * fraction


def classify_density(percent):
    """Label a palindrome density so reports stay readable."""
    if percent >= 1.0:
        return "dense"
    if percent >= 0.5:
        return "moderate"
    return "sparse"


def balance_skew(start, end):
    """Where the palindromes sit inside the range: -1 means left edge, +1 right edge."""
    found = palindromes_in_range(start, end)
    if not found:
        return 0.0
    average = sum(found) / len(found)
    half_span = (end - start) * 0.5
    return (average - midpoint(start, end)) / half_span


def range_report(start, end):
    """Human-readable summary of the palindromes inside an inclusive range."""
    found = palindromes_in_range(start, end)
    percent = density_percent(start, end)
    estimate = estimated_density_percent(len(str(end)))
    lines = [
        "range {}..{}: {} palindromes".format(start, end, len(found)),
        "  density {:.3f}% ({}), estimate {:.3f}%".format(
            percent, classify_density(percent), estimate),
        "  skew {:+.3f}, first {}, last {}".format(
            balance_skew(start, end), found[0] if found else "-",
            found[-1] if found else "-"),
    ]
    return "\n".join(lines)


def main():
    for probe in (121, 123, -22, 0, 1221):
        print("{:>6} -> {}".format(probe, is_palindromic_number(probe)))
    print("next after 123:", next_palindromic_number(123))
    print("next after 1221:", next_palindromic_number(1221))
    for start, end in ((1, 100), (100, 999), (1000, 9999)):
        print(range_report(start, end))


if __name__ == "__main__":
    main()

