LOW_CUT = 1.0 / 3
HIGH_CUT = 2.0 / 3
CENTRE_TOLERANCE = 0.25


def triangular_sum(n):
    """Sum of 1..n, computed with the closed-form formula."""
    return n * (n + 1) * 0.5


def validate_sequence(numbers):
    """Check that `numbers` is a list of n-1 distinct ints from 1 to n."""
    if not isinstance(numbers, list) or not numbers:
        raise ValueError("numbers must be a non-empty list")
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("all entries must be plain integers")
    n = len(numbers) + 1
    if len(set(numbers)) != len(numbers):
        raise ValueError("entries must be distinct")
    if min(numbers) < 1 or max(numbers) > n:
        raise ValueError("entries must lie between 1 and %d" % n)
    return n


def find_missing_number(numbers):
    """Return the single value of 1..n absent from `numbers`."""
    n = validate_sequence(numbers)
    return int(triangular_sum(n) - sum(numbers))


def describe(numbers, missing):
    """Collect a few statistics about where the gap sits in the range."""
    n = len(numbers) + 1
    midpoint = (1 + n) * 0.5
    position = (missing - 1) / (n - 1)
    centre_gap = abs(position - 0.5)
    return {
        "n": n,
        "missing": missing,
        "midpoint": midpoint,
        "position": position,
        "mean": sum(numbers) / len(numbers),
        "offset": missing - midpoint,
        "near_centre": centre_gap < CENTRE_TOLERANCE,
    }


def classify(position):
    """Name the third of the range the missing number falls into."""
    if position < LOW_CUT:
        return "low"
    if position > HIGH_CUT:
        return "high"
    return "middle"


def format_report(stats):
    percent = stats["position"] * 100.0
    lines = [
        "range 1..%d, missing %d" % (stats["n"], stats["missing"]),
        "  midpoint of range  : %.2f" % stats["midpoint"],
        "  offset from centre : %+.2f" % stats["offset"],
        "  mean of the given  : %.3f" % stats["mean"],
        "  position in range  : %.1f%% (%s)" % (percent, classify(stats["position"])),
    ]
    if stats["near_centre"]:
        lines.append("  the gap sits near the centre")
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 4, 5],
        [1, 3],
        [5, 3, 1, 2, 6, 7, 8, 9, 10, 11],
    ]
    for numbers in samples:
        missing = find_missing_number(numbers)
        print("find_missing_number(%r) -> %d" % (numbers, missing))
        print(format_report(describe(numbers, missing)))
        print()


if __name__ == "__main__":
    main()

