MIN_HEIGHT_M = 0.5
MAX_HEIGHT_M = 2.5
MIN_WEIGHT_KG = 1.0

UNDERWEIGHT_LIMIT = 18.5
NORMAL_LIMIT = 25.0
OVERWEIGHT_LIMIT = 30.0


def validate_measurements(weight_kg, height_m):
    """Reject values that cannot describe a living person."""
    if weight_kg < MIN_WEIGHT_KG:
        raise ValueError("weight must be at least %.1f kg" % MIN_WEIGHT_KG)
    if not MIN_HEIGHT_M <= height_m <= MAX_HEIGHT_M:
        raise ValueError("height must be between %.1f m and %.1f m"
                         % (MIN_HEIGHT_M, MAX_HEIGHT_M))


def calculate_bmi(weight_kg, height_m):
    """Return the BMI for the given weight (kg) and height (m), 2 decimals."""
    validate_measurements(float(weight_kg), float(height_m))
    bmi = float(weight_kg) / (float(height_m) * float(height_m))
    return round(bmi, 2)


def classify_bmi(bmi):
    """Map a BMI value onto the standard WHO categories."""
    if bmi < UNDERWEIGHT_LIMIT:
        return "underweight"
    if bmi < NORMAL_LIMIT:
        return "normal weight"
    if bmi < OVERWEIGHT_LIMIT:
        return "overweight"
    return "obese"


def healthy_weight_range(height_m):
    """Return the weight interval (kg) matching a normal BMI at this height."""
    validate_measurements(MIN_WEIGHT_KG, float(height_m))
    area = float(height_m) * float(height_m)
    low = round(UNDERWEIGHT_LIMIT * area, 1)
    high = round(NORMAL_LIMIT * area, 1)
    return low, high


def weight_to_target(weight_kg, height_m, target_bmi=22.0):
    """Kilograms to gain (negative) or lose (positive) to reach target_bmi."""
    area = float(height_m) * float(height_m)
    return round(float(weight_kg) - target_bmi * area, 1)


def describe(weight_kg, height_m):
    """Build a one-line human readable summary of a measurement."""
    bmi = calculate_bmi(weight_kg, height_m)
    low, high = healthy_weight_range(height_m)
    delta = weight_to_target(weight_kg, height_m)
    advice = "at a healthy weight"
    if delta > 0.75:
        advice = "could lose %.1f kg" % delta
    elif delta < -0.75:
        advice = "could gain %.1f kg" % (-delta)
    return "%.1f kg at %.2f m -> BMI %.2f (%s); healthy range %.1f-%.1f kg; %s" % (
        float(weight_kg), float(height_m), bmi, classify_bmi(bmi), low, high, advice)


def main():
    people = [
        (70, 1.75),
        (90, 1.8),
        (52, 1.68),
        (120, 1.72),
    ]
    for weight_kg, height_m in people:
        print(describe(weight_kg, height_m))
    average = sum(calculate_bmi(w, h) for w, h in people) / len(people)
    print("group average BMI: %.2f (%s)" % (average, classify_bmi(average)))


if __name__ == "__main__":
    main()

