    return low, high


def weight_to_target(weight_kg, height_m, target_bmi=22.):
    """Kilograms to gain (negative) or lose (positive) to reach target_bmi."""
    area = float(height_m) * float(height_m)
    return round(float(weight_kg) - target_bmi * area, 1)


def describe(weight_kg, height_m):
    """Build a one-line human readable summary of a measurement."""
    bmi = calculate_bmi(weight_kg, height_m)
    low, high = healthy_weight_range(height_m)
    delta = weight_to_target(weight_kg, height_m)
    advice = "at a healthy weight"
    if delta > .75:
        advice = "could lose %.1f kg" % delta
    elif delta < -.75:
        advice = "could gain %.1f kg" % (-delta)
    return "%.1f kg at %.2f m -> BMI %.2f (%s); healthy range %.1f-%.1f kg; %s" % (
        float(weight_kg), float(height_m), bmi, classify_bmi(bmi), low, high, advice)


def main():
    people = [
        (70, 1.75),
        (90, 1.8),
        (52, 1.68),
        (120, 1.72),
    ]
    for weight_kg, height_m in people:
        print(describe(weight_kg, height_m))
    average = sum(calculate_bmi(w, h) for w, h in people) / len(people)
    print("group average BMI: %.2f (%s)" % (average, classify_bmi(average)))


if __name__ == "__main__":
