import re
from collections import Counter

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+")


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return EMAIL_RE.findall(text)


def confidence(email):
    """Heuristic plausibility score in the range 0..1 for a single address."""
    local, domain = email.split("@", 1)
    labels = domain.split(".")
    tld = labels[-1]
    score = 1.0
    if len(tld) < 3:
        score *= 0.75
    if not tld.isalpha():
        score *= 0.5
    if len(local) < 3:
        score *= 0.75
    if local.startswith(".") or local.endswith("."):
        score *= 0.5
    if any(ch.isdigit() for ch in labels[0]):
        score *= 0.75
    return score


def likely_emails(emails, threshold=0.5):
    """Keep only the addresses whose heuristic score reaches the threshold."""
    return [e for e in emails if confidence(e) >= threshold]


def average_local_length(emails):
    """Mean length of the part before the @ sign."""
    if not emails:
        return 0.0
    return sum(len(e.split("@", 1)[0]) for e in emails) / len(emails)


def domain_distribution(emails):
    """Map each domain to the percentage of addresses that use it."""
    counts = Counter(e.split("@", 1)[1].lower() for e in emails)
    total = len(emails)
    return {domain: 100.0 * n / total for domain, n in counts.items()}


def format_report(text):
    """Build a human readable summary of the addresses contained in text."""
    emails = extract_emails(text)
    if not emails:
        return "no email addresses found"
    lines = ["found %d address(es)" % len(emails)]
    for email in emails:
        score = confidence(email)
        mark = "clean" if score >= 1.0 else "suspect"
        lines.append("  %-28s %.2f  %s" % (email, score, mark))
    lines.append("mean local part length: %.2f" % average_local_length(emails))
    for domain, share in sorted(domain_distribution(emails).items()):
        lines.append("  %-20s %5.1f%%" % (domain, share))
    kept = likely_emails(emails, 0.75)
    lines.append("above threshold: %d" % len(kept))
    return "\n".join(lines)


def main():
    samples = [
        "Contact us at info@example.com or support@test.org.",
        "No emails here.",
        "Billing: a@b.c, sales99@shop.example.com and admin@shop.example.com",
    ]
    for sample in samples:
        print(sample)
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

