import math


def validate_inputs(principal, rate, compounding_frequency, time_years):
    """Reject inputs that make the compound interest formula meaningless."""
    if principal < 0.0:
        raise ValueError("principal must not be negative")
    if rate < -1.0:
        raise ValueError("a rate below -100% would wipe out more than the balance")
    if compounding_frequency < 1:
        raise ValueError("compounding_frequency must be at least 1")
    if time_years < 0:
        raise ValueError("time_years must not be negative")


def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    """Return the total amount after compounding (principal plus interest)."""
    validate_inputs(principal, rate, compounding_frequency, time_years)
    periodic_rate = 1.0 + rate / compounding_frequency
    periods = compounding_frequency * time_years
    return principal * periodic_rate ** periods


def interest_earned(principal, rate, compounding_frequency, time_years):
    """Return only the interest portion of the final balance."""
    total = calculate_compound_interest(principal, rate, compounding_frequency, time_years)
    return total - principal


def effective_annual_rate(rate, compounding_frequency):
    """Annual rate that a single yearly compounding would need to match."""
    validate_inputs(0.0, rate, compounding_frequency, 0)
    periodic_rate = 1.0 + rate / compounding_frequency
    return periodic_rate ** compounding_frequency - 1


def doubling_time(rate, compounding_frequency):
    """Years needed for the balance to reach 2.0 times the principal."""
    growth = 1.0 + rate / compounding_frequency
    if growth <= 1:
        return float("inf")
    return math.log(2.0) / (compounding_frequency * math.log(growth))


def rate_from_basis_points(basis_points):
    """Convert a quoted rate in basis points into a decimal rate."""
    return basis_points / 10000.0


def growth_schedule(principal, rate, compounding_frequency, years):
    """Year-by-year balances, rounded to the nearest cent."""
    schedule = []
    for year in range(1, years + 1):
        balance = calculate_compound_interest(principal, rate, compounding_frequency, year)
        schedule.append((year, round(balance, 2)))
    return schedule


def format_currency(amount):
    sign = "-" if amount < 0.0 else ""
    return "{0}${1:,.2f}".format(sign, abs(amount))


def format_percent(rate):
    return "{0:.3f}%".format(rate * 100.0)


def main():
    scenarios = [
        ("Savings account", 1000.0, 500, 1, 1),
        ("Quarterly CD", 1000.0, 500, 4, 1),
        ("Monthly bond fund", 2500.0, 725, 12, 5),
        ("Daily money market", 7500.0, 225, 365, 3),
    ]
    for name, principal, basis_points, frequency, years in scenarios:
        rate = rate_from_basis_points(basis_points)
        total = calculate_compound_interest(principal, rate, frequency, years)
        earned = interest_earned(principal, rate, frequency, years)
        eff = effective_annual_rate(rate, frequency)
        print("{0}: {1} -> {2}".format(name, format_currency(principal), format_currency(total)))
        print("  interest {0}, effective rate {1}".format(format_currency(earned), format_percent(eff)))
        print("  doubles in {0:.2f} years".format(doubling_time(rate, frequency)))
        for year, balance in growth_schedule(principal, rate, frequency, years):
            share = balance / total
            print("    year {0}: {1} ({2:.1%} of final)".format(year, format_currency(balance), share))


if __name__ == "__main__":
    main()

