def parse_octet(text):
    """Return the integer value of a textual octet, or None if it is not one."""
    if not text or len(text) > 3:
        return None
    if not text.isdigit():
        return None
    if len(text) > 1 and text.startswith('0'):
        return None
    value = int(text)
    if value > 255:
        return None
    return value


def percentage(part, whole):
    """Express part of whole as a percentage, tolerating an empty whole."""
    if whole <= 0:
        return 0.0
    return (part / whole) * 100.0


def is_valid_ipv4(ip_address):
    """True when ip_address is four dot-separated octets in the range 0-255."""
    if not isinstance(ip_address, str):
        return False
    parts = ip_address.strip().split('.')
    if len(parts) != 4:
        return False
    return all(parse_octet(part) is not None for part in parts)


def octets(ip_address):
    """The four octet values of a valid address."""
    return [parse_octet(part) for part in ip_address.strip().split('.')]


def classify(ip_address):
    """Name the address range an IPv4 string belongs to."""
    if not is_valid_ipv4(ip_address):
        return 'invalid'
    first, second = octets(ip_address)[:2]
    if first == 127:
        return 'loopback'
    if first == 10 or (first == 172 and 16 <= second <= 31):
        return 'private'
    if first == 192 and second == 168:
        return 'private'
    if 224 <= first <= 239:
        return 'multicast'
    return 'public'


def grade(rate):
    """Turn a share of valid addresses into a short verdict."""
    if rate >= 1.0:
        return 'all addresses valid'
    if rate >= 0.75:
        return 'mostly valid'
    if rate >= 0.5:
        return 'mixed quality'
    return 'largely invalid'


def summarize(addresses):
    """Collect validity counts, per-category tallies and a verdict."""
    categories = {}
    valid = 0
    for address in addresses:
        category = classify(address)
        categories[category] = categories.get(category, 0) + 1
        if category != 'invalid':
            valid += 1
    total = len(addresses)
    rate = valid / total if total else 0.0
    return {
        'total': total,
        'valid': valid,
        'rate': rate,
        'categories': categories,
        'verdict': grade(rate),
    }


def format_report(addresses):
    """Build a human readable report for a batch of addresses."""
    summary = summarize(addresses)
    lines = []
    for address in addresses:
        lines.append('{:<18} {}'.format(address, classify(address)))
    lines.append('{}/{} valid ({:.1f}%) - {}'.format(
        summary['valid'],
        summary['total'],
        percentage(summary['valid'], summary['total']),
        summary['verdict'],
    ))
    for category in sorted(summary['categories']):
        lines.append('  {}: {}'.format(category, summary['categories'][category]))
    return '\n'.join(lines)


def main():
    samples = [
        '192.168.1.1',
        '256.0.0.1',
        '127.0.0.1',
        '8.8.8.8',
        '10.0.0.7',
        '224.0.0.251',
        '1.2.3',
        '01.2.3.4',
    ]
    print(format_report(samples))


if __name__ == '__main__':
    main()

