from collections import Counter

MAJORITY_SHARE = 0.5
FLAT_SHARE = 0.25
BAR_WIDTH = 20


def validate_numbers(numbers):
    """Return the input as a list of numbers, raising on bad input."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    values = list(numbers)
    if not values:
        raise ValueError("numbers must not be empty")
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("all elements must be int or float")
    return values


def frequency_table(numbers):
    """Map each distinct value to how often it occurs."""
    return Counter(validate_numbers(numbers))


def find_mode(numbers):
    """Return a most frequent element of numbers."""
    counts = frequency_table(numbers)
    best_value, _ = max(counts.items(), key=lambda item: item[1])
    return best_value


def mode_share(numbers):
    """Fraction of the sample taken up by the mode."""
    values = validate_numbers(numbers)
    counts = frequency_table(values)
    return counts[find_mode(values)] / len(values)


def median(numbers):
    """Middle value of the sample, averaging the two centre values if even."""
    values = sorted(validate_numbers(numbers))
    middle = len(values) // 2
    if len(values) % 2 == 1:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2.0


def all_modes(numbers):
    """Every value tied for the highest frequency, in sorted order."""
    counts = frequency_table(numbers)
    top = max(counts.values())
    return sorted(value for value, count in counts.items() if count == top)


