def validate_series(data):
    """Convert an input sequence into a list of floats, rejecting bad values."""
    if not isinstance(data, (list, tuple)):
        raise TypeError("data must be a list or tuple of numbers")
    series = []
    for value in data:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("unsupported data point: %r" % (value,))
        series.append(float(value))
    return series


def calculate_sma(data, window_size):
    """Simple moving average of `data` over a sliding window of `window_size`."""
    series = validate_series(data)
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an int")
    if window_size <= 0:
        raise ValueError("window_size must be positive")
    if window_size > len(series):
        return []
    total = 0.0
    for value in series[:window_size]:
        total += value
    width = float(window_size)
    averages = [total / width]
    for index in range(window_size, len(series)):
        total += series[index] - series[index - window_size]
        averages.append(total / width)
    return averages


def sma_offset(window_size):
    """Index shift between a window's last point and its centre."""
    return (window_size - 1) / 2.0


def percent_deviation(value, average):
    """Relative gap between a raw point and its moving average, in percent."""
    if average == 0.0:
        return 0.0
    return 100.0 * (value - average) / average


def calculate_ema(data, window_size):
    """Exponential moving average, seeded with the first simple average."""
    series = validate_series(data)
    if window_size <= 0 or window_size > len(series):
        return []
    span = window_size + 1.0
    alpha = 2 / span
    current = sum(series[:window_size]) / float(window_size)
    averages = [current]
    for value in series[window_size:]:
        current = alpha * value + (1 - alpha) * current
        averages.append(current)
    return averages


def classify_trend(averages):
    """Label the overall direction of a moving-average curve."""
    if len(averages) < 2:
        return "flat"
    slope = (averages[-1] - averages[0]) / (len(averages) - 1)
    if slope > 0.25:
        return "rising"
    if slope < -0.25:
        return "falling"
    return "flat"


def blended_average(sma, ema):
    return [0.5 * (simple + exponential) for simple, exponential in zip(sma, ema)]


def format_report(data, window_size):
    sma = calculate_sma(data, window_size)
    if not sma:
        return "window_size %d exceeds the %d available points" % (window_size, len(data))
    blend = blended_average(sma, calculate_ema(data, window_size))
    offset = sma_offset(window_size)
    lines = ["window=%d points=%d trend=%s" % (window_size, len(data), classify_trend(sma))]
    for index, simple in enumerate(sma):
        last = index + window_size - 1
        point = float(data[last])
        lines.append("centre=%.1f sma=%.4f blend=%.4f dev=%+.2f%%"
                     % (last - offset, simple, blend[index], percent_deviation(point, simple)))
    return "\n".join(lines)


def main():
    prices = [3, 5, 4, 6, 8, 7, 9, 12, 11]
    print(format_report(prices, 3))
    print(format_report(prices, 4))
    print(format_report(prices, 20))


if __name__ == "__main__":
    main()

