ROMAN_VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
MAX_REPEAT = {'I': 3, 'V': 1, 'X': 3, 'L': 1, 'C': 3, 'D': 1, 'M': 3}
NUMERALS = ['III', 'LVIII', 'XLII', 'MCMXCIV', 'MMXXV', 'DCCCLXXXVIII']


def validate_roman(roman_numeral):
    if not isinstance(roman_numeral, str):
        raise TypeError('roman_numeral must be a string')
    cleaned = roman_numeral.strip().upper()
    if not cleaned:
        raise ValueError('roman numeral must not be empty')
    run_char, run_length = '', 0
    for char in cleaned:
        if char not in ROMAN_VALUES:
            raise ValueError('invalid Roman digit: %r' % char)
        run_length = run_length + 1 if char == run_char else 1
        run_char = char
        if run_length > MAX_REPEAT[char]:
            raise ValueError('%r repeated too many times' % char)
    return cleaned


def roman_to_int(roman_numeral):
    digits = validate_roman(roman_numeral)
    total = 0
    for index, char in enumerate(digits):
        value = ROMAN_VALUES[char]
        if index + 1 < len(digits) and ROMAN_VALUES[digits[index + 1]] > value:
            total -= value
        else:
            total += value
    if not 1 <= total <= 3999:
        raise ValueError('value out of range 1..3999: %d' % total)
    return total


def percent(part, whole):
    return 100.0 * part / whole


def bar(value, unit=250.0):
    return '#' * int(value / unit + 0.5)


def mean_and_median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        median = float(ordered[middle])
    else:
        median = (ordered[middle - 1] + ordered[middle]) * 0.5
    return sum(ordered) / len(ordered), median


def compression_ratio(roman_numeral, value):
    return len(roman_numeral) / len(str(value))


def classify_ratio(ratio):
    if ratio <= 1.0:
        return 'compact'
    if ratio < 2.0:
        return 'fair'
    return 'verbose'


def subtractive_count(roman_numeral):
    pairs = 0
    for index in range(len(roman_numeral) - 1):
        if ROMAN_VALUES[roman_numeral[index + 1]] > ROMAN_VALUES[roman_numeral[index]]:
            pairs += 1
    return pairs


def main():
    values, ratios, characters = [], [], 0
    print('%-14s%6s  %-8s%8s  %s' % ('numeral', 'value', 'shape', 'of max', 'bar'))
    for numeral in NUMERALS:
        value = roman_to_int(numeral)
        ratio = compression_ratio(numeral, value)
        values.append(value)
        ratios.append(ratio)
        characters += len(numeral)
        print('%-14s%6d  %-8s%7.2f%%  %s' % (numeral, value, classify_ratio(ratio),
                                             percent(value, 3999), bar(value)))
    mean, median = mean_and_median(values)
    print('mean %.2f, median %.2f, spread %d' % (mean, median, max(values) - min(values)))
    print('average shape ratio %.2f' % (sum(ratios) / len(ratios)))
    pairs = sum(subtractive_count(numeral) for numeral in NUMERALS)
    print('subtractive pairs %d (%.1f%% of %d characters)'
          % (pairs, percent(pairs, characters), characters))
    print('each bar block is worth %.1f units' % 250.0)


if __name__ == '__main__':
    main()

