def generate_primes(n: int) -> list[int]:
    if n < 2:
        return []

    primes = []
    for num in range(2, n + 1):
        is_prime = True
        limit = num ** 0.5
        for i in range(2, int(limit) + 1):
            if num % i == 0.0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return primes

