import math
import re

WORD_RE = re.compile(r"[A-Za-z0-9']+")


def read_words(filepath):
    """Return the list of words found in the file at *filepath*."""
    with open(filepath, encoding="utf-8") as handle:
        text = handle.read()
    return WORD_RE.findall(text)


def count_words_in_file(filepath):
    """Count the total number of words in a simple text file."""
    return len(read_words(filepath))


def count_sentences(text):
    """Count sentence-like chunks, never reporting fewer than one."""
    chunks = [chunk for chunk in re.split(r"[.!?]+", text) if chunk.strip()]
    return max(len(chunks), 1)


def average_word_length(words):
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def long_words(words, factor=1.5):
    """Words noticeably longer than the average word of the text."""
    threshold = factor * average_word_length(words)
    return [word for word in words if len(word) > threshold]


def lexical_density(words):
    """Fraction of distinct words, case-insensitively."""
    if not words:
        return 0.0
    distinct = {word.lower() for word in words}
    return len(distinct) / len(words)


def automated_readability_index(text, words):
    """ARI grade estimate for the text (0.0 when there is nothing to score)."""
    if not words:
        return 0.0
    characters = sum(len(word) for word in words)
    letters_term = 4.71 * (characters / len(words))
    length_term = 0.5 * (len(words) / count_sentences(text))
    return letters_term + length_term - 21.43


def rounded(value):
    return int(math.floor(value + 0.5))


def density_label(density):
    if density >= 0.75:
        return "varied vocabulary"
    if density >= 0.5:
        return "moderately repeated vocabulary"
    return "heavily repeated vocabulary"


def format_report(filepath):
    with open(filepath, encoding="utf-8") as handle:
        text = handle.read()
    words = WORD_RE.findall(text)
    density = lexical_density(words)
    grade = max(automated_readability_index(text, words), 1.0)
    lines = [
        "file: {0}".format(filepath),
        "words: {0}".format(len(words)),
        "sentences: {0}".format(count_sentences(text)),
        "average word length: {0:.2f}".format(average_word_length(words)),
        "distinct words: {0:.1f}% ({1})".format(100.0 * density, density_label(density)),
        "long words: {0}".format(", ".join(long_words(words)) or "none"),
        "estimated reading grade: {0}".format(rounded(grade)),
