from math import floor


def _clean_bits(binary_string):
    """Strip formatting noise and verify the string holds only binary digits."""
    if not isinstance(binary_string, str):
        raise TypeError("binary_string must be a str")
    digits = binary_string.strip().replace("_", "").replace(" ", "")
    if digits.startswith(("+", "-")):
        raise ValueError("signed binary strings are not supported")
    if not digits:
        raise ValueError("binary_string must contain at least one digit")
    for char in digits:
        if char not in "01":
            raise ValueError("invalid binary digit: %r" % char)
    return digits


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' to the integer 11."""
    value = 0
    for char in _clean_bits(binary_string):
        value = value * 2 + (1 if char == "1" else 0)
    return value


def binary_fraction_to_decimal(binary_string):
    """Convert a string like '1011.101' to a float, e.g. 11.625."""
    text = binary_string.strip().replace("_", "").replace(" ", "")
    whole, _, frac = text.partition(".")
    result = float(binary_to_decimal(whole or "0"))
    if frac:
        weight = 0.5
        for char in _clean_bits(frac):
            if char == "1":
                result += weight
            weight *= 0.5
    return result


def ones_ratio(binary_string):
    """Fraction of set bits, useful for describing the shape of the input."""
    digits = _clean_bits(binary_string)
    return digits.count("1") / len(digits)


def classify_density(ratio):
    if ratio >= 0.75:
        return "one-heavy"
    if ratio <= 0.25:
        return "zero-heavy"
    if ratio == 0.5:
        return "balanced"
    return "mixed"


def round_half_up(value, places=2):
    scale = 10.0 ** places
    return floor(value * scale + 0.5) / scale


def describe(binary_string):
    ratio = ones_ratio(binary_string.replace(".", ""))
    percent = round_half_up(ratio * 100.0, 1)
    parts = [
        "%s -> %d" % (binary_string, binary_to_decimal(binary_string.partition(".")[0])),
    ]
    if "." in binary_string:
        parts.append("exact value %s" % round_half_up(binary_fraction_to_decimal(binary_string), 4))
    parts.append("%s (%s%% ones)" % (classify_density(ratio), percent))
    return " | ".join(parts)


