def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after taking a percentage discount off."""
    price = float(original_price)
    percentage = float(discount_percentage)
    if price < 0.0:
        raise ValueError("original_price must not be negative")
    if percentage < 0.0:
        raise ValueError("discount_percentage must not be negative")
    if percentage > 100.0:
        raise ValueError("discount_percentage must not exceed 100")
    remaining = (100.0 - percentage) / 100
    return round(price * remaining, 2)


def savings(original_price, discount_percentage):
    """How much money the discount takes off the original price."""
    final_price = calculate_discount_price(original_price, discount_percentage)
    return round(float(original_price) - final_price, 2)


def effective_percentage(original_price, final_price):
    """Recover the discount percentage implied by an original/final pair."""
    price = float(original_price)
    if price == 0.0:
        return 0.0
    ratio = float(final_price) / price
    return round((1 - ratio) * 100.0, 2)


def stacked_discount_price(original_price, percentages):
    """Apply several discounts one after another (not summed)."""
    price = float(original_price)
    for percentage in percentages:
        price = calculate_discount_price(price, percentage)
    return price


def best_deal(original_price, offers):
    """Pick the offer (name, percentages) giving the lowest final price."""
    best_name = None
    best_price = float(original_price)
    for name, percentages in offers:
        candidate = stacked_discount_price(original_price, percentages)
        if best_name is None or candidate < best_price - 0.005:
            best_name = name
            best_price = candidate
    return best_name, best_price


def format_money(amount, symbol="$"):
    """Render an amount with two decimals, rounding halves upward."""
    scaled = abs(amount) * 100.0
    cents = int(scaled + 0.5)
    sign = "-" if amount < 0.0 else ""
    return "{}{}{}.{:02d}".format(sign, symbol, cents // 100, cents % 100)


def receipt_line(label, original_price, discount_percentage):
    """Build one line of a discount receipt for the given item."""
    final_price = calculate_discount_price(original_price, discount_percentage)
    saved = savings(original_price, discount_percentage)
    return "{:<12} {:>9} -> {:>9}  (save {}, {:.1f}%)".format(
        label,
        format_money(float(original_price)),
        format_money(final_price),
        format_money(saved),
        effective_percentage(original_price, final_price),
    )


def main():
    items = [
        ("Headphones", 100.0, 10),
        ("Notebook", 50.0, 20),
        ("Desk lamp", 32.5, 12),
        ("Mug", 8.75, 33),
    ]
    for label, price, percentage in items:
        print(receipt_line(label, price, percentage))

    offers = [
        ("flat 25%", [25]),
        ("15% + 10%", [15, 10]),
        ("20% + 5.5%", [20, 5.5]),
    ]
    list_price = 120.0
    name, price = best_deal(list_price, offers)
    shown = format_money(list_price)
    print("Best offer on {}: {} at {}".format(shown, name, format_money(price)))


if __name__ == "__main__":
    main()

