from collections import OrderedDict


def sort_dict_by_key(input_dict):
    """Return a new OrderedDict with the items of input_dict sorted by key."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    return OrderedDict((key, input_dict[key]) for key in sorted(input_dict))


def normalize_scores(raw_scores, maximum):
    """Turn raw point totals into fractions of the maximum possible score."""
    if maximum <= 0.0:
        raise ValueError("maximum must be positive")
    normalized = {}
    for name, points in raw_scores.items():
        fraction = float(points) / float(maximum)
        normalized[name] = min(fraction, 1.0)
    return sort_dict_by_key(normalized)


HOMEWORK_WEIGHT = 0.25
MISSING_FRACTION = 0.0


def weighted_final(homework_fraction, exam_fraction):
    """Combine homework and exam fractions using the course weighting."""
    exam_weight = 1.0 - HOMEWORK_WEIGHT
    return HOMEWORK_WEIGHT * homework_fraction + exam_weight * exam_fraction


def round_half_up(value, digits=0):
    """Round away from zero on ties, unlike Python's banker's rounding."""
    scale = 10.0 ** digits
    shifted = value * scale
    if shifted < 0.0:
        return -int(-shifted + 0.5) / scale
    return int(shifted + 0.5) / scale


def letter_grade(fraction):
    if fraction >= 0.9:
        return "A"
    if fraction >= 0.8:
        return "B"
    if fraction >= 0.7:
        return "C"
    if fraction >= 0.6:
        return "D"
    return "F"


def format_percent(fraction):
    return "{0:.1f}%".format(round_half_up(fraction * 100.0, 1))


def final_fractions(homework_raw, exam_raw, homework_max, exam_max):
    """Map every student that appears in either source to a final fraction."""
    homework = normalize_scores(homework_raw, homework_max)
    exam = normalize_scores(exam_raw, exam_max)
    finals = {}
    for name in set(homework) | set(exam):
        homework_part = homework.get(name, MISSING_FRACTION)
        exam_part = exam.get(name, MISSING_FRACTION)
        finals[name] = weighted_final(homework_part, exam_part)
    return sort_dict_by_key(finals)


def build_report(finals):
    """Produce a key-sorted report mapping each student to a summary line."""
    report = {}
    for name, final in finals.items():
        report[name] = "{0} ({1})".format(format_percent(final), letter_grade(final))
    return sort_dict_by_key(report)


def class_average(finals):
    if not finals:
        return MISSING_FRACTION
    return sum(finals.values()) / float(len(finals))


def main():
    print(sort_dict_by_key({'b': 2, 'a': 1, 'c': 3}))
    print(sort_dict_by_key({'z': 26, 'y': 25}))

    homework_raw = {'dana': 38, 'alice': 45, 'carl': 27, 'bob': 41}
    exam_raw = {'bob': 88, 'alice': 92, 'carl': 61, 'dana': 75}
    homework_max = 50.0
    exam_max = 100.0
    finals = final_fractions(homework_raw, exam_raw, homework_max, exam_max)
    for name, summary in build_report(finals).items():
        print("{0:<6} {1}".format(name, summary))
    print("class average: " + format_percent(class_average(finals)))


if __name__ == "__main__":
    main()

