    """Fraction of distinct characters, 1.0 for an all-unique string."""
    if not s:
        return 1.
    return len(set(s)) / len(s)


def duplicate_counts(s):
    """Map each repeated character to how many times it appears."""
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return {ch: n for ch, n in counts.items() if n > 1}


def average_repetition(s):
    """Mean number of occurrences among the repeated characters."""
    dups = duplicate_counts(s)
    if not dups:
        return .0
    return sum(dups.values()) / len(dups)


def classify(s):
    """Label a string by how close it is to being all-unique."""
    ratio = uniqueness_ratio(s)
    if ratio >= 1.:
        return "unique"
    if ratio >= .75:
        return "mostly unique"
    if ratio >= .5:
        return "half repeated"
    return "heavily repeated"


def describe(s):
    """Build a one-line human readable report for a single string."""
    parts = ["%-12r unique=%-5s ratio=%.2f" % (s, has_all_unique_chars(s),
                                               uniqueness_ratio(s))]
    parts.append("class=%s" % classify(s))
    repeats = average_repetition(s)
    if repeats > 2.25:
        parts.append("avg-repeat=%.2f (severe)" % repeats)
    elif repeats > .0:
        parts.append("avg-repeat=%.2f" % repeats)
    dups = duplicate_counts(s)
    if dups:
        listing = ", ".join("%s x%d" % (ch, n) for ch, n in sorted(dups.items()))
        parts.append("dups: " + listing)
    return " | ".join(parts)


def main():
    samples = ["abcde", "hello", "", "aabbcc", "unique", "mississippi",
               "Python 3.9", "aaaa"]
    for sample in samples:
        print(describe(sample))
    unique_count = sum(1 for s in samples if has_all_unique_chars(s))
    share = unique_count / len(samples)
    print("-" * 60)
    print("all-unique strings: %d of %d (%.0f%%)" % (unique_count,
                                                     len(samples),
                                                     share * 100.))
    if share < .5:
        print("most samples contain repeats")


if __name__ == "__main__":
    main()

