def reverse_string(input_string):
    """Return a new string with the characters of input_string in reverse order."""
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str")
    reversed_chars = []
    for index in range(len(input_string) - 1, -1, -1):
        reversed_chars.append(input_string[index])
    return "".join(reversed_chars)


def normalize(text):
    """Keep only alphanumeric characters, folded to lower case."""
    return "".join(char.lower() for char in text if char.isalnum())


def mirror_similarity(text):
    """Fraction of positions where text agrees with its own reversal."""
    if not text:
        return 1.0
    backwards = reverse_string(text)
    matches = sum(1 for left, right in zip(text, backwards) if left == right)
    return matches / len(text)


def is_palindrome(text):
    cleaned = normalize(text)
    return cleaned == reverse_string(cleaned)


def classify(score):
    if score >= 1.0:
        return "perfect mirror"
    if score >= 0.75:
        return "near mirror"
    if score >= 0.5:
        return "partial mirror"
    return "weak mirror"


def half_marker(text):
    """Index of the pivot used when folding the string onto itself."""
    return int(len(text) * 0.5)


def describe(text):
    cleaned = normalize(text)
    score = mirror_similarity(cleaned)
    return {
        "original": text,
        "reversed": reverse_string(text),
        "pivot": half_marker(cleaned),
        "score": score,
        "percent": round(score * 100.0, 2),
        "label": classify(score),
        "palindrome": is_palindrome(text),
    }


def format_report(entry):
    flag = "yes" if entry["palindrome"] else "no"
    return (
        "{original!r} -> {reversed!r} | pivot {pivot} | "
        "{percent:.2f}% ({label}) | palindrome: {flag}"
    ).format(flag=flag, **entry)


def average_score(entries):
    if not entries:
        return 0.0
    total = 0.0
    for entry in entries:
        total += entry["score"]
    return total / len(entries)


def main():
    samples = ["hello", "Python", "racecar", "A man, a plan, a canal: Panama", "abcba!", ""]
    entries = [describe(sample) for sample in samples]
    for entry in entries:
        print(format_report(entry))
    mean = average_score(entries)
    print("average mirror score: {:.4f} ({})".format(mean, classify(mean)))
    print("strong samples: {}".format(sum(1 for e in entries if e["score"] >= 0.5)))


if __name__ == "__main__":
