def is_even(number):
    """Return True if `number` is an even integer."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int")
    return number % 2 == 0


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of ints."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for token in tokens:
        numbers.append(int(token))
    return numbers


def even_ratio(numbers):
    """Fraction of the given numbers that are even (0.0 for an empty list)."""
    if not numbers:
        return 0.0
    evens = sum(1 for value in numbers if is_even(value))
    return evens / len(numbers)


def as_percentage(ratio):
    """Convert a 0..1 ratio into a percentage value."""
    return ratio * 100.0


def balance_label(ratio):
    """Describe how far the even/odd split is from a perfect half-half mix."""
    deviation = abs(ratio - 0.5)
    if deviation <= 0.05:
        return "balanced"
    if deviation <= 0.25:
        return "slightly skewed"
    return "strongly skewed"


def ratio_bar(ratio, width=20):
    """Render the ratio as a simple text bar of `width` cells."""
    filled = int(ratio * width + 0.5)
    return "[" + "#" * filled + "-" * (width - filled) + "]"


def mean(numbers):
    """Arithmetic mean of the numbers, 0.0 when there is nothing to average."""
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)


def summarize(numbers):
    """Build report lines about the parity of a batch of numbers."""
    lines = []
    for value in numbers:
        kind = "even" if is_even(value) else "odd"
        lines.append("{:>6} is {}".format(value, kind))
    ratio = even_ratio(numbers)
    lines.append("even share: {:.1f}% {}".format(as_percentage(ratio), ratio_bar(ratio)))
    lines.append("split is {}".format(balance_label(ratio)))
    lines.append("mean value: {:.2f}".format(mean(numbers)))
    midpoint = (max(numbers) + min(numbers)) / 2.0
    lines.append("range midpoint: {:.2f}".format(midpoint))
    return lines


def main():
    sample = "4, 7, 10, 11, 12, 15, 18, 21"
    numbers = parse_numbers(sample)
    for line in summarize(numbers):
        print(line)
    print("is_even(4) ->", is_even(4))
    print("is_even(7) ->", is_even(7))


if __name__ == "__main__":
    main()

