import math


def validate_numbers(numbers):
    """Reject inputs that are not lists of at least four positive integers."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list of int")
    if len(numbers) < 4:
        raise ValueError("at least four numbers are required")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("every element must be an int")
        if value <= 0:
            raise ValueError("every element must be positive")


def sum_two_smallest(numbers):
    """Return the sum of the two smallest positive numbers in the list."""
    validate_numbers(numbers)
    smallest = second = None
    for value in numbers:
        if smallest is None or value < smallest:
            smallest, second = value, smallest
        elif second is None or value < second:
            second = value
    return smallest + second


def mean(numbers):
    return sum(numbers) / len(numbers)


def median(numbers):
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def midrange(numbers):
    low = min(numbers)
    return low + (max(numbers) - low) * 0.5


def share_percent(part, whole):
    """Percentage of the total that `part` represents."""
    if whole <= 0:
        raise ValueError("whole must be positive")
    return part / whole * 100.0


def round_half_up(value):
    return int(math.floor(value + 0.5))


def format_percent(value):
    """Percentage with one decimal place, rounded away from zero at the half."""
    tenths = round_half_up(value * 10.0)
    return "{0:.1f}%".format(tenths / 10.0)


def format_report(numbers):
    pair_sum = sum_two_smallest(numbers)
    total = sum(numbers)
    lines = [
        "values      : {0}".format(numbers),
        "two smallest: {0}".format(pair_sum),
        "share       : {0}".format(format_percent(share_percent(pair_sum, total))),
        "mean        : {0:.3f}".format(mean(numbers)),
        "median      : {0:.3f}".format(median(numbers)),
        "midrange    : {0:.3f}".format(midrange(numbers)),
    ]
    return "\n".join(lines)


def main():
    samples = [
        [19, 5, 42, 2, 77],
        [10, 343445353, 3453445, 3453545353453],
        [4, 8, 15, 16, 23, 42],
    ]
    for sample in samples:
        print(format_report(sample))
        print("-" * 48)


if __name__ == "__main__":
    main()

