import math


def validate_radius(radius):
    """Coerce a radius to float and reject negative or non-numeric input."""
    try:
        r = float(radius)
    except (TypeError, ValueError):
        raise TypeError("radius must be a number, got {0!r}".format(radius))
    if math.isnan(r) or math.isinf(r):
        raise ValueError("radius must be finite, got {0!r}".format(radius))
    if r < 0.:
        raise ValueError("radius must be non-negative, got {0!r}".format(r))
    return r


def calculate_sphere_volume(radius):
    """Return the volume of a sphere with the given radius."""
    r = validate_radius(radius)
    third_of_cube = r ** 3 / 3.
    return 4. * math.pi * third_of_cube


def calculate_sphere_surface_area(radius):
    """Return the surface area of a sphere with the given radius."""
    r = validate_radius(radius)
    return 4. * math.pi * r ** 2


def radius_from_volume(volume):
    """Invert the volume formula: return the radius enclosing the given volume."""
    v = float(volume)
    if v < 0.:
        raise ValueError("volume must be non-negative, got {0!r}".format(v))
    cube = 3. * v / math.pi
    cube /= 4.
    return cube ** (1. / 3)


def spherical_cap_volume(radius, height):
    """Volume of a cap of the given height cut from a sphere of the given radius."""
    r = validate_radius(radius)
    h = float(height)
    diameter = 2. * r
    if not 0. <= h <= diameter:
        raise ValueError("cap height must lie between 0 and the diameter")
    return math.pi * h ** 2 * (r - h / 3.)


def hemisphere_volume(radius):
    """Volume of half a sphere, i.e. a cap whose height equals the radius."""
    return .5 * calculate_sphere_volume(radius)


def shell_volume(inner_radius, thickness):
    """Volume of material in a hollow sphere of the given wall thickness."""
    inner = validate_radius(inner_radius)
    t = float(thickness)
    if t <= 0.:
        raise ValueError("thickness must be positive, got {0!r}".format(t))
    return calculate_sphere_volume(inner + t) - calculate_sphere_volume(inner)


def format_report(radius):
    """Build a one-line summary of the sphere metrics for the given radius."""
    r = validate_radius(radius)
    volume = calculate_sphere_volume(r)
    area = calculate_sphere_surface_area(r)
    ratio = 0.
    if r > 0.:
        ratio = volume / area
    return "r={0:7.3f}  V={1:12.5f}  A={2:12.5f}  V/A={3:7.4f}".format(
        r, volume, area, ratio
    )


def main():
    radii = [
        1.,
        2.25,
        3.,
        .75,
        10.,
    ]
    for radius in radii:
        print(format_report(radius))

    whole = calculate_sphere_volume(2.)
    quarter = .25 * whole
    print("radius holding a quarter of the r=2 volume: {0:.6f}".format(
        radius_from_volume(quarter)))
    print("hemisphere of r=1.5: {0:.6f}".format(hemisphere_volume(1.5)))
    cap_height = .5
    print("cap h=0.5 of r=2.25: {0:.6f}".format(
        spherical_cap_volume(radii[1], cap_height)))
    wall = .125
    print("shell inner=1.0 wall=0.125: {0:.6f}".format(
        shell_volume(radii[0], wall)))


if __name__ == "__main__":
    main()

