import math


def parse_csv_line(line):
    """Split a single CSV row into a list of field strings."""
    if line is None:
        return []
    return line.rstrip("\r\n").split(",")


def parse_number(text):
    """Convert a CSV field to a float, understanding percentages; None if not numeric."""
    token = text.strip()
    if not token:
        return None
    if token.endswith("%"):
        try:
            return float(token[:-1]) / 100.0
        except ValueError:
            return None
    try:
        return float(token)
    except ValueError:
        return None


def round_half_up(value, places=2):
    """Round away from zero on ties, unlike Python's banker's rounding."""
    factor = 10.0 ** places
    if value < 0.0:
        return -math.floor(-value * factor + 0.5) / factor
    return math.floor(value * factor + 0.5) / factor


def quantile(values, q):
    """Linear-interpolation quantile of an unsorted sequence of numbers."""
    ordered = sorted(values)
    position = (len(ordered) - 1) * q
    low = int(math.floor(position))
    high = int(math.ceil(position))
    if low == high:
        return ordered[low]
    frac = position - low
    return ordered[low] * (1.0 - frac) + ordered[high] * frac


def summarize(values):
    """Mean plus quartiles for a non-empty list of numbers."""
    total = math.fsum(values)
    return {
        "mean": total / len(values),
        "q1": quantile(values, 0.25),
        "median": quantile(values, 0.5),
        "q3": quantile(values, 0.75),
    }


def row_revenue(fields):
    """Revenue for a record of product,units,unit_price,discount."""
    units = parse_number(fields[1])
    price = parse_number(fields[2])
    if units is None or price is None:
        return None
    discount = parse_number(fields[3]) or 0.0
    revenue = units * price * (1.0 - discount)
    if units >= 100.0:
        revenue *= 0.95
    return round_half_up(revenue)


def main():
    data = [
        "product,units,unit_price,discount",
        "apple,120,0.45,5%",
        "banana,80,0.30,",
        "cherry,,2.75,10%",
        "date,40,1.25,0%",
    ]
    rows = [parse_csv_line(line) for line in data]
    header = rows[0]
    print(" | ".join(header) + " | revenue")

    revenues = []
    for fields in rows[1:]:
        revenue = row_revenue(fields)
        if revenue is None:
            print(" | ".join(fields) + " | skipped (incomplete)")
            continue
        revenues.append(revenue)
        print(" | ".join(fields) + " | %.2f" % revenue)

    if not revenues:
        return
    stats = summarize(revenues)
    total = math.fsum(revenues)
    print("mean %.2f  median %.2f  iqr %.2f" % (stats["mean"], stats["median"], stats["q3"] - stats["q1"]))
    for fields, revenue in zip(rows[1:], revenues):
        share = revenue / total
        if share > 0.25:
            print("%s carries %.1f%% of revenue" % (fields[0], share * 100.0))


if __name__ == "__main__":
    main()

