def validate_event(event):
    """Check that an event is a well formed (start_time, end_time) tuple."""
    if not isinstance(event, tuple) or len(event) != 2:
        raise ValueError("an event must be a tuple of (start_time, end_time)")
    start, end = event
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("event times must be integers (minutes from midnight)")
    if end < start:
        raise ValueError("event end time must not precede its start time")
    return start, end


def check_event_overlap(event1, event2):
    """Return True if the two events share at least one moment in time."""
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return start1 < end2 and start2 < end1


def overlap_minutes(event1, event2):
    """Number of minutes the two events have in common."""
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return max(0, min(end1, end2) - max(start1, start2))


def duration_hours(event):
    """Length of an event expressed in hours."""
    start, end = validate_event(event)
    return (end - start) / 60.


def overlap_ratio(event1, event2):
    """Fraction of the shorter event that is lost to the collision."""
    shorter = min(duration_hours(event1), duration_hours(event2))
    if shorter == 0.:
        return 0.
    return (overlap_minutes(event1, event2) / 60.) / shorter


def midpoint(event):
    """Middle instant of an event, in minutes from midnight."""
    start, end = validate_event(event)
    return (start + end) * .5


def severity(ratio):
    if ratio >= .75:
        return "major"
    if ratio >= .25:
        return "moderate"
    return "minor"


def format_time(minutes):
    """Render a minute offset (possibly fractional) as HH:MM."""
    total = int(round(minutes))
    return "{:02d}:{:02d}".format((total // 60) % 24, total % 60)


def find_conflicts(schedule):
    """List every colliding pair of events as (index1, index2, ratio)."""
    conflicts = []
    for i in range(len(schedule)):
        for j in range(i + 1, len(schedule)):
            if check_event_overlap(schedule[i], schedule[j]):
                conflicts.append((i, j, overlap_ratio(schedule[i], schedule[j])))
    return conflicts


def main():
    schedule = [(540, 600), (570, 630), (660, 675), (680, 695), (700, 835)]
    for index, event in enumerate(schedule):
        hours = duration_hours(event)
        tag = " (long)" if hours > 2. else ""
        print("event {}: {} - {}  {:.2f}h centred on {}{}".format(
            index, format_time(event[0]), format_time(event[1]),
            hours, format_time(midpoint(event)), tag))
    conflicts = find_conflicts(schedule)
    if not conflicts:
        print("no overlapping events")
        return
    lost = 0.
    for i, j, ratio in conflicts:
        shared = overlap_minutes(schedule[i], schedule[j]) / 60.
        lost += shared
        print("events {} and {} overlap for {:.2f}h -> {} conflict ({:.0%})".format(
            i, j, shared, severity(ratio), ratio))
    print("total contested time: {:.2f}h".format(lost))
    if lost >= .5:
        print("reschedule recommended")


if __name__ == "__main__":
    main()

