def _validated(numbers):
    """Return the input as a list of floats, rejecting non-numeric entries."""
    values = []
    for item in numbers:
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("mean_absolute_deviation expects numbers, got %r" % (item,))
        values.append(float(item))
    return values


def mean(numbers):
    """Arithmetic mean of a list of numbers; 0.0 for an empty list."""
    values = _validated(numbers)
    if not values:
        return 0.0
    return sum(values) / len(values)


def mean_absolute_deviation(numbers):
    """Average absolute distance of the numbers from their mean."""
    values = _validated(numbers)
    if not values:
        return 0.0
    center = mean(values)
    return sum(abs(value - center) for value in values) / len(values)


def relative_deviation(numbers):
    """Mean absolute deviation expressed as a fraction of the mean's magnitude."""
    center = mean(numbers)
    if center == 0.0:
        return 0.0
    return mean_absolute_deviation(numbers) / abs(center)


def classify_spread(ratio):
    """Describe how dispersed a sample is, given its relative deviation."""
    if ratio < 0.25:
        return "tight"
    if ratio < 0.75:
        return "moderate"
    return "wide"


def describe(numbers):
    """Build a one-line summary of a sample's centre and dispersion."""
    values = _validated(numbers)
    center = mean(values)
    spread = mean_absolute_deviation(values)
    ratio = relative_deviation(values)
    return "n=%d mean=%.4f mad=%.4f rel=%.4f (%s)" % (
        len(values),
        center,
        spread,
        ratio,
        classify_spread(ratio),
    )


def main():
    samples = [
        [],
        [1, 2, 3, 4],
        [10, 20, 30],
        [
            0.5,
            1.25,
            2.75,
        ],
    ]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
