def is_valid_triangle(a, b, c):
    """Return True when the three lengths can form a non-degenerate triangle."""
    sides = sorted((a, b, c))
    if sides[0] <= 0.0:
        return False
    return sides[0] + sides[1] > sides[2]


def triangle_area(a, b, c):
    """Area of the triangle with the given side lengths (Heron's formula)."""
    if not is_valid_triangle(a, b, c):
        return 0.0
    s = 0.5 * (a + b + c)
    return (s * (s - a) * (s - b) * (s - c)) ** 0.5


def inradius(a, b, c):
    """Radius of the inscribed circle, or 0.0 for an impossible triangle."""
    area = triangle_area(a, b, c)
    if area == 0.0:
        return 0.0
    return area / (0.5 * (a + b + c))


def circumradius(a, b, c):
    """Radius of the circumscribed circle, or 0.0 for an impossible triangle."""
    area = triangle_area(a, b, c)
    if area == 0.0:
        return 0.0
    return (a * b * c) / (4.0 * area)


def classify(a, b, c):
    """Describe the triangle by its sides and its largest angle."""
    if not is_valid_triangle(a, b, c):
        return "degenerate"
    x, y, z = sorted((a, b, c))
    if x == z:
        shape = "equilateral"
    elif x == y or y == z:
        shape = "isosceles"
    else:
        shape = "scalene"
    longest = z * z
    others = x * x + y * y
    tolerance = 1e-9 * max(longest, 1.0)
    if abs(longest - others) <= tolerance:
        angle = "right"
    elif longest > others:
        angle = "obtuse"
    else:
        angle = "acute"
    return shape + " " + angle


def parse_sides(text):
    """Read three side lengths from a comma or space separated string."""
    parts = text.replace(",", " ").split()
    if len(parts) != 3:
        raise ValueError("expected three side lengths, got: " + text)
    return tuple(float(part) for part in parts)


def describe(a, b, c):
    """One-line human readable summary of a candidate triangle."""
    area = triangle_area(a, b, c)
    header = "sides {0:g}, {1:g}, {2:g}".format(a, b, c)
    if area == 0.0:
        return "{0}: not a triangle, area 0.0".format(header)
    return "{0}: {1}, area {2:.4f}, r {3:.4f}, R {4:.4f}".format(
        header, classify(a, b, c), area, inradius(a, b, c), circumradius(a, b, c)
    )


def main():
    samples = [
        "3, 4, 5",
        "1, 1, 10",
        "2.25, 2.25, 2.25",
        "0.75, 0.75, 1",
        "6, 8, 12.5",
        "-1, 2, 2.5",
    ]
    total = 0.0
    for text in samples:
        a, b, c = parse_sides(text)
        print(describe(a, b, c))
        total += triangle_area(a, b, c)
    print("total area of valid triangles: {0:.4f}".format(total))


if __name__ == "__main__":
    main()

