class ToDoList:
    """A small to-do list that tracks task names and their completion state."""

    def __init__(self, tasks=None):
        self._tasks = []
        for name in tasks or []:
            self.add_task(name)

    @staticmethod
    def _clean(task_name):
        if not isinstance(task_name, str):
            raise TypeError("task names must be strings")
        cleaned = task_name.strip()
        if not cleaned:
            raise ValueError("task names must not be empty")
        return cleaned

    def _find(self, cleaned):
        for task in self._tasks:
            if task["name"] == cleaned:
                return task
        return None

    def add_task(self, task_name):
        cleaned = self._clean(task_name)
        if self._find(cleaned) is not None:
            return False
        self._tasks.append({"name": cleaned, "done": False})
        return True

    def mark_completed(self, task_name):
        task = self._find(self._clean(task_name))
        if task is None:
            return False
        task["done"] = True
        return True

    def get_pending_tasks(self):
        return [task["name"] for task in self._tasks if not task["done"]]

    def get_completed_tasks(self):
        return [task["name"] for task in self._tasks if task["done"]]

    def completion_ratio(self):
        if not self._tasks:
            return 1.0
        done = len(self.get_completed_tasks())
        return done / len(self._tasks)

    def progress_bar(self, width=20):
        filled = int(self.completion_ratio() * width + 0.5)
        return "[" + "#" * filled + "-" * (width - filled) + "]"

    def status(self):
        ratio = self.completion_ratio()
        if ratio >= 1.0:
            return "all done"
        if ratio >= 0.75:
            return "almost there"
        if ratio >= 0.25:
            return "in progress"
        return "just started"

    def report(self):
        percent = self.completion_ratio() * 100.0
        lines = ["%s %5.1f%% (%s)" % (self.progress_bar(), percent, self.status())]
        for name in self.get_completed_tasks():
            lines.append("  [x] " + name)
        for name in self.get_pending_tasks():
            lines.append("  [ ] " + name)
        return "\n".join(lines)


def main():
    todo = ToDoList(["Buy milk", "Walk dog", "Pay rent", "Call plumber"])
    todo.mark_completed("Buy milk")
    print(todo.report())
    print("pending:", todo.get_pending_tasks())

    for name in list(todo.get_pending_tasks()):
        todo.mark_completed(name)
    if todo.completion_ratio() == 1.0:
        print("Everything on the list is finished.")
    print(todo.report())


if __name__ == "__main__":
    main()

