import math


def geometric_mean(numbers):
    """Return the geometric mean of a list of positive numbers, else 0.0."""
    if not numbers:
        return 0.0
    log_sum = 0.0
    for value in numbers:
        if value <= 0:
            return 0.0
        log_sum += math.log(value)
    return math.exp(log_sum / len(numbers))


def arithmetic_mean(numbers):
    """Return the arithmetic mean, or 0.0 for an empty list."""
    if not numbers:
        return 0.0
    total = 0.0
    for value in numbers:
        total += value
    return total / len(numbers)


def harmonic_mean(numbers):
    """Return the harmonic mean of positive numbers, else 0.0."""
    if not numbers:
        return 0.0
    reciprocal_sum = 0.0
    for value in numbers:
        if value <= 0:
            return 0.0
        reciprocal_sum += 1.0 / value
    return len(numbers) / reciprocal_sum


def geometric_spread(numbers):
    """Return the multiplicative spread factor around the geometric mean."""
    center = geometric_mean(numbers)
    if center == 0.0 or len(numbers) < 2:
        return 1.0
    log_center = math.log(center)
    squared = 0.0
    for value in numbers:
        deviation = math.log(value) - log_center
        squared += deviation * deviation
    return math.exp(math.sqrt(squared / (len(numbers) - 1)))


def means_are_ordered(numbers):
    """True when harmonic <= geometric <= arithmetic holds numerically."""
    low = harmonic_mean(numbers)
    middle = geometric_mean(numbers)
    high = arithmetic_mean(numbers)
    tolerance = 1e-9
    return low <= middle + tolerance and middle <= high + tolerance


def format_report(numbers):
    """Build a one-line summary of the means of a sample."""
    sample = ", ".join(format(float(v), "g") for v in numbers)
    center = geometric_mean(numbers)
    if center == 0.0:
        return "[" + sample + "] -> undefined (empty or non-positive values)"
    spread = geometric_spread(numbers)
    midpoint = (harmonic_mean(numbers) + arithmetic_mean(numbers)) * 0.5
    flag = "ordered" if means_are_ordered(numbers) else "unordered"
    return "[%s] -> geo=%.4f spread=%.4f mid=%.4f (%s)" % (
        sample, center, spread, midpoint, flag)


def main():
    halved = [0.5, 2]
    mixed = [1.5, 9, 4]
    prices = [10, 12, 10.5]
    samples = [[1, 2, 4], [2, 8], halved, mixed, prices, [3, -1, 4], []]
    for sample in samples:
        print(format_report(sample))
    growth = [
        1.05,
        1.2,
        1,
    ]
    factor = geometric_mean(growth)
    print("compounded growth over %d periods: %.4f"
          % (len(growth), factor ** len(growth)))


if __name__ == "__main__":
    main()

