def is_valid_email(email_string):
    """Return True if the string looks like a basic email address."""
    if not isinstance(email_string, str):
        return False
    candidate = email_string.strip()
    if candidate.count("@") != 1:
        return False
    local, domain = candidate.split("@")
    if not local or not domain:
        return False
    return "." in domain


def split_address(email_string):
    """Return (local, domain, tld) for a valid address, or None."""
    if not is_valid_email(email_string):
        return None
    local, domain = email_string.strip().split("@")
    tld = domain.rsplit(".", 1)[1]
    return local, domain, tld


def quality_score(email_string):
    """Score an address between 0.0 and 1.0 based on simple heuristics."""
    parts = split_address(email_string)
    if parts is None:
