def levenshtein_distance(s1, s2):
    """Return the minimum number of edits needed to turn s1 into s2."""
    if s1 == s2:
        return 0
    if not s1:
        return len(s2)
    if not s2:
        return len(s1)

    previous = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1, start=1):
        current = [i]
        for j, c2 in enumerate(s2, start=1):
            deletion = previous[j] + 1
            insertion = current[j - 1] + 1
            substitution = previous[j - 1] + (c1 != c2)
            current.append(min(deletion, insertion, substitution))
        previous = current
    return previous[-1]


def similarity_ratio(s1, s2):
    """Normalised similarity in [0.0, 1.0]; 1.0 means identical strings."""
    longest = max(len(s1), len(s2))
    if longest == 0:
        return 1.0
    return 1.0 - levenshtein_distance(s1, s2) / longest


def classify(ratio):
    """Describe how close two strings are, based on their similarity ratio."""
    if ratio >= 1.0:
        return "identical"
    if ratio >= 0.75:
        return "very similar"
    if ratio >= 0.5:
        return "somewhat similar"
    if ratio >= 0.25:
        return "distant"
    return "unrelated"


def best_match(word, candidates, threshold=0.5):
    """Pick the candidate closest to word, or None if none passes threshold."""
    best, best_ratio = None, 0.0
    for candidate in candidates:
        ratio = similarity_ratio(word, candidate)
        if ratio > best_ratio:
            best, best_ratio = candidate, ratio
    if best_ratio < threshold:
        return None
    return best


def format_report(s1, s2):
    ratio = similarity_ratio(s1, s2)
    return "{:>8} -> {:<8} distance={} similarity={:5.1f}% ({})".format(
        s1, s2, levenshtein_distance(s1, s2), ratio * 100.0, classify(ratio)
    )


def main():
    pairs = [
        ("kitten", "sitting"),
        ("flaw", "lawn"),
        ("book", "book"),
        ("apple", "orange"),
        ("", "abc"),
    ]
    for s1, s2 in pairs:
        print(format_report(s1, s2))

    dictionary = ["receive", "relieve", "believe", "retrieve"]
    for typo in ("recieve", "belive", "xyzzy"):
        match = best_match(typo, dictionary, threshold=0.75)
        suggestion = match if match else "no suggestion"
        print("{:>8}: {}".format(typo, suggestion))


if __name__ == "__main__":
    main()

