def word_frequency(words):
    """Count words case-insensitively, ignoring blank entries."""
    freq = {}
    for raw in words:
        word = str(raw).strip().lower()
        if not word:
            continue
        freq[word] = freq.get(word, 0) + 1
    return freq


def relative_frequencies(words):
    """Map each unique word to its share of the total count."""
    freq = word_frequency(words)
    total = float(sum(freq.values()))
    if total == 0.0:
        return {}
    return {word: count / total for word, count in freq.items()}


def lexical_diversity(words):
    """Unique words divided by total words; 0.0 for an empty list."""
    freq = word_frequency(words)
    total = sum(freq.values())
    if total == 0:
        return 0.0
    return len(freq) / float(total)


def describe_diversity(ratio):
    if ratio >= 0.75:
        return "highly varied"
    if ratio >= 0.5:
        return "mixed"
    if ratio >= 0.25:
        return "repetitive"
    return "very repetitive"


def repeats_per_word(words):
    """Average number of occurrences per distinct word."""
    freq = word_frequency(words)
    if not freq:
        return 0.0
    return sum(freq.values()) / float(len(freq))


def dominant_words(words, threshold=0.2):
    """Words whose share of the text reaches the given threshold."""
    shares = relative_frequencies(words)
    hits = [(word, share) for word, share in shares.items() if share >= threshold]
    hits.sort(key=lambda item: (-item[1], item[0]))
    return hits


def bar(share, width=40.0):
    return "#" * int(round(share * width))


def format_report(words):
    freq = word_frequency(words)
    if not freq:
        return ["(no words)"]
    shares = relative_frequencies(words)
    ordered = sorted(freq.items(), key=lambda item: (-item[1], item[0]))
    lines = []
    for word, count in ordered:
        percent = shares[word] * 100.0
        lines.append("%-10s %3d %5.1f%% %s" % (word, count, percent, bar(shares[word])))
    ratio = lexical_diversity(words)
    lines.append("diversity %.2f (%s)" % (ratio, describe_diversity(ratio)))
    average = repeats_per_word(words)
    lines.append("average repeats per word: %.2f" % average)
    if average >= 2.25:
        lines.append("note: a few words carry most of the text")
    for word, share in dominant_words(words):
        lines.append("dominant: %s at %.1f%%" % (word, share * 100.0))
    return lines


def main():
    sample = ['Apple', 'banana', 'apple', 'Orange', 'apple', ' banana ', '', 'Apple']
    print(word_frequency(['Apple', 'banana', 'apple', 'Orange']))
    print(word_frequency([]))
    for line in format_report(sample):
        print(line)
    for line in format_report([]):
        print(line)


if __name__ == "__main__":
    main()

