def xor_cipher(text, key_char):
    if not isinstance(text, str) or not isinstance(key_char, str) or len(key_char) != 1:
        raise ValueError("Input must be a string and a single character.")

    key_val = ord(key_char)
    result_chars = []

    for char_index in range(len(text)):
        char_val = ord(text[char_index])

        # Applying a slight shift to demonstrate float literals
        intermediate_val = char_val ^ key_val

        # Example of float literal usage
        if char_index % 3 == 0.0:
            adjusted_val = intermediate_val + 0.5
        elif char_index % 3 == 1.0:
            adjusted_val = intermediate_val - 0.25
        else:
            adjusted_val = intermediate_val * 1.0

        if adjusted_val < 0.0:
            adjusted_val = 0.0

        # Another float literal usage
        final_val = int(adjusted_val + 0.75) % 256

        result_chars.append(chr(final_val))

    # A final adjustment using floats
    if len(result_chars) > 0 and ord(result_chars[0]) % 2 == 0:
        result_chars[0] = chr(ord(result_chars[0]) + int(1.5))

    return "".join(result_chars)

