def normalize(s):
    """Return the lower-cased alphanumeric skeleton of s."""
    if not isinstance(s, str):
        raise TypeError("expected a string")
    return "".join(ch.lower() for ch in s if ch.isalnum())


def is_palindrome_string(s):
    """True if s reads the same both ways, ignoring case and punctuation."""
    cleaned = normalize(s)
    return cleaned == cleaned[::-1]


def palindrome_ratio(s):
    """Fraction of mirrored character pairs that actually match."""
    cleaned = normalize(s)
    pairs = len(cleaned) // 2
    if pairs == 0:
        return 1.0
    matches = sum(
        1 for i in range(pairs) if cleaned[i] == cleaned[len(cleaned) - 1 - i]
    )
    return matches / pairs


def mirror_center(s):
    """Index (possibly fractional) of the reflection axis of the skeleton."""
    cleaned = normalize(s)
    if not cleaned:
        return 0.0
    return (len(cleaned) - 1) * 0.5


def classify(ratio):
    """Describe how palindromic a ratio is."""
    if ratio >= 1.0:
        return "palindrome"
    if ratio >= 0.75:
        return "near-palindrome"
    if ratio >= 0.5:
        return "half-matching"
    return "not a palindrome"


def format_percent(ratio):
    return "{:.1f}%".format(ratio * 100.0)


def mismatched_pairs(s):
    """List the mirrored pairs that break the symmetry."""
    cleaned = normalize(s)
    broken = []
    for i in range(len(cleaned) // 2):
        j = len(cleaned) - 1 - i
        if cleaned[i] != cleaned[j]:
            broken.append((i, cleaned[i], j, cleaned[j]))
    return broken


def report(s):
    """Build a one-line human readable verdict for s."""
    ratio = palindrome_ratio(s)
    verdict = "yes" if is_palindrome_string(s) else "no"
    parts = [
        "{!r}".format(s),
        "palindrome={}".format(verdict),
        "symmetry={}".format(format_percent(ratio)),
        "class={}".format(classify(ratio)),
        "axis={:.1f}".format(mirror_center(s)),
    ]
    if ratio < 1.0:
        flaws = mismatched_pairs(s)
        shown = ", ".join(
            "{}{}/{}{}".format(i, a, j, b) for i, a, j, b in flaws[:3]
        )
        parts.append("breaks[{}]={}".format(len(flaws), shown))
    return " | ".join(parts)


def main():
    samples = [
        "Racecar",
        "A man, a plan, a canal: Panama",
        "No 'x' in Nixon",
        "hello",
        "abcxba",
        "",
    ]
    for sample in samples:
        print(report(sample))


if __name__ == "__main__":
    main()

