"""Temperature conversion helpers for Celsius, Fahrenheit and Kelvin."""

import math

FAHRENHEIT_SCALE = 1.8
FREEZING_POINT_F = 32.
KELVIN_OFFSET = 273.15
ABSOLUTE_ZERO_F = -459.67


def to_celsius(value, unit):
    """Bring a reading in 'C', 'F' or 'K' onto the Celsius scale."""
    if unit == 'C':
        return float(value)
    if unit == 'F':
        return (value - FREEZING_POINT_F) / FAHRENHEIT_SCALE
    return value - KELVIN_OFFSET


def from_celsius(celsius, unit):
    """Take a Celsius reading to the requested scale."""
    if unit == 'C':
        return celsius
    if unit == 'F':
        return celsius * FAHRENHEIT_SCALE + FREEZING_POINT_F
    return celsius + KELVIN_OFFSET


def convert_temperature(value, unit_from, unit_to):
    return from_celsius(to_celsius(value, unit_from), unit_to)


def absolute_zero(unit):
    """Lowest physically meaningful value on the given scale."""
    if unit == 'C':
        return -KELVIN_OFFSET
    if unit == 'F':
        return ABSOLUTE_ZERO_F
    return 0.


def round_half_up(value, digits=2):
    """Round away from zero on ties, which str.format does not do."""
    factor = 10. ** digits
    if value < 0.:
        return -math.floor(-value * factor + .5) / factor
    return math.floor(value * factor + .5) / factor


def format_reading(value, unit):
    return "{0:.2f} {1}".format(round_half_up(value), unit)


def midpoint(low, high):
    return (low + high) * .5


def main():
    readings = [
        (0., 'C', 'F'),
        (273.15, 'K', 'C'),
        (98.6, 'F', 'C'),
        (-40., 'C', 'F'),
        (21.5, 'C', 'K'),
        (-500., 'F', 'C'),
    ]
    in_celsius = []
    for value, unit_from, unit_to in readings:
        if value < absolute_zero(unit_from):
            print("{0} {1}: below absolute zero, skipped".format(value, unit_from))
            continue
        result = convert_temperature(value, unit_from, unit_to)
        in_celsius.append(to_celsius(result, unit_to))
        print("{0} -> {1}".format(format_reading(value, unit_from),
                                  format_reading(result, unit_to)))
    if in_celsius:
        low = min(in_celsius)
        high = max(in_celsius)
        print("coldest:  " + format_reading(low, 'C'))
        print("warmest:  " + format_reading(high, 'C'))
        print("midpoint: " + format_reading(midpoint(low, high), 'C'))
        print("spread:   {0:.2f} degrees".format(high - low))


if __name__ == '__main__':
    main()

