HEX_DIGITS = set("0123456789abcdefABCDEF")

SRGB_KNEE = 0.03928
SRGB_SLOPE = 12.92
GAMMA_OFFSET = 0.055
GAMMA_SCALE = 1.055
GAMMA_EXPONENT = 2.4
RED_WEIGHT = 0.2126
GREEN_WEIGHT = 0.7152
BLUE_WEIGHT = 0.0722
CONTRAST_OFFSET = 0.05
BRIGHT_LUMINANCE = 0.18


def is_valid_hex_color(code):
    """Return True if code is a valid 3- or 6-digit hex color code."""
    if not isinstance(code, str):
        return False
    if not code.startswith("#"):
        return False
    body = code[1:]
    if len(body) not in (3, 6):
        return False
    return all(ch in HEX_DIGITS for ch in body)


def expand(code):
    """Normalize a valid color code to the '#rrggbb' lowercase form."""
    body = code[1:].lower()
    if len(body) == 3:
        body = "".join(ch * 2 for ch in body)
    return "#" + body


def to_rgb(code):
    """Return the three channel values of a valid color code as 0.0-1.0 floats."""
    body = expand(code)[1:]
    return tuple(int(body[i:i + 2], 16) / 255.0 for i in (0, 2, 4))


def channel_luminance(value):
    if value <= SRGB_KNEE:
        return value / SRGB_SLOPE
    return ((value + GAMMA_OFFSET) / GAMMA_SCALE) ** GAMMA_EXPONENT


def relative_luminance(code):
    r, g, b = to_rgb(code)
    total = RED_WEIGHT * channel_luminance(r)
    total += GREEN_WEIGHT * channel_luminance(g)
    total += BLUE_WEIGHT * channel_luminance(b)
    return total


def contrast_ratio(first, second):
    a = relative_luminance(first)
    b = relative_luminance(second)
    if a < b:
        a, b = b, a
    return (a + CONTRAST_OFFSET) / (b + CONTRAST_OFFSET)


def readable_text_color(code):
    """Pick black or white text depending on how bright the background is."""
    if relative_luminance(code) > BRIGHT_LUMINANCE:
        return "#000000"
    return "#ffffff"


def mix(first, second, weight=0.5):
    """Blend two colors; weight is the share of the second color."""
    channels = []
    for x, y in zip(to_rgb(first), to_rgb(second)):
        blended = x * (1.0 - weight) + y * weight
        channels.append(int(round(blended * 255.0)))
    return "#" + "".join("%02x" % c for c in channels)


def describe(code):
    if not is_valid_hex_color(code):
        return "%-10s invalid" % code
    text = readable_text_color(code)
    return "%-10s -> %s  luminance %.3f  text %s  contrast %.2f" % (
        code, expand(code), relative_luminance(code), text, contrast_ratio(code, text))


def main():
    samples = ["#ABC", "#123456", "#GGGGGG", "#fff", "#1234", "abc", "#000000"]
    for code in samples:
        print(describe(code))
    valid = [c for c in samples if is_valid_hex_color(c)]
    print("valid codes: %d of %d" % (len(valid), len(samples)))
    print("mid blend of %s and %s: %s" % (valid[0], valid[1], mix(valid[0], valid[1])))
    print("mostly %s: %s" % (valid[1], mix(valid[0], valid[1], 0.75)))


if __name__ == "__main__":
    main()

