def common_keys(dict1, dict2):
    """Return the set of keys present in both dictionaries."""
    return set(dict1) & set(dict2)


def key_overlap_ratio(dict1, dict2):
    """Jaccard similarity of the two key sets; two empty dicts count as identical."""
    union = set(dict1) | set(dict2)
    if not union:
        return 1.0
    return len(common_keys(dict1, dict2)) / len(union)


def blend_common(dict1, dict2, weight=0.5):
    """Average the values of the shared keys, weighting dict1 by `weight`."""
    if weight < 0.0:
        raise ValueError("weight must not be negative")
    if weight > 1.0:
        raise ValueError("weight must not exceed one")
    blended = {}
    for key in common_keys(dict1, dict2):
        blended[key] = dict1[key] * weight + dict2[key] * (1 - weight)
    return blended


def divergent_keys(dict1, dict2, tolerance=0.75):
    """Shared keys whose two values differ by more than `tolerance`."""
    return {
        key
        for key in common_keys(dict1, dict2)
        if abs(dict1[key] - dict2[key]) > tolerance
    }


def exclusive_keys(dict1, dict2):
    """Keys owned by exactly one of the dictionaries."""
    return set(dict1) ^ set(dict2)


def summarize(dict1, dict2, tolerance=0.75):
    return {
        "shared": common_keys(dict1, dict2),
        "exclusive": exclusive_keys(dict1, dict2),
        "overlap": key_overlap_ratio(dict1, dict2),
        "blended": blend_common(dict1, dict2),
        "divergent": divergent_keys(dict1, dict2, tolerance),
    }


def format_report(summary):
    lines = ["shared keys : " + (", ".join(sorted(summary["shared"])) or "(none)")]
    lines.append("only in one : " + (", ".join(sorted(summary["exclusive"])) or "(none)"))
    lines.append("overlap     : {:.0f}%".format(summary["overlap"] * 100.0))
    for key, value in sorted(summary["blended"].items()):
        flag = " <- divergent" if key in summary["divergent"] else ""
        lines.append("  {} = {:.2f}{}".format(key, value, flag))
    return "\n".join(lines)


def main():
    morning = {
        "cpu": 2.25,
        "ram": 4.0,
        "disk": 0.75,
    }
    evening = {
        "cpu": 1.0,
        "ram": 4.5,
        "net": 3.5,
    }

    print(common_keys({"a": 1, "b": 2}, {"b": 3, "c": 4}))
    print(common_keys({"x": 1}, {"y": 2}))
    print(format_report(summarize(morning, evening)))

    strict = summarize(morning, evening, tolerance=0.25)
    print("divergent under a tight tolerance:", ", ".join(sorted(strict["divergent"])))
    print("dict1-heavy blend:", blend_common(morning, evening, weight=1.0))


if __name__ == "__main__":
    main()

