def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count


def bit_length(n):
    """Number of bits needed to write n, with zero occupying a single bit."""
    return max(n.bit_length(), 1)


def bit_density(n):
    """Fraction of the bits of n that are set, in the range 0.0 to 1.0."""
    if n == 0:
        return 0.0
    return count_set_bits(n) / bit_length(n)


def is_dense(n):
    """True when at least half of the bits of n are ones."""
    return bit_density(n) >= 0.5


def hamming_distance(a, b):
    """Number of bit positions in which a and b differ."""
    return count_set_bits(a ^ b)


def average_set_bits(values):
    """Mean population count over a sequence of non-negative integers."""
    values = list(values)
    if not values:
        return 0.0
    total = sum(count_set_bits(v) for v in values)
    return total / len(values)


def balance(n):
    """Signed measure of how far n is from having equal ones and zeros."""
    excess = bit_density(n) - 0.5
    return excess * 2.0


def format_row(n):
    """Render one report line describing the bits of n."""
    return "{:>6} {:>12} {:>3} {:>7.2f}% {:>6.2f} {}".format(
        n,
        format(n, "b"),
        count_set_bits(n),
        bit_density(n) * 100.0,
        balance(n),
        "dense" if is_dense(n) else "sparse",
    )


def report(values):
    """Build a multi-line report for the given integers."""
    header = "{:>6} {:>12} {:>3} {:>8} {:>6} {}".format(
        "n", "binary", "ones", "density", "bal", "class"
    )
    lines = [header]
    lines.extend(format_row(v) for v in values)
    lines.append("average ones per value: {:.3f}".format(average_set_bits(values)))
    return "\n".join(lines)


def main():
    samples = [0, 1, 7, 10, 255, 256, 1023, 4095]
    print(report(samples))
    print("count_set_bits(10) =", count_set_bits(10))
    print("count_set_bits(7)  =", count_set_bits(7))
    print("hamming_distance(10, 7) =", hamming_distance(10, 7))
    spread = max(balance(v) for v in samples) - min(balance(v) for v in samples)
    print("balance spread: {:.2f} of a possible 2".format(spread))
    ratio = average_set_bits(samples) / 4.0
    print("average ones relative to a nibble: {:.2f}".format(ratio))


if __name__ == "__main__":
    main()

