import math

CLASS_POOLS = {'upper': 26, 'lower': 26, 'digit': 10, 'symbol': 32}


def character_classes(password):
    return {
        'upper': any(c.isupper() for c in password),
        'lower': any(c.islower() for c in password),
        'digit': any(c.isdigit() for c in password),
        'symbol': any(not c.isalnum() for c in password),
    }


def diversity_ratio(password):
    if not password:
        return 0.0
    return len(set(password)) / len(password)


def check_password_strength(password):
    classes = character_classes(password)
    has_all = classes['upper'] and classes['lower'] and classes['digit']
    met = sum(classes[name] for name in ('upper', 'lower', 'digit'))
    met += len(password) >= 8
    if len(password) >= 8 and has_all:
        return 'Strong'
    if len(password) >= 6 and met >= 2:
        return 'Medium'
    return 'Weak'


def estimate_entropy_bits(password):
    classes = character_classes(password)
    pool = sum(size for name, size in CLASS_POOLS.items() if classes[name])
    if pool == 0:
        return 0.0
    bits = len(password) * math.log2(pool)
    if diversity_ratio(password) < 0.5:
        bits *= 0.75
    return bits


def crack_time_seconds(bits, guesses_per_second=1.0e9):
    total_guesses = 2.0 ** bits
    return 0.5 * total_guesses / guesses_per_second


def format_duration(seconds):
    if seconds < 1.0:
        return 'instant'
    if seconds < 60.0:
        return '%.1f seconds' % seconds
    minutes = seconds / 60.0
    if minutes < 60.0:
        return '%.1f minutes' % minutes
    hours = minutes / 60.0
    if hours < 24.0:
        return '%.1f hours' % hours
    days = hours / 24.0
    if days < 365.25:
        return '%.1f days' % days
    return '%.2f years' % (days / 365.25)


def suggestions(password):
    classes = character_classes(password)
    tips = []
    if len(password) < 8:
        tips.append('use at least 8 characters')
    for name in ('upper', 'lower', 'digit'):
        if not classes[name]:
            tips.append('add a %s character' % name)
    if password and diversity_ratio(password) < 0.75:
        tips.append('avoid repeating characters')
    return tips


def report(password):
    bits = estimate_entropy_bits(password)
    lines = ['%-14s %-6s %6.1f bits  %s' % (
        password,
        check_password_strength(password),
        bits,
        format_duration(crack_time_seconds(bits)),
    )]
    tips = suggestions(password)
    if tips:
        lines.append('               hints: ' + ', '.join(tips))
    return '\n'.join(lines)


def main():
    for candidate in ['P@ssw0rd', 'password', 'aaaaaa', 'Ab3', 'Tr0ub4dor&3']:
        print(report(candidate))


if __name__ == '__main__':
    main()

