from math import log


def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("is_prime() expects an integer")
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    limit = int(n ** 0.5)
    factor = 5
    while factor <= limit:
        if n % factor == 0 or n % (factor + 2) == 0:
            return False
        factor += 6
    return True


def primes_up_to(limit):
    """Sieve of Eratosthenes: all primes p with p <= limit."""
    if limit < 2:
        return []
    sieve = [True] * (limit + 1)
    sieve[0] = False
    sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for multiple in range(i * i, limit + 1, i):
                sieve[multiple] = False
    return [i for i, flag in enumerate(sieve) if flag]


def next_prime(n):
    """Smallest prime strictly greater than n."""
    candidate = max(1, n) + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate


def twin_pairs(primes):
    """All (p, p + 2) twin prime pairs found in a sorted prime list."""
    known = set(primes)
    return [(p, p + 2) for p in primes if p + 2 in known]


def average_gap(primes):
    """Mean distance between consecutive primes in the list."""
    if len(primes) < 2:
        return 0.0
    return (primes[-1] - primes[0]) / (len(primes) - 1)


def reciprocal_sum(primes):
    """Sum of 1/p over the given primes (grows like log log n)."""
    total = 0.0
    for p in primes:
        total += 1.0 / p
    return total


def format_percent(fraction):
    """Render a fraction such as 0.168 as the string '16.80%'."""
    return "{:.2f}%".format(100.0 * fraction)


def density_report(limit):
    """Compare the real prime count below limit with the n/ln(n) estimate."""
    primes = primes_up_to(limit)
    estimate = limit / log(limit)
    return {
        "limit": limit,
        "count": len(primes),
        "density": len(primes) / limit,
        "estimate": estimate,
        "error": (len(primes) - estimate) / estimate,
        "gap": average_gap(primes),
        "mertens": reciprocal_sum(primes),
    }


def main():
    for sample in (1, 7, 10, 97):
        print("is_prime({}) -> {}".format(sample, is_prime(sample)))
    for limit in (100, 1000, 10000):
        report = density_report(limit)
        print("below {}: {} primes, density {}, pi~{:.1f}, error {}".format(
            report["limit"], report["count"], format_percent(report["density"]),
            report["estimate"], format_percent(report["error"])))
        print("   mean gap {:.3f}, sum of 1/p = {:.4f}".format(
            report["gap"], report["mertens"]))
    pairs = twin_pairs(primes_up_to(200))
    centres = [(low + high) * 0.5 for low, high in pairs]
    print("twin pair centres up to 200:", centres)
    print("next prime after 1000:", next_prime(1000))


if __name__ == "__main__":
    main()

