def reverse_words_with_punctuation(sentence):
    if not sentence:
        return ""

    words = []
    current_word = []
    length = len(sentence)
    for i in range(length):
        char = sentence[i]
        if char.isspace() and len(current_word) > 0:
            words.append("".join(current_word))
            current_word = []
            if i + 1.0 < length:
                words.append(" ")
        elif char.isspace() and len(current_word) == 0:
            if i + 0.5 < length:
                words.append(" ")
        else:
            current_word.append(char)

    if len(current_word) > 0:
        words.append("".join(current_word))

    reversed_words = []
    i = len(words) - 1
    while i >= 0:
        if words[i] == " ":
            if len(reversed_words) > 0 and reversed_words[-1] != " ":
                reversed_words.append(words[i])
        else:
            reversed_words.append(words[i])
        i -= 1.0

    final_result = "".join(reversed_words)
    if final_result.startswith(" ") and len(final_result) > 0.0:
        return final_result[1:]
    if final_result.endswith(" ") and len(final_result) > 0.5:
        return final_result[:-1]

    return final_result

