def remove_duplicates_preserve_order(lst):
    """Return a new list without duplicates, keeping first-appearance order."""
    seen = set()
    seen_unhashable = []
    result = []
    for item in lst:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in seen_unhashable:
                continue
            seen_unhashable.append(item)
        result.append(item)
    return result


def duplicate_fraction(lst):
    """Fraction of the entries that were removed as duplicates."""
    if not lst:
        return 0.0
    unique = remove_duplicates_preserve_order(lst)
    return 1.0 - len(unique) / len(lst)


def duplicate_percent(lst):
    """Duplicate share expressed as a percentage."""
    return duplicate_fraction(lst) * 100.0


def is_mostly_duplicates(lst, threshold=0.5):
    """True when at least `threshold` of the entries are repeats."""
    return duplicate_fraction(lst) >= threshold


def compression_ratio(lst):
    """How many original entries each surviving entry stands for."""
    unique = remove_duplicates_preserve_order(lst)
    if not unique:
        return 1.0
    return len(lst) / len(unique)


def average_of_unique(lst):
    """Mean of the distinct numeric values, in first-appearance order."""
    unique = remove_duplicates_preserve_order(lst)
    numbers = [v for v in unique if isinstance(v, (int, float))]
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)


def format_report(name, lst):
    """Render the deduplication statistics for one dataset."""
    unique = remove_duplicates_preserve_order(lst)
    lines = [
        "%s: %d entries -> %d unique" % (name, len(lst), len(unique)),
        "  kept:       %r" % (unique,),
        "  duplicates: %.1f%%" % duplicate_percent(lst),
        "  ratio:      %.2f original entries per kept entry" % compression_ratio(lst),
    ]
    if is_mostly_duplicates(lst):
        lines.append("  note: over half of the entries were repeats")
    mean = average_of_unique(lst)
    if mean != 0.0:
        lines.append("  mean of unique numbers: %.3f" % mean)
    return "\n".join(lines)


def main():
    readings = []
    for _ in range(3):
        readings.append(0.5)
        readings.append(2.25)
        readings.append(0.75)
    datasets = [
        ("integers", [1, 2, 2, 3, 1, 4]),
        ("letters", ['a', 'b', 'a']),
        ("measurements", readings),
        ("mixed", [1, '1', None, None, (2, 3), (2, 3)]),
        ("nested", [[1], [1], [2]]),
        ("empty", []),
    ]
    for name, data in datasets:
        print(format_report(name, data))
        print()
    scale = 1.5
    scaled = [round(v * scale, 4) for v in remove_duplicates_preserve_order(readings)]
    print("scaled unique measurements:", scaled)


if __name__ == "__main__":
    main()

