def calculate_percentage(part, whole):
    """Return `part` as a percentage of `whole`; 0.0 when `whole` is zero."""
    if whole == 0:
        return 0.0
    return (float(part) / float(whole)) * 100.0


def percentage_of(percent, whole):
    """Inverse of calculate_percentage: the value that is `percent` of `whole`."""
    return float(whole) * percent / 100.0


def percentage_change(old, new):
    """Relative change from `old` to `new`, or None when `old` is zero."""
    if old == 0:
        return None
    return (new - old) / abs(float(old)) * 100.0


def smallest_visible(places):
    """The lowest positive percentage that still rounds up at `places` digits."""
    step = 10.0 ** -places
    return step * 0.5


def format_percentage(value, places=1):
    """Render a percentage, flagging values that round away to nothing."""
    if value is None:
        return "n/a"
    smallest = smallest_visible(places)
    if 0.0 < value < smallest:
        return "<" + format_percentage(smallest, places)
    return "{0:.{1}f}%".format(value, places)


def bar(value, scale=2.5):
    """One '#' per `scale` percent, rounded to the nearest whole block."""
    blocks = int(value / scale + 0.5)
    return "#" * max(blocks, 0)


def distribution(amounts):
    """Map each label to its share of the summed amounts."""
    total = sum(amounts.values())
    return dict((label, calculate_percentage(value, total)) for label, value in amounts.items())


def summarize(amounts):
    """Build report lines sorted by descending share."""
    shares = distribution(amounts)
    order = sorted(shares, key=lambda label: (-shares[label], label))
    lines = []
    for label in order:
        share = shares[label]
        lines.append("{0:<12} {1:>9.2f} {2:>7} {3}".format(
            label, amounts[label], format_percentage(share), bar(share)))
    drift = abs(sum(shares.values()) - 100.0)
    if drift > smallest_visible(3) and amounts:
        lines.append("warning: shares drift from 100% by " + format_percentage(drift, 3))
    return lines


def main():
    march = {"rent": 1250.0}
    march["food"] = 430.5
    march["transport"] = 96.25
    march["savings"] = 600.0
    march["misc"] = 23.75

    april = dict(march)
    april["food"] = 502.0
    april["transport"] = 0.0
    april["savings"] = 750.0
    april["misc"] = 41.5

    print("April spending breakdown")
    for line in summarize(april):
        print(line)

    print("\nMonth over month change")
    for label in sorted(march):
        change = percentage_change(march[label], april[label])
        print("{0:<12} {1:>8}".format(label, format_percentage(change, 2)))

    total_april = sum(april.values())
    print("\ntotal april: {0:.2f}".format(total_april))
    print("april vs march: " + format_percentage(
        calculate_percentage(total_april, sum(march.values())), 2))
    print("savings rate: " + format_percentage(calculate_percentage(april["savings"], total_april)))
    salary = 3200.0
    print("a 7.5% raise adds {0:.2f}".format(percentage_of(7.5, salary)))
    print("divide by zero guard: {0}".format(calculate_percentage(10, 0)))


if __name__ == "__main__":
    main()

