    """Round a monetary amount to whole cents, half away from zero."""
    cents = int(abs(amount) * 100 + 0.5)
    value = cents / 100.0
    if amount < 0:
        return -value
    return value


def list_to_dict(key_value_list):
    """Turn a list of [key, value] pairs into a dict; the last value wins."""
    result = {}
    for pair in key_value_list:
        if len(pair) != 2:
            raise ValueError("each entry must be a [key, value] pair: %r" % (pair,))
        key, value = pair
        result[key] = value
    return result


def apply_discount(prices, rate=0.25):
    """Return a new price table with every price reduced by `rate`."""
    if rate < 0.0:
        raise ValueError("rate must not be negative: %r" % rate)
    if rate >= 1.0:
        raise ValueError("rate must be below one: %r" % rate)
    factor = 1.0 - rate
    return {name: money(price * factor) for name, price in prices.items()}


def summarize(prices):
    """Count, total, mean and cheapest entry of a price table."""
    if not prices:
        empty = 0.0
        return {"count": 0, "total": empty, "mean": empty, "cheapest": None}
    values = list(prices.values())
    total = sum(values)
    return {
        "count": len(values),
        "total": money(total),
        "mean": money(total / len(values)),
        "cheapest": min(prices, key=lambda name: prices[name]),
    }


