def normalize(rng):
    """Return a (start, end) tuple with start <= end, validating the input."""
    if not isinstance(rng, (tuple, list)) or len(rng) != 2:
        raise ValueError("a range must be a pair (start, end)")
    start, end = rng
    for value in (start, end):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("range bounds must be numbers")
    if start > end:
        return (end, start)
    return (start, end)


def range_overlap(range1, range2):
    """Return the overlapping portion of two ranges, or None if disjoint."""
    start1, end1 = normalize(range1)
    start2, end2 = normalize(range2)
    overlap_start = max(start1, start2)
    overlap_end = min(end1, end2)
    if overlap_start > overlap_end:
        return None
    return (overlap_start, overlap_end)


def overlap_length(range1, range2):
    """Length of the shared interval, zero when the ranges do not meet."""
    shared = range_overlap(range1, range2)
    if shared is None:
        return 0.0
    return shared[1] - shared[0]


def overlap_fraction(range1, range2):
    """Share of range1 that is covered by range2, within the unit interval."""
    start, end = normalize(range1)
    span = end - start
    if span == 0:
        if range_overlap(range1, range2) is None:
            return 0.0
        return 1.0
    return overlap_length(range1, range2) / span


def midpoint(rng):
    """Centre of a range, used to report where the overlap sits."""
    start, end = normalize(rng)
    return (start + end) * 0.5


def format_range(rng):
    if rng is None:
        return "none"
    start, end = rng
    return "[{0:g}, {1:g}]".format(start, end)


def classify(shared, fraction):
    if fraction >= 1.0:
        return "contained"
    if fraction >= 0.75:
        return "mostly overlapping"
    if fraction > 0.25:
        return "partly overlapping"
    if shared is not None:
        return "barely touching"
    return "disjoint"


def describe(range1, range2):
    """One-line human readable report about how two ranges relate."""
    shared = range_overlap(range1, range2)
    fraction = overlap_fraction(range1, range2)
    centre = "n/a"
    if shared is not None:
        centre = "{0:g}".format(midpoint(shared))
    return "{0} vs {1} -> {2} ({3}, {4:.0%} of first, centre {5})".format(
        format_range(normalize(range1)),
        format_range(normalize(range2)),
        format_range(shared),
        classify(shared, fraction),
        fraction,
        centre,
    )


def main():
    unit = (0, 2.25)
    half = (0.5, 1)
    pairs = [
        ((1, 5), (3, 7)),
        ((1, 3), (5, 7)),
        (unit, half),
        ((-4, 4), (0.75, 9)),
        ((2, 2), (1.5, 3)),
        ((10, 6), (6, 10)),
    ]
    for first, second in pairs:
        print(describe(first, second))


if __name__ == "__main__":
    main()

