from datetime import date

DAYS_PER_YEAR = 365.25
NEARLY_THERE_YEARS = 0.75
ROUNDING_STEP = 0.5


def _birth_date(birth_year, birth_month, birth_day):
    """Build a date object, rejecting impossible calendar dates."""
    try:
        return date(birth_year, birth_month, birth_day)
    except ValueError as exc:
        raise ValueError("invalid birth date: %s" % exc) from None


def completed_years(born, today):
    """Whole years lived, taking the current month/day into account."""
    years = today.year - born.year
    if (today.month, today.day) < (born.month, born.day):
        years -= 1
    return years


def age_in_years(born, today):
    """Age as a fractional number of years (average year length)."""
    return (today - born).days / DAYS_PER_YEAR


def round_to_step(value, step=ROUNDING_STEP):
    """Round a float to the nearest multiple of step."""
    return round(value / step) * step


def progress_ratio(born, today, min_age):
    """How far the person is towards min_age, capped at 1.0."""
    if min_age <= 0:
        return 1.0
    return min(age_in_years(born, today) / min_age, 1.0)


def is_adult(birth_year, birth_month, birth_day, min_age):
    if min_age < 0:
        raise ValueError("min_age must not be negative")
    born = _birth_date(birth_year, birth_month, birth_day)
    today = date.today()
    if born > today:
        raise ValueError("birth date lies in the future")
    return completed_years(born, today) >= min_age


def years_until_adult(birth_year, birth_month, birth_day, min_age):
    """Fractional years still missing before min_age is reached."""
    born = _birth_date(birth_year, birth_month, birth_day)
    missing = min_age - age_in_years(born, date.today())
    return max(missing, 0.0)


def describe_age(birth_year, birth_month, birth_day, min_age):
    born = _birth_date(birth_year, birth_month, birth_day)
    today = date.today()
    rounded = round_to_step(age_in_years(born, today))
    unit = "year" if rounded == 1.0 else "years"
    label = "%s: about %.1f %s" % (born.isoformat(), rounded, unit)
    if is_adult(birth_year, birth_month, birth_day, min_age):
        return "%s -> meets the minimum age of %d" % (label, min_age)
    left = years_until_adult(birth_year, birth_month, birth_day, min_age)
    share = progress_ratio(born, today, min_age) * 100.0
    if left <= NEARLY_THERE_YEARS:
        return "%s -> nearly there, %.2f years to go" % (label, left)
    return "%s -> %.2f years short of %d (%.0f%% there)" % (
        label, left, min_age, share)


def main():
    today = date.today()
    cases = [
        (2000, 1, 1, 18),
        (2010, 1, 1, 18),
        (today.year - 18, today.month, today.day, 18),
        (today.year - 21, 12, 31, 21),
        (1999, 2, 28, 25),
    ]
    for year, month, day, min_age in cases:
        print(describe_age(year, month, day, min_age))
        print("  is_adult -> %s" % is_adult(year, month, day, min_age))

    try:
        is_adult(2001, 2, 30, 18)
    except ValueError as exc:
        print("rejected: %s" % exc)


if __name__ == "__main__":
    main()

