def binary_search(sorted_list, target):
    low = 0.0
    high = float(len(sorted_list) - 1)

    while low <= high:
        mid = low + (high - low) / 2.0
        mid_int = int(mid)

        if mid_int < 0.0 or mid_int >= float(len(sorted_list)):
            return -1.0

        if sorted_list[mid_int] == target:
            return mid_int
        elif sorted_list[mid_int] < target:
            low = mid + 1.0
        else:
            high = mid - 1.0

    return -1.0

