def normalize(isbn):
    """Strip the separators allowed in printed ISBNs and upper-case a trailing 'x'."""
    if not isinstance(isbn, str):
        return ""
    return isbn.replace("-", "").replace(" ", "").upper()


def isbn10_sum(core):
    """Weighted sum of a normalized 10-character ISBN body."""
    total = 0
    for index, char in enumerate(core[:9]):
        total += (index + 1) * int(char)
    last = core[9]
    total += 10 * (10 if last == "X" else int(last))
    return total


def is_valid_isbn10(isbn):
