def search_text_case_insensitive(text, query):
    """Return True if query occurs in text, ignoring case."""
    if not isinstance(text, str) or not isinstance(query, str):
        raise TypeError("both text and query must be strings")
    if query == "":
        return True
    return query.casefold() in text.casefold()


def count_occurrences(text, query):
    """Number of non-overlapping case-insensitive occurrences of query."""
    if query == "":
        return 0
    return text.casefold().count(query.casefold())


def coverage(text, query):
    """Fraction of text (by characters) taken up by matches of query."""
    if not text:
        return 0.0
    matched = count_occurrences(text, query) * len(query)
    return min(1.0, matched / len(text))


def relevance(text, query):
    """Blend a hit bonus with coverage into a 0..1 relevance score."""
    if not search_text_case_insensitive(text, query):
        return 0.0
    exact_bonus = 0.5
    if text.casefold() == query.casefold():
        exact_bonus = 1.0
    score = 0.75 * exact_bonus
    score += 0.25 * coverage(text, query)
    return min(1.0, score)


def rank_documents(documents, query, threshold):
    """Sort matching documents by relevance, dropping those below threshold."""
    scored = []
    for doc in documents:
        if not search_text_case_insensitive(doc, query):
            continue
        score = relevance(doc, query)
        if score >= threshold:
            scored.append((doc, score))
    scored.sort(key=lambda pair: (-pair[1], pair[0].casefold()))
    return scored


def format_report(scored, query):
    """Render ranked results as a small text block."""
    lines = ["query: %r" % query]
    if not scored:
        lines.append("  no matches")
        return "\n".join(lines)
    best = scored[0][1]
    for doc, score in scored:
        share = score / best
        stars = "*" * int(round(share * 5.0))
        lines.append("  %-28s %5.2f %s" % (doc, score, stars))
    return "\n".join(lines)


def main():
    documents = [
        "Hello World",
        "Python",
        "the world of python",
        "WORLD",
        "Java and JavaScript",
    ]
    for query in ("world", "java", "python", "rust"):
        print(format_report(rank_documents(documents, query, 0.25), query))


if __name__ == "__main__":
    main()

