def parse_numbers(text):
    """Turn a free-form string of numbers into a list of ints/floats."""
    numbers = []
    for token in text.replace(",", " ").split():
        value = float(token)
        if value == int(value):
            value = int(value)
        numbers.append(value)
    return numbers


def count_values(data):
    counts = {}
    for value in data:
        counts[value] = counts.get(value, 0) + 1
    return counts


def calculate_mode(data):
    """Return a list with the most frequently occurring value(s)."""
    if not data:
        return []
    counts = count_values(data)
    highest = max(counts.values())
    return [value for value, times in counts.items() if times == highest]


def calculate_median(data):
    if not data:
        return None
    ordered = sorted(data)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) * 0.5


def calculate_mean(data):
    if not data:
        return None
    return sum(data) / len(data)


def midrange(data):
    if not data:
        return None
    return (min(data) + max(data)) * 0.5


def modal_share(data):
    """Fraction of the sample covered by all modal values together."""
    if not data:
        return 0.0
    counts = count_values(data)
    modes = calculate_mode(data)
    return sum(counts[value] for value in modes) / len(data)


def classify_share(share):
    if share >= 0.75:
        return "overwhelming"
    if share >= 0.5:
        return "dominant"
    if share >= 0.25:
        return "notable"
    return "weak"


def describe(data):
    modes = sorted(calculate_mode(data))
    if not modes:
        return "empty sample: no mode, no centre"
    share = modal_share(data)
    lines = [
        "sample size: %d" % len(data),
        "mode(s): %s" % ", ".join(str(value) for value in modes),
        "modal share: %.1f%% (%s)" % (share * 100.0, classify_share(share)),
        "mean: %.3f" % calculate_mean(data),
        "median: %s" % calculate_median(data),
        "midrange: %s" % midrange(data),
    ]
    if len(modes) > 1:
        lines.append("spread between modes: %s" % (modes[-1] - modes[0]))
    return "\n".join(lines)


def main():
    samples = [
        "1 2 2 3 3 3 4",
        "1, 1, 2, 2, 3",
        "2.5 2.5 1.25 4.0 2.5",
        "7",
        "",
    ]
    for raw in samples:
        data = parse_numbers(raw)
        print("input: [%s]" % ", ".join(str(value) for value in data))
        print("calculate_mode -> %s" % calculate_mode(data))
        print(describe(data))
        print("-" * 32)


if __name__ == "__main__":
    main()

