import math


def reverse_integer(n):
    """Reverse the digits of an integer, preserving the sign."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("reverse_integer expects a plain int")
    sign = -1 if n < 0 else 1
    reversed_digits = int(str(abs(n))[::-1])
    return sign * reversed_digits


def digit_mean(n):
    """Average value of the decimal digits of n."""
    digits = [int(ch) for ch in str(abs(n))]
    return sum(digits) / len(digits)


def growth_ratio(original, reversed_value):
    """How much larger the reversed magnitude is than the original one."""
    if original == 0:
        return 1.0
    return abs(reversed_value) / abs(original)


def round_half_up(value, places=2):
    """Round away from zero on exact halves, unlike Python's banker rounding."""
    factor = 10.0 ** places
    if value < 0:
        return -math.floor(-value * factor + 0.5) / factor
    return math.floor(value * factor + 0.5) / factor


def classify_ratio(ratio):
    if ratio > 1.0:
        return "grows"
    if ratio < 1.0:
        return "shrinks"
    return "unchanged"


def classify_digits(mean):
    """4.5 is the mean of a uniform digit distribution."""
    if mean > 4.5:
        return "high digits"
    if mean < 4.5:
        return "low digits"
    return "balanced digits"


def describe(n):
    rev = reverse_integer(n)
    ratio = growth_ratio(n, rev)
    mean = digit_mean(n)
    return "{:>8} -> {:>8}  ratio {:>6}  ({}, mean {}, {})".format(
        n,
        rev,
        round_half_up(ratio),
        classify_ratio(ratio),
        round_half_up(mean, 1),
        classify_digits(mean),
    )


def main():
    samples = [123, -456, 0, 1200, -9, 100000, 45, 8080]
    for value in samples:
        print(describe(value))

    ratios = [growth_ratio(v, reverse_integer(v)) for v in samples]
    average = sum(ratios) / len(ratios)
    spread = max(ratios) - min(ratios)
    print("average ratio:", round_half_up(average, 3))
    print("ratio spread:", round_half_up(spread, 3))
    if spread > 2.0:
        print("magnitudes vary widely across the sample")


if __name__ == "__main__":
    main()

