import math


def calculate_mean(numbers):
    """Arithmetic mean of a non-empty sequence of numbers."""
    total = 0.0
    for value in numbers:
        total += value
    return total / len(numbers)


def calculate_sample_std_dev(numbers):
    """Sample standard deviation (Bessel-corrected); 0.0 for tiny inputs."""
    count = len(numbers)
    if count < 2:
        return 0.0
    mean = calculate_mean(numbers)
    squared_error = 0.0
    for value in numbers:
        difference = value - mean
        squared_error += difference * difference
    variance = squared_error / (count - 1.0)
    return variance ** 0.5


def calculate_median(numbers):
    """Middle value of the sorted sample, averaging the two central items."""
    ordered = sorted(numbers)
    count = len(ordered)
    middle = count // 2
    if count % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def coefficient_of_variation(numbers):
    """Relative dispersion in percent; 0.0 when the mean is zero."""
    mean = calculate_mean(numbers)
    if math.isclose(mean, 0.0):
        return 0.0
    return 100.0 * calculate_sample_std_dev(numbers) / abs(mean)


def z_scores(numbers):
    """Standardised values of the sample, all zero when there is no spread."""
    std_dev = calculate_sample_std_dev(numbers)
    mean = calculate_mean(numbers)
    if std_dev == 0.0:
        return [0.0 for _ in numbers]
    return [(value - mean) / std_dev for value in numbers]


def outliers(numbers, threshold=2.0):
    """Values whose standardised distance from the mean exceeds threshold."""
    scores = z_scores(numbers)
    return [value for value, score in zip(numbers, scores) if abs(score) > threshold]


def summarize(numbers):
    """Human-readable one-line report for a sample."""
    if not numbers:
        return "empty sample"
    parts = [
        "n=%d" % len(numbers),
        "mean=%.4f" % calculate_mean(numbers),
        "median=%.4f" % calculate_median(numbers),
        "sd=%.4f" % calculate_sample_std_dev(numbers),
        "cv=%.2f%%" % coefficient_of_variation(numbers),
    ]
    extreme = outliers(numbers)
    if extreme:
        parts.append("outliers=%s" % extreme)
    return ", ".join(parts)


def main():
    reaction_times = [
        0.31,
        0.29,
        0.34,
        0.30,
        0.33,
        1.42,
    ]
    for sample in ([1, 2, 3], [10, 20, 30, 40], [42], [], reaction_times):
        print(summarize(sample))


if __name__ == "__main__":
    main()

