import sys


def validate_points(points):
    """Check that the input is a sequence of at least two real numbers."""
    if not isinstance(points, (list, tuple)):
        raise TypeError("points must be a list or tuple")
    if len(points) < 2:
        raise ValueError("need at least two points to form a pair")
    for value in points:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("points must contain only ints or floats")


def find_closest_pair_1d(points):
    """Return the two points separated by the smallest distance."""
    validate_points(points)
    ordered = sorted(points)
    best = (ordered[0], ordered[1])
    best_gap = ordered[1] - ordered[0]
    for index in range(1, len(ordered) - 1):
        left = ordered[index]
        right = ordered[index + 1]
        if right - left < best_gap:
            best_gap = right - left
            best = (left, right)
    return best


def pair_midpoint(pair):
    """Coordinate lying halfway between the two members of a pair."""
    return (pair[0] + pair[1]) / 2.0


def suggested_step(points, fraction=0.5):
    """Sampling step small enough to still separate the tightest pair."""
    pair = find_closest_pair_1d(points)
    return abs(pair[1] - pair[0]) * fraction


def average_gap(points):
    """Mean distance between neighbours once the points are sorted."""
    validate_points(points)
    ordered = sorted(points)
    return (ordered[-1] - ordered[0]) / (len(ordered) - 1)


def tightness(points):
    """Smallest gap divided by the mean gap; zero when all points coincide."""
    mean = average_gap(points)
    if mean == 0:
        return 0.0
    pair = find_closest_pair_1d(points)
    return abs(pair[1] - pair[0]) / mean


def classify(points):
    """Label the sample by how much the tightest pair beats the mean gap."""
    ratio = tightness(points)
    if ratio < 0.25:
        return "clustered"
    if ratio < 0.75:
        return "uneven"
    return "even"


def parse_points(tokens):
    """Turn command line or stdin tokens into a list of numbers."""
    values = []
    for token in tokens:
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("not a number: " + token)
    return values


def describe(points):
    """Build a one-line report about the tightest pair in the sample."""
    pair = find_closest_pair_1d(points)
    return ("closest={0} gap={1:.3f} mid={2:.3f} mean_gap={3:.3f} "
            "step={4:.3f} ratio={5:.1f}% [{6}]").format(
                pair, abs(pair[1] - pair[0]), pair_midpoint(pair),
                average_gap(points), suggested_step(points),
                100.0 * tightness(points), classify(points))


def main(argv):
    tokens = argv[1:]
    if not tokens:
        tokens = sys.stdin.read().replace(",", " ").split()
    try:
        print(describe(parse_points(tokens)))
    except (TypeError, ValueError) as error:
        print("error:", error)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

