import math


def get_quadrant(x, y):
    """Return the quadrant (1-4) of the point, or 0 if it lies on an axis."""
    if x == 0 or y == 0:
        return 0
    if x > 0:
        return 1 if y > 0 else 4
    return 2 if y > 0 else 3


def quadrant_name(quadrant):
    names = {
        0: "on an axis",
        1: "upper right",
        2: "upper left",
        3: "lower left",
        4: "lower right",
    }
    return names[quadrant]


def midpoint(p, q):
    """Midpoint of the segment joining two points."""
    mx = (p[0] + q[0]) * 0.5
    my = (p[1] + q[1]) * 0.5
    return mx, my


def scaled(p, factor):
    return p[0] * factor, p[1] * factor


def polar_angle(x, y):
    """Angle of the point measured counter-clockwise from the positive x axis."""
    angle = math.degrees(math.atan2(y, x))
    if angle < 0:
        angle += 360.0
    return angle


def percentage(count, total):
    if total == 0:
        return 0.0
    return 100.0 * count / total


def format_point(p):
    return "({0:.2f}, {1:.2f})".format(p[0], p[1])


def describe_point(p):
    x, y = p
    quadrant = get_quadrant(x, y)
    radius = math.hypot(x, y)
    if radius == 0.0:
        return "{0} is the origin".format(format_point(p))
    return "{0} -> quadrant {1} ({2}), r={3:.3f}, theta={4:.1f} deg".format(
        format_point(p), quadrant, quadrant_name(quadrant), radius, polar_angle(x, y)
    )


def quadrant_report(points):
    counts = {q: 0 for q in range(5)}
    for x, y in points:
        counts[get_quadrant(x, y)] += 1
    lines = []
    for quadrant in range(5):
        share = percentage(counts[quadrant], len(points))
        lines.append(
            "quadrant {0} ({1}): {2} point(s), {3:.1f}%".format(
                quadrant, quadrant_name(quadrant), counts[quadrant], share
            )
        )
    return lines


def main():
    points = [
        (3, 5),
        (-2, 0),
        (1, -4.5),
        (-2.25, 6),
        (-0.75, -3),
        (0.5, 2),
        (0, 0),
    ]
    for point in points:
        print(describe_point(point))
    print("midpoint of first two: " + format_point(midpoint(points[0], points[1])))
    halfway = scaled(points[3], 0.5)
    print("half of {0}: {1}".format(format_point(points[3]), format_point(halfway)))
    stretched = scaled(points[5], 2.25)
    print("stretched {0}: quadrant {1}".format(format_point(stretched), get_quadrant(*stretched)))
    for line in quadrant_report(points):
        print(line)


if __name__ == "__main__":
    main()

