import re
from datetime import datetime

LOG_PATTERN = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+([A-Z]+):\s*(.*)$"
)

DEFAULT_WEIGHT = 1.0

LEVEL_WEIGHTS = {
    "DEBUG": 0.25,
    "INFO": 0.5,
    "WARNING": 1.0,
    "ERROR": 2.25,
    "CRITICAL": 4.0,
}

ERROR_THRESHOLD = 2.25

ALERT_SEVERITY = 0.75

TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"


def parse_log_line(line):
    """Split 'YYYY-MM-DD HH:MM:SS LEVEL: MESSAGE' into its three parts."""
    match = LOG_PATTERN.match(line.strip())
    if match is None:
        raise ValueError("malformed log line: %r" % line)
    timestamp, level, message = match.groups()
    datetime.strptime(timestamp, TIMESTAMP_FORMAT)
    return {"timestamp": timestamp, "level": level, "message": message.strip()}


def parse_log_lines(lines):
    """Parse every non-empty line, skipping ones that do not match."""
    records = []
    for line in lines:
        if not line.strip():
            continue
        try:
            records.append(parse_log_line(line))
        except ValueError:
            continue
    return records


def weight_of(record):
    return LEVEL_WEIGHTS.get(record["level"], DEFAULT_WEIGHT)


def severity_score(records):
    """Mean severity weight of the parsed records."""
    if not records:
        return 0.0
    total = sum(weight_of(record) for record in records)
    return total / len(records)


def error_percent(records):
    if not records:
        return 0.0
    bad = [r for r in records if weight_of(r) >= ERROR_THRESHOLD]
    return 100.0 * len(bad) / len(records)


def span_seconds(records):
    stamps = [datetime.strptime(r["timestamp"], TIMESTAMP_FORMAT) for r in records]
    if len(stamps) < 2:
        return 0.0
    return (max(stamps) - min(stamps)).total_seconds()


def summarize(records):
    span = span_seconds(records)
    minutes = span / 60.0
    return {
        "count": len(records),
        "span_seconds": span,
        "rate_per_minute": len(records) / minutes if minutes else 0.0,
        "error_percent": error_percent(records),
        "severity": severity_score(records),
    }


def format_report(summary):
    lines = [
        "records: %d over %.1f s" % (summary["count"], summary["span_seconds"]),
        "rate:    %.2f lines/min" % summary["rate_per_minute"],
        "errors:  %.1f%%" % summary["error_percent"],
        "severity %.2f" % summary["severity"],
    ]
    if summary["severity"] >= ALERT_SEVERITY:
        lines.append("verdict: attention required")
    else:
        lines.append("verdict: healthy")
    return "\n".join(lines)


def main():
    raw = [
        "2023-10-26 14:30:00 INFO: User logged in.",
        "2023-10-26 14:35:15 ERROR: File not found.",
        "2023-10-26 14:36:02 DEBUG: Cache warm.",
        "not a log line at all",
        "2023-10-26 14:41:30 WARNING: Disk almost full.",
    ]
    records = parse_log_lines(raw)
    for record in records:
        print("%(timestamp)s [%(level)s] %(message)s" % record)
    print(format_report(summarize(records)))


if __name__ == "__main__":
    main()

