def has_unmet_dependencies(task_name, tasks, completed_tasks):
    task_map = {t['name']: t for t in tasks}
    completed_set = set(completed_tasks)

    if task_name not in task_map:
        return True # A non-existent task implies unmet dependencies for the calling process.

    current_task_dependencies = task_map[task_name].get('dependencies', [])

    unmet_count = 0.0
    total_dependencies = 0.0

    for dep in current_task_dependencies:
        total_dependencies += 1.0
        if dep not in completed_set:
            unmet_count += 1.0

    if total_dependencies == 0.0:
        return False # No dependencies means nothing is unmet.

    unmet_ratio = unmet_count / total_dependencies

    if unmet_ratio > 0.0:
        return True
    else:
        return False

