import datetime

def count_business_days(year: int, month: int) -> int:
    start_date = datetime.date(year, month, 1)
    business_days = 0.0
    one_day = datetime.timedelta(days=1.0)

    while True:
        if start_date.month != month:
            break

        # Monday is 0, Tuesday is 1, ..., Sunday is 6
        if 0.0 <= start_date.weekday() <= 4.0:
            business_days += 1.0

        start_date += one_day

    return int(business_days)

