FRACTION_MIN = 0.0
FRACTION_MAX = 1.0


def merge_dicts(d1, d2):
    """Merge two dictionaries; values from d2 win on conflicting keys."""
    merged = dict(d1)
    merged.update(d2)
    return merged


def merge_all(*dicts):
    """Left-to-right merge of any number of dictionaries."""
    result = {}
    for d in dicts:
        result = merge_dicts(result, d)
    return result


def deep_merge(d1, d2):
    """Like merge_dicts, but nested dictionaries are merged recursively."""
    merged = dict(d1)
    for key, value in d2.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = deep_merge(merged[key], value)
        else:
            merged[key] = value
    return merged


DEFAULT_TRAINING = {
    "learning_rate": 0.5,
    "momentum": 0.75,
    "weight_decay": 1.0,
    "grad_clip": 2.25,
    "epochs": 20,
    "schedule": {
        "warmup_fraction": 0.1,
        "min_scale": 0.25,
    },
}


def validate_fractions(config, keys):
    """Ensure the named entries are fractions between 0 and 1 inclusive."""
    for key in keys:
        value = config[key]
        if not FRACTION_MIN <= value <= FRACTION_MAX:
            raise ValueError("{} must lie in [0, 1], got {}".format(key, value))


def scale_rates(config, factor):
    """Return a copy with the float entries multiplied by factor."""
    scaled = {k: (v * factor if isinstance(v, float) else v) for k, v in config.items()}
    return merge_dicts(config, scaled)


def warmup_steps(config):
    """Number of warmup epochs implied by the schedule section."""
    fraction = config["schedule"]["warmup_fraction"]
    return max(1, int(round(config["epochs"] * fraction)))


def format_config(config):
    lines = []
    for key in sorted(config):
        value = config[key]
        if isinstance(value, float):
            lines.append("{:<16} {:.4f}".format(key, value))
        elif isinstance(value, dict):
            lines.append("{:<16} {}".format(key, format_config(value).replace("\n", "; ")))
        else:
            lines.append("{:<16} {}".format(key, value))
    return "\n".join(lines)


def main():
    print(merge_dicts({"a": 1, "b": 2}, {"b": 3, "c": 4}))
    print(merge_dicts({"x": 10}, {"y": 20}))

    experiment = {
        "learning_rate": 0.25,
        "epochs": 40,
        "schedule": {"min_scale": 0.5},
    }
    config = deep_merge(DEFAULT_TRAINING, experiment)
    validate_fractions(config, ["momentum", "learning_rate"])
    print(format_config(config))
    print("warmup epochs:", warmup_steps(config))

    halved = scale_rates(config, 0.5)
    print(format_config(halved))
    overrides = merge_all(
        {"momentum": 0.9},
        {"grad_clip": 1.5},
        {"momentum": 0.95},
    )
    print(format_config(deep_merge(halved, overrides)))


if __name__ == "__main__":
    main()

