PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def validate(s):
    """Reject anything that is not a bracket character."""
    bad = [c for c in s if c not in PAIRS and c not in OPENERS]
    if bad:
        raise ValueError("unexpected characters: " + "".join(sorted(set(bad))))
    return s


def is_balanced(s):
    stack = []
    for c in validate(s):
        if c in OPENERS:
            stack.append(c)
        elif not stack or stack.pop() != PAIRS[c]:
            return False
    return not stack


def match_ratio(s):
    """Fraction of brackets that take part in a correct pair."""
    validate(s)
    if not s:
        return 1.0
    stack = []
    matched = 0
    for c in s:
        if c in OPENERS:
            stack.append(c)
        elif stack and stack[-1] == PAIRS[c]:
            stack.pop()
            matched += 2
    return matched / len(s)


def rate(s):
    if is_balanced(s):
        return "balanced"
    ratio = match_ratio(s)
    if ratio >= 0.75:
        return "nearly balanced"
    if ratio >= 0.5:
        return "partly matched"
    return "broken"


def max_depth(s):
    depth = 0
    best = 0
    for c in validate(s):
        if c in OPENERS:
            depth += 1
            best = max(best, depth)
        else:
            depth -= 1
    return best


def summarize(samples):
    if not samples:
        return {
            "balanced_rate": 0.0,
            "mean_depth": 0.0,
        }
    good = sum(1 for s in samples if is_balanced(s))
    depths = [max_depth(s) for s in samples]
    return {
        "balanced_rate": good / len(samples),
        "mean_depth": sum(depths) / len(depths),
    }


def main():
    samples = ["({[]})", "([)]", "", "(((", "{}[]()", "([]{})[", "[[{()}]]"]
    for s in samples:
        print("%-10s balanced=%-5s depth=%d ratio=%.2f %s"
              % (s or "<empty>", is_balanced(s), max_depth(s),
                 match_ratio(s), rate(s)))
    stats = summarize(samples)
    print("balanced rate: %.2f" % stats["balanced_rate"])
    print("mean depth:    %.2f" % stats["mean_depth"])
    if stats["mean_depth"] >= 2.25:
        print("sample set is deeply nested")


if __name__ == "__main__":
    main()

