def _validate(num):
    if isinstance(num, bool) or not isinstance(num, int):
        raise TypeError("num must be an integer")
    if num < 1:
        raise ValueError("num must be a positive integer")


def proper_divisors(num):
    """Return the sorted proper positive divisors of num."""
    _validate(num)
    if num == 1:
        return []
    divisors = {1}
    limit = int(num ** 0.5)
    for candidate in range(2, limit + 1):
        if num % candidate == 0:
            divisors.add(candidate)
            divisors.add(num // candidate)
    divisors.discard(num)
    return sorted(divisors)


def is_perfect_number(num):
    """True when num equals the sum of its proper positive divisors."""
    return num > 1 and sum(proper_divisors(num)) == num


def abundancy_index(num):
    """sigma(num) / num, which is exactly 2.0 for perfect numbers."""
    return (num + sum(proper_divisors(num))) / num


def classify(num):
    divisor_total = sum(proper_divisors(num))
    if divisor_total < num:
        return "deficient"
    if divisor_total > num:
        return "abundant"
    return "perfect"


def reciprocal_divisor_sum(num):
    """Sum of 1/d over all divisors of num; approaches 2.0 for perfect numbers."""
    total = 1.0 / num
    for divisor in proper_divisors(num):
        total += 1.0 / divisor
    return total


def euclid_euler_form(num):
    """Return (p, mersenne_prime) with num == 2**(p-1) * (2**p - 1), else None."""
    if not is_perfect_number(num):
        return None
    exponent = 2
    while 2 ** (exponent - 1) <= num:
        mersenne = 2 ** exponent - 1
        if 2 ** (exponent - 1) * mersenne == num:
            return exponent, mersenne
        exponent += 1
    return None


def report_line(num):
    divisors = proper_divisors(num)
    shown = ", ".join(str(d) for d in divisors) if divisors else "-"
    percent = 100.0 * sum(divisors) / num
    return "{:4d}  {:<9s}  sigma/n={:5.3f}  sum={:5.1f}% of n  divisors: {}".format(
        num, classify(num), abundancy_index(num), percent, shown
    )


def main():
    for num in range(1, 31):
        print(report_line(num))

    tolerance = 1.0e-9
    for num in (6, 28, 496, 8128):
        form = euclid_euler_form(num)
        reciprocal_gap = abs(reciprocal_divisor_sum(num) - 2.0)
        print(
            "{} is perfect: {}, 2**(p-1)*(2**p-1) with p={}, "
            "half of sigma = {:.1f}, reciprocal check {}".format(
                num,
                is_perfect_number(num),
                form[0],
                0.5 * (num + sum(proper_divisors(num))),
                "ok" if reciprocal_gap < tolerance else "failed",
            )
        )


if __name__ == "__main__":
    main()

