def char_frequencies(s):
    """Count characters in order of first appearance."""
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def first_non_repeating_char(s):
    """Return the first character that occurs exactly once, or '' if none."""
    if not isinstance(s, str):
        raise TypeError("expected a string")
    counts = char_frequencies(s)
    for ch in s:
        if counts[ch] == 1:
            return ch
    return ""


def uniqueness_ratio(s):
    """Fraction of distinct characters that appear exactly once."""
    counts = char_frequencies(s)
    if not counts:
        return 0.0
    singles = sum(1 for n in counts.values() if n == 1)
    return singles / len(counts)


def average_repeat(s):
    """Mean number of occurrences per distinct character."""
    counts = char_frequencies(s)
    if not counts:
        return 0.0
    return len(s) / len(counts)


def dominant_share(s):
    """Share of the string taken by its most frequent character."""
    counts = char_frequencies(s)
    if not counts:
        return 0.0
    return max(counts.values()) / len(s)


def describe_uniqueness(ratio):
    if ratio >= 0.75:
        return "mostly unique"
    if ratio >= 0.5:
        return "half unique"
    if ratio > 0.0:
        return "few unique"
    return "all repeated"


def format_percent(value):
    return "{:.1f}%".format(value * 100.0)


def report_line(s):
    ratio = uniqueness_ratio(s)
    found = first_non_repeating_char(s)
    answer = repr(found) if found else "(none)"
    parts = [
        "input={!r}".format(s),
        "first={}".format(answer),
        "unique={}".format(format_percent(ratio)),
        "avg_repeat={:.2f}".format(average_repeat(s)),
        describe_uniqueness(ratio),
    ]
    if dominant_share(s) > 0.5:
        parts.append("dominated by one character")
    return " | ".join(parts)


def main():
    samples = ["aabbcdeeff", "aabbcc", "swiss", "aaaab", "", "xyz"]
    for sample in samples:
        print(report_line(sample))
    overall = sum(uniqueness_ratio(s) for s in samples) / len(samples)
    print("mean uniqueness across samples: {}".format(format_percent(overall)))
    if overall < 0.25:
        print("this sample set is dominated by repeated characters")


if __name__ == "__main__":
    main()

