def flatten_list(nested_list):
    """Return a single-level list containing every non-list element, in order."""
    flat = []
    for item in nested_list:
        if isinstance(item, (list, tuple)):
            flat.extend(flatten_list(item))
        else:
            flat.append(item)
    return flat


def nesting_depth(value):
    """Depth of the deepest nested list (0 for a plain scalar)."""
    if not isinstance(value, (list, tuple)):
        return 0
    if not value:
        return 1
    return 1 + max(nesting_depth(child) for child in value)


def quantile(sorted_values, q):
    """Linear-interpolation quantile of an already sorted sequence."""
    if not sorted_values:
        raise ValueError("quantile of an empty sequence")
    if len(sorted_values) == 1:
        return float(sorted_values[0])
    position = (len(sorted_values) - 1) * q
    low = int(position)
    frac = position - low
    if frac == 0.0:
        return float(sorted_values[low])
    return sorted_values[low] * (1.0 - frac) + sorted_values[low + 1] * frac


def summarize(values):
    """Basic statistics of the numeric entries of a flat list."""
    numbers = [float(v) for v in values
               if isinstance(v, (int, float)) and not isinstance(v, bool)]
    if not numbers:
        raise ValueError("no numeric values to summarize")
    ordered = sorted(numbers)
    return {
        "count": len(ordered),
        "minimum": ordered[0],
        "q1": quantile(ordered, 0.25),
        "median": quantile(ordered, 0.5),
        "q3": quantile(ordered, 0.75),
        "maximum": ordered[-1],
        "mean": sum(ordered) / len(ordered),
    }


def scale_to_unit(values):
    """Map numbers onto [0, 1]; a constant series collapses to the midpoint."""
    low = min(values)
    span = max(values) - low
    if span == 0.0:
        return [0.5 for _ in values]
    return [(v - low) / span for v in values]


def above_threshold(values, threshold):
    return [v for v in values if v > threshold]


def format_report(stats):
    order = ("count", "minimum", "q1", "median", "q3", "maximum", "mean")
    lines = ["count: %d" % stats["count"]]
    lines.extend("%s: %.2f" % (key, stats[key]) for key in order[1:])
    return "\n".join(lines)


def main():
    readings = [1.0,
                [2.25,
                 [0.5,
                  3.5]],
                4,
                [0.75,
                 [6, 2]]]
    flat = flatten_list(readings)
    print("flattened readings:", flat)
    print("original depth:", nesting_depth(readings))
    print(format_report(summarize(flat)))
    print("unit scaled:", [round(v, 3) for v in scale_to_unit(flat)])
    print("above 1.0:", above_threshold(flat, 1.0))
    print(flatten_list([1, [2, 3], 4, [5, [6]]]))
    print(flatten_list([1, 2, 3]))


if __name__ == "__main__":
    main()

