ROMAN_VALUES = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

SYMBOL_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def int_to_roman(num):
    """Convert an integer in 1..3999 to its Roman numeral representation."""
    if isinstance(num, bool) or not isinstance(num, int):
        raise TypeError("num must be an int")
    if num < 1 or num > 3999:
        raise ValueError("num must be between 1 and 3999")
    parts = []
    for value, symbol in ROMAN_VALUES:
        count, num = divmod(num, value)
        parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(numeral):
    """Convert a Roman numeral string back to an integer."""
    total = 0
    previous = 0
    for char in reversed(numeral.upper()):
        if char not in SYMBOL_VALUES:
            raise ValueError("invalid Roman symbol: %r" % char)
        value = SYMBOL_VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    return total


def expansion_ratio(num):
    """Roman characters used per decimal digit of num."""
    return len(int_to_roman(num)) / len(str(num))


def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
