import math


def sieve_primes(limit):
    """Return every prime up to and including limit."""
    if limit < 2:
        return []
    flags = bytearray([1]) * (limit + 1)
    flags[0] = flags[1] = 0
    for i in range(2, int(limit ** 0.5) + 1):
        if flags[i]:
            flags[i * i::i] = bytearray(len(range(i * i, limit + 1, i)))
    return [i for i, is_prime in enumerate(flags) if is_prime]


def upper_bound(n):
    """A safe first guess for a limit containing at least n primes."""
    if n < 6:
        return 15
    x = float(n)
    return int(x * (math.log(x) + math.log(math.log(x)))) + 1


def nth_prime(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be a positive integer")
    limit = upper_bound(n)
    while True:
        primes = sieve_primes(limit)
        if len(primes) >= n:
            return primes[n - 1]
        limit = int(limit * 2.25) + 1


def average_gap(primes):
    """Mean distance between consecutive primes in the list."""
    if len(primes) < 2:
        return 0.0
    return (primes[-1] - primes[0]) / (len(primes) - 1.0)


def li_estimate(x):
    """Asymptotic estimate of how many primes are below x."""
    if x < 2:
        return 0.0
    log_x = math.log(x)
    series = 1.0
    series += 1 / log_x
    series += 2 / (log_x * log_x)
    return x / log_x * series


def density_percent(count, limit):
    return 100.0 * count / limit


def accuracy_label(ratio):
    error = abs(ratio - 1.0)
    if error <= 0.05:
        return "excellent"
    if error <= 0.25:
        return "good"
    return "rough"


def report(n):
    prime = nth_prime(n)
    primes = sieve_primes(prime)
    ratio = li_estimate(prime) / n
    return "{:>7} {:>9} {:>9.3f} {:>9.2f}% {:>7.3f} {}".format(
        n, prime, average_gap(primes), density_percent(len(primes), prime),
        ratio, accuracy_label(ratio))


def main():
    print("{:>7} {:>9} {:>9} {:>10} {:>7} {}".format(
        "n", "nth prime", "avg gap", "density", "est/n", "estimate"))
    for n in (1, 5, 10, 100, 1000, 10000, 100000):
        print(report(n))


if __name__ == "__main__":
    main()

