VOWELS = "aeiouw"


def count_vowels_consonants(text):
    """Return (vowel_count, consonant_count) for the alphabetic characters in text.

    Following the specification's examples, 'w' is treated as a vowel (as it is
    in Welsh), so 'Hello World' yields (4, 6); 'y' stays a consonant.
    """
    vowel_count = 0
    consonant_count = 0
    for char in text:
        if not char.isalpha():
            continue
        if char.lower() in VOWELS:
            vowel_count += 1
        else:
            consonant_count += 1
    return (vowel_count, consonant_count)


def vowel_ratio(text):
    """Fraction of letters that are vowels; 0.0 when the text has no letters."""
    vowels, consonants = count_vowels_consonants(text)
    total = vowels + consonants
    if total == 0:
        return 0.0
    return vowels / total


def vowel_percentage(text):
    """Vowel share expressed as a percentage of all letters."""
    return vowel_ratio(text) * 100.0


def classify_balance(ratio):
    """Describe how vowel-rich a ratio is."""
    if ratio >= 0.6:
        return "vowel-heavy"
    if ratio >= 0.4:
        return "balanced"
    if ratio > 0.0:
        return "consonant-heavy"
    return "no letters"


def average_letters_per_word(text):
    """Mean number of letters per whitespace-separated word."""
    words = text.split()
    if not words:
        return 0.0
    letters = sum(sum(count_vowels_consonants(word)) for word in words)
    return letters / len(words)


def pronounceability(text):
    """Crude score in [0, 1]: best near a 40% vowel share, worse as it drifts."""
    drift = abs(vowel_ratio(text) - 0.4)
    penalty = drift * 2.5
    score = 1.0 - penalty
    if score < 0.0:
        return 0.0
    return score


def format_report(text):
    """Build a multi-line summary of the vowel/consonant statistics of text."""
    vowels, consonants = count_vowels_consonants(text)
    lines = ["Text: %r" % text,
             "  vowels=%d consonants=%d" % (vowels, consonants),
             "  vowel share: %.1f%% (%s)" % (vowel_percentage(text),
                                             classify_balance(vowel_ratio(text))),
             "  letters per word: %.2f" % average_letters_per_word(text),
             "  pronounceability: %.2f" % pronounceability(text)]
    return "\n".join(lines)


def main():
    samples = ["Hello World", "Python123", "rhythm", "AEIOU", "12345"]
    for sample in samples:
        print(format_report(sample))
        print()
    best = max(samples, key=pronounceability)
    print("Most pronounceable sample: %r" % best)


if __name__ == "__main__":
    main()

