class QueueEmptyError(IndexError):
    """Raised when a dequeue is attempted on an empty queue."""


class SimpleQueue:
    """A first-in, first-out queue backed by a plain Python list."""

    def __init__(self, items=None):
        self._items = list(items) if items is not None else []

    def __len__(self):
        return len(self._items)

    def is_empty(self):
        return not self._items

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            raise QueueEmptyError("dequeue from an empty queue")
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            raise QueueEmptyError("peek at an empty queue")
        return self._items[0]


def simulate_single_server(arrivals, services):
    """Serve customers in arrival order, returning one record per customer."""
    if len(arrivals) != len(services):
        raise ValueError("arrivals and services must have the same length")
    waiting = SimpleQueue()
    for index, (arrival, service) in enumerate(zip(arrivals, services), start=1):
        if arrival < 0.0:
            raise ValueError("arrival times cannot be negative")
        if service <= 0.0:
            raise ValueError("service durations must be positive")
        waiting.enqueue((index, float(arrival), float(service)))
    clock = 0.0
    records = []
    while not waiting.is_empty():
        index, arrival, service = waiting.dequeue()
        start = max(clock, arrival)
        finish = start + service
        records.append((index, arrival, start - arrival, finish))
        clock = finish
    return records


def average_wait(records):
    if not records:
        return 0.0
    return sum(record[2] for record in records) / len(records)


def idle_time(records):
    total = 0.0
    previous_finish = 0.0
    for _, arrival, _, finish in records:
        total += max(0.0, arrival - previous_finish)
        previous_finish = finish
    return total


def format_report(records, patience=1.0):
    lines = ["cust  arrive   wait  finish  note"]
    for index, arrival, wait, finish in records:
        note = "impatient" if wait > patience else ""
        lines.append(f"{index:>4}  {arrival:6.2f} {wait:6.2f} {finish:7.2f}  {note}")
    lines.append(f"average wait: {average_wait(records):.2f}")
    lines.append(f"server idle:  {idle_time(records):.2f}")
    return "\n".join(lines)


def main():
    arrivals = [
        0.0,
        0.5,
        1.0,
        2.25,
        7.5,
    ]
    services = [
        1.5,
        2.0,
        0.75,
        1.25,
        2.5,
    ]
    records = simulate_single_server(arrivals, services)
    print(format_report(records, patience=0.75))


if __name__ == "__main__":
    main()

