DIGITS = "0123456789"

MOSTLY_DIGITS = 0.75
MIXED = 0.5


def is_all_digits(s):
    """Return True if s is non-empty and every character is a digit."""
    if not s:
        return False
    for ch in s:
        if ch not in DIGITS:
            return False
    return True


def digit_ratio(s):
    """Fraction of characters in s that are digits; 0.0 for an empty string."""
    if not s:
        return 0.0
    hits = sum(1 for ch in s if ch in DIGITS)
    return hits / len(s)


def classify(s):
    """Describe how digit-like s is, using the ratio thresholds."""
    if is_all_digits(s):
        return "all digits"
    ratio = digit_ratio(s)
    if ratio >= MOSTLY_DIGITS:
        return "mostly digits"
    if ratio >= MIXED:
        return "mixed"
    if ratio > 0.0:
        return "few digits"
    return "no digits"


def as_percent(ratio):
    """Format a ratio in the range 0.0 .. 1.0 as a percentage string."""
    return "{:.1f}%".format(ratio * 100.0)


def describe(s):
    """One line of report for a single candidate string."""
    return "{!r:<12} {:<6} {:>7}  {}".format(
        s, str(is_all_digits(s)), as_percent(digit_ratio(s)), classify(s)
    )


def average_ratio(samples):
    """Mean digit ratio over samples, or 0.0 when there is nothing to average."""
    if not samples:
        return 0.0
    total = 0.0
    for s in samples:
        total += digit_ratio(s)
    return total / len(samples)


def summarize(samples):
    """Build the full report: a line per sample plus aggregate figures."""
    lines = [describe(s) for s in samples]
    numeric = [s for s in samples if is_all_digits(s)]
    share = len(numeric) / len(samples) if samples else 0.0
    lines.append("pure numeric strings: {} of {} ({})".format(
        len(numeric), len(samples), as_percent(share)))
    lines.append("average digit ratio: " + as_percent(average_ratio(samples)))
    if share >= MIXED:
        lines.append("verdict: the sample is predominantly numeric")
    else:
        lines.append("verdict: the sample is predominantly non-numeric")
    return "\n".join(lines)


def main():
    samples = ["12345", "123a45", "", "007", "12.5", "9999x", "3-1-4", "42"]
    print(summarize(samples))


if __name__ == "__main__":
    main()

