import math


def prime_factors(n):
    """Return the multiset of prime factors of n in non-decreasing order."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    factors = []
    remaining = n
    while remaining % 2 == 0 and remaining > 1:
        factors.append(2)
        remaining //= 2
    divisor = 3
    while divisor <= remaining ** 0.5:
        if remaining % divisor == 0:
            factors.append(divisor)
            remaining //= divisor
        else:
            divisor += 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def geometric_mean(factors):
    """Average size of the prime factors, weighted multiplicatively."""
    product = 1.0
    for factor in factors:
        product *= factor
    return product ** (1.0 / len(factors))


def factor_counts(factors):
    counts = {}
    for factor in factors:
        counts[factor] = counts.get(factor, 0) + 1
    return counts


def format_factorization(n, factors):
    counts = factor_counts(factors)
    parts = []
    for prime in sorted(counts):
        exponent = counts[prime]
        parts.append(str(prime) if exponent == 1 else f"{prime}^{exponent}")
    return f"{n} = " + " * ".join(parts)


def abc_quality(n, factors):
    """log(n) / log(radical): 1.0 for squarefree n, larger for powerful n."""
    radical = 1
    for prime in factor_counts(factors):
        radical *= prime
    if radical == n:
        return 1.0
    return math.log(n) / math.log(radical)


def smooth_percentage(factors, bound):
    small = [factor for factor in factors if factor <= bound]
    return 100.0 * len(small) / len(factors)


def main():
    bound = 7
    for n in (12, 7, 1, 360, 97, 1024, 5040, 1234567):
        factors = prime_factors(n)
        if not factors:
            print(f"{n} has no prime factors")
            continue
        quality = abc_quality(n, factors)
        print(format_factorization(n, factors))
        print(f"  factors        : {factors}")
        print(f"  geometric mean : {geometric_mean(factors):.3f}")
        print(f"  abc quality    : {quality:.3f}")
        print(f"  {bound}-smooth part  : {smooth_percentage(factors, bound):.1f}%")
        if quality > 1.5:
            print("  strongly powerful (repeated prime factors dominate)")
        elif quality > 1.0:
            print("  partly powerful (some repeated prime factors)")
        else:
            print("  squarefree")


if __name__ == "__main__":
    main()

