VALUE_TOLERANCE = 0.000001


class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right


def build_tree(values):
    """Build a binary tree from a level-order list where None marks a gap."""
    if not values or values[0] is None:
        return None
    root = Node(values[0])
    queue = [root]
    index = 1
    while queue and index < len(values):
        node = queue.pop(0)
        for side in ("left", "right"):
            if index >= len(values):
                break
            value = values[index]
            index += 1
            if value is not None:
                child = Node(value)
                setattr(node, side, child)
                queue.append(child)
    return root


def values_close(first, second, tolerance=VALUE_TOLERANCE):
    return abs(first - second) <= tolerance


def _is_mirror(left, right):
    if left is None and right is None:
        return True
    if left is None or right is None:
        return False
    if not values_close(left.value, right.value):
        return False
    return _is_mirror(left.left, right.right) and _is_mirror(left.right, right.left)


def is_symmetric(root):
    return root is None or _is_mirror(root.left, root.right)


def count_nodes(node):
    if node is None:
        return 0
    return 1 + count_nodes(node.left) + count_nodes(node.right)


def tree_depth(node):
    if node is None:
        return 0
    return 1 + max(tree_depth(node.left), tree_depth(node.right))


def average_value(node):
    total = count_nodes(node)
    if total == 0:
        return 0.0
    return _sum_values(node) / total


def _sum_values(node):
    if node is None:
        return 0
    return node.value + _sum_values(node.left) + _sum_values(node.right)


def balance_ratio(root):
    """Fraction of non-root nodes living in the left subtree."""
    if root is None:
        return 0.5
    left = count_nodes(root.left)
    total = left + count_nodes(root.right)
    if total == 0:
        return 0.5
    return left / total


def balance_label(ratio):
    skew = abs(ratio - 0.5)
    if skew <= 0.125:
        return "balanced"
    if skew <= 0.375:
        return "slightly skewed"
    return "heavily skewed"


def symmetry_score(root):
    if is_symmetric(root):
        return 1.0
    skew = abs(balance_ratio(root) - 0.5)
    return round(1.0 - skew - skew, 4)


def report(name, values):
    root = build_tree(values)
    ratio = balance_ratio(root)
    print("%s: %s" % (name, values))
    print("  symmetric : %s" % is_symmetric(root))
    print("  nodes     : %d (depth %d)" % (count_nodes(root), tree_depth(root)))
    print("  mean value: %.2f" % average_value(root))
    print("  left share: %.1f%% (%s)" % (ratio * 100.0, balance_label(ratio)))
    print("  score     : %.4f" % symmetry_score(root))


def main():
    report("example 1", [1, 2, 2, 3, 4, 4, 3])
    report("example 2", [1, 2, 2, None, 3, None, 3])
    report("empty", [])
    report("lopsided", [1, 2, 2, 3, None, None, None, 4])


if __name__ == "__main__":
    main()

