from typing import List, Sequence, Tuple


def _is_number(value) -> bool:
    """True for plain ints and floats (booleans are rejected)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def validate_inputs(nums: Sequence[float], target_sum: float) -> None:
    """Reject anything the sliding-window algorithm cannot handle."""
    if not _is_number(target_sum):
        raise TypeError("target_sum must be a number")
    if target_sum < 0.0:
        raise ValueError("target_sum must be non-negative")
    for index, value in enumerate(nums):
        if not _is_number(value):
            raise TypeError("nums[%d] is not a number" % index)
        if value < 0.0:
            raise ValueError("nums[%d] is negative; only non-negative values allowed" % index)


def tolerance_for(target_sum: float) -> float:
    """Comparison slack so float inputs still match their exact target."""
    return 1e-9 * max(1.0, abs(target_sum))


def subarray_sum(nums: Sequence[float], target_sum: float) -> Tuple[int, int]:
    """Return (start, end) of the first contiguous window summing to target_sum."""
    validate_inputs(nums, target_sum)
    tol = tolerance_for(target_sum)
    start = 0
    window_total = 0.0
    for end, value in enumerate(nums):
        window_total += value
        while window_total > target_sum + tol and start <= end:
            window_total -= nums[start]
            start += 1
        if abs(window_total - target_sum) <= tol:
            return (start, end)
    return (-1, -1)


def describe_window(nums: Sequence[float], target_sum: float) -> str:
    """Human readable report about the window found for target_sum."""
    start, end = subarray_sum(nums, target_sum)
    if start < 0:
        return "target %g: no contiguous window found" % target_sum
    window: List[float] = list(nums[start:end + 1])
    window_total = float(sum(window))
    array_total = float(sum(nums))
    if array_total > 0.0:
        share = 100.0 * window_total / array_total
    else:
        share = 100.0
    mean = window_total / len(window)
    return "target %g: indices %d..%d %s sum=%g share=%.1f%% mean=%.2f" % (
        target_sum, start, end, window, window_total, share, mean)


def parse_numbers(text: str) -> List[float]:
    """Read whitespace separated numbers, e.g. '1 4 20 3 10 5'."""
    return [float(token) for token in text.split()]


def main() -> None:
    cases = [
        ("1 4 20 3 10 5", "33"),
        ("1 4 0 0 3 10 5", "7"),
        ("0.5 1 2.25 0.75", "3.25"),
        ("2.5 0.75 1.25", "2"),
        ("1 2 3", "7"),
        ("0 0 0", "0"),
    ]
    for text, target_text in cases:
        nums = parse_numbers(text)
        print(describe_window(nums, float(target_text)))


if __name__ == "__main__":
    main()

