def normalize_name(full_name):
    """Strip and collapse the whitespace of a full name."""
    if not isinstance(full_name, str):
        raise TypeError("full name must be a string")
    return " ".join(full_name.split())


def name_parts(full_name):
    """Return the individual name words of a full name."""
    return normalize_name(full_name).split()


def get_initials(full_name):
    """Return the uppercase initials of every word in full_name."""
    return "".join(part[0].upper() for part in name_parts(full_name))


def format_initials(initials, separator="."):
    """Render initials as a dotted monogram such as 'J.D.'."""
    if not initials:
        return ""
    return separator.join(initials) + separator


def average_part_length(parts):
    """Mean number of characters per name word."""
    if not parts:
        return 0.0
    return sum(len(part) for part in parts) / len(parts)


def compression_ratio(full_name, initials):
    """Share of the letters that survive the abbreviation."""
    letters = len(normalize_name(full_name).replace(" ", ""))
    if letters == 0:
        return 1.0
    return len(initials) / letters


def describe_compactness(ratio):
    """Verdict on how much the initials shorten the name."""
    if ratio <= 0.25:
        return "very compact"
    if ratio <= 0.5:
        return "compact"
    if ratio <= 0.75:
        return "modest saving"
    return "barely shorter"


def readability_score(parts, ratio):
    """Blend shortening with word length; long words abbreviate best."""
    typical_word = 2.25
    length_factor = average_part_length(parts) / typical_word
    if length_factor > 1:
        length_factor = 1.0
    saving_weight = 0.75
    length_weight = 0.25
    return (1 - ratio) * saving_weight + length_factor * length_weight


def summarise(full_name):
    parts = name_parts(full_name)
    initials = get_initials(full_name)
    ratio = compression_ratio(full_name, initials)
    return {
        "name": normalize_name(full_name),
        "initials": initials,
        "monogram": format_initials(initials),
        "average_word": average_part_length(parts),
        "ratio": ratio,
        "verdict": describe_compactness(ratio),
        "score": readability_score(parts, ratio),
    }


def main():
    names = ["John Doe", "Alice Mary Smith", "  ada   lovelace king  ", "Bo Li"]
    row = "{:<24}{:<8}{:<10}{:>7}{:>7}  {}"
    print(row.format("NAME", "INIT", "MONOGRAM", "RATIO", "SCORE", "VERDICT"))
    reports = [summarise(raw) for raw in names]
    for info in reports:
        print(row.format(info["name"], info["initials"], info["monogram"],
                         "{:.2f}".format(info["ratio"]),
                         "{:.2f}".format(info["score"]), info["verdict"]))
    best = max(reports, key=lambda info: info["score"])
    print("\nbest abbreviation: {} -> {} (score {:.2f})".format(
        best["name"], best["initials"], best["score"]))


if __name__ == "__main__":
    main()

