import re
from collections import Counter

WORD_RE = re.compile(r"[a-z0-9']+")


def word_counts(text):
    """Count occurrences of each word, ignoring case and punctuation."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = WORD_RE.findall(text.lower())
    cleaned = [w.strip("'") for w in words]
    return dict(Counter(w for w in cleaned if w))


def total_words(counts):
    return sum(counts.values())


def frequency_percentages(counts):
    """Map each word to its share of the whole text, in percent."""
    total = total_words(counts)
    if total == 0:
        return {}
