class StackEmptyError(IndexError):
    """Raised when an item is requested from an empty stack."""


class SimpleStack:
    """A last-in, first-out container backed by a plain Python list."""

    def __init__(self, items=None):
        self._items = list(items) if items is not None else []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise StackEmptyError("pop from an empty stack")
        return self._items.pop()

    def is_empty(self):
        return not self._items

    def __repr__(self):
        return "SimpleStack({!r})".format(self._items)


def divide(left, right):
    if right == 0.0:
        raise ZeroDivisionError("division by zero in expression")
    return left / right


BINARY_OPS = {
    "+": lambda left, right: left + right,
    "-": lambda left, right: left - right,
    "*": lambda left, right: left * right,
    "/": divide,
}


def tokenize(text):
    return text.split()


def evaluate_rpn(tokens):
    """Evaluate a postfix expression, using SimpleStack for the operands."""
    stack = SimpleStack()
    for token in tokens:
        if token in BINARY_OPS:
            right = stack.pop()
            left = stack.pop()
            stack.push(BINARY_OPS[token](left, right))
        elif token == "sqrt":
            stack.push(stack.pop() ** 0.5)
        else:
            stack.push(float(token))
    result = stack.pop()
    if not stack.is_empty():
        raise ValueError("leftover operands in {!r}".format(stack))
    return result


def apply_rate(amount, rate):
    return amount * (1.0 + rate)


def format_amount(value):
    scaled = abs(value) * 100.0
    cents = int(scaled + 0.5)
    sign = "-" if value < 0.0 else ""
    return "{}{}.{:02d}".format(sign, cents // 100, cents % 100)


def main():
    readings = [
        1.5,
        2.25,
        3.75,
    ]
    total = evaluate_rpn(tokenize(" ".join(str(r) for r in readings) + " + +"))
    print("total:", format_amount(total))
    mean = evaluate_rpn(tokenize("{} {} /".format(total, len(readings))))
    print("mean:", format_amount(mean))
    print("root of total:", "{:.4f}".format(evaluate_rpn(tokenize("%r sqrt" % total))))
    print("with surcharge:", format_amount(apply_rate(total, 0.075)))

    stack = SimpleStack()
    stack.push(1)
    stack.push(2)
    print("popped:", stack.pop(), stack.pop())
    try:
        stack.pop()
    except StackEmptyError as exc:
        print("error:", exc)


if __name__ == "__main__":
    main()

