import math


def is_power_of_two(n):
    """Return True if n is a positive integer power of two."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be a non-negative integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return n > 0 and n & (n - 1) == 0


def bounding_powers(n):
    """Return the powers of two bracketing n (equal if n is a power of two)."""
    if n < 1:
        raise ValueError("n must be positive to be bracketed")
    lower = 1 << (n.bit_length() - 1)
    upper = lower if lower == n else lower << 1
    return lower, upper


def geometric_midpoint(lower):
    """The value splitting the octave above `lower` evenly on a log scale."""
    return lower * math.sqrt(2.0)


def position_in_octave(n):
    """Where n sits between its bracketing powers of two, in octaves."""
    lower, _upper = bounding_powers(n)
    return math.log2(n / lower)


def octave_cents(n):
    """The same position expressed in cents (1200 cents to an octave)."""
    return 1200.0 * position_in_octave(n)


def nearest_power_of_two(n):
    """Return the power of two closest to n in the multiplicative sense."""
    lower, upper = bounding_powers(n)
    if lower == upper:
        return lower
    return lower if n < geometric_midpoint(lower) else upper


def relative_drift(n):
    """Fractional distance from n to the nearest power of two."""
    near = nearest_power_of_two(n)
    return abs(n - near) / near


def is_near_power_of_two(n, tolerance=0.05):
    """True if n is within `tolerance` of the nearest power of two."""
    return relative_drift(n) <= tolerance


def describe(n):
    """Build a one-line human readable verdict for n."""
    if is_power_of_two(n):
        return "{} is a power of two: 2^{}".format(n, n.bit_length() - 1)
    if n == 0:
        return "0 is not a power of two (no exponent gives zero)"
    side = "above" if position_in_octave(n) > 0.5 else "below"
    near = nearest_power_of_two(n)
    drift = 100.0 * relative_drift(n)
    verdict = "close enough to round" if is_near_power_of_two(n) else "distinct"
    return "{} is not a power of two; it sits {:.0f} cents into its octave, " \
           "{} the midpoint, nearest 2^{} ({:.1f}% away, {})".format(
               n, octave_cents(n), side, near.bit_length() - 1, drift, verdict)


def summarize(values):
    """Report how many of the given values are powers of two."""
    if not values:
        raise ValueError("values must not be empty")
    hits = [v for v in values if is_power_of_two(v)]
    share = 100.0 * len(hits) / len(values)
    close = [v for v in values if v > 0 and is_near_power_of_two(v)]
    offsets = [position_in_octave(v) for v in values if v > 0]
    mean_offset = sum(offsets) / len(offsets)
    return "{} of {} values are powers of two ({:.1f}%), {} are within " \
           "tolerance, mean octave offset {:.2f}".format(
               len(hits), len(values), share, len(close), mean_offset)


def main():
    samples = [0, 1, 2, 3, 12, 16, 17, 1000, 1024, 1536, 1 << 20]
    for value in samples:
        print(describe(value))
    print(summarize(samples))


if __name__ == "__main__":
    main()

